-- ============================================================================
-- CONSOLIDATED BASELINE (answer-model-v2 re-squash, 2026-07-01)
-- ============================================================================
-- Schema-only dump (public + app) of the fully-migrated local DB. This is a
-- RE-SQUASH of the prior form-model-normalization baseline (2026-07-01) that now
-- also folds in the two answer-model-v2 migrations (20260701000000_answer_model_v2_
-- definition + 20260701000010_answer_model_v2_answers), which are deleted. Net new
-- vs the prior baseline: answers typed scalar columns (value_number/date/time,
-- trigger-derived by app.sync_answer_typed_values; value stays canonical), answers
-- answered_at + reserved confidentiality_level, re-keyed answer_selected_options
-- (selections hang off answer_id, not response_id/item_id; guard_submitted_selections
-- + re-keyed reject_invalid_selection), instance-ready answer key
-- (answers.group_instance_id + public.response_group_instances + form_items.
-- parent_item_id), form_items.default_value, and HC080 default-value validation in
-- publish_form_version. Replaces the entire prior migration set. Carried below
-- (dump excludes these; from the live DB) so the squashed baseline is PRIVILEGE-+
-- SCHEMA-identical to the pre-squash history (empty sorted pg_dump diff):
-- (1) storage buckets+object policies, (2) app config feature_flags+app_secrets,
-- (3) global config vocabularies, (4) auth.users triggers, (5) the hardened
-- privilege posture. answer-model-v2 did NOT touch any of the five carried
-- sections, so they are copied verbatim from the prior baseline. Demo rows the old
-- migrations seeded into public.* are NOT carried; seed.sql is the canonical demo
-- data.
-- ============================================================================





SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "app";


ALTER SCHEMA "app" OWNER TO "postgres";


CREATE EXTENSION IF NOT EXISTS "pg_net" WITH SCHEMA "extensions";






COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE EXTENSION IF NOT EXISTS "citext" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";





SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."case_action_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "case_id" "uuid" NOT NULL,
    "source_case_phase_id" "uuid",
    "title" "text" NOT NULL,
    "description" "text",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "assigned_to" "uuid",
    "due_date" "date",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "completed_by" "uuid",
    CONSTRAINT "case_action_items_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'done'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "case_action_items_title_not_blank" CHECK (("btrim"("title") <> ''::"text"))
);


ALTER TABLE "public"."case_action_items" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."advance_action_item_core"("p_action_item_id" "uuid", "p_status" "text") RETURNS "public"."case_action_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_case_id uuid;
  v_assigned_to uuid;
  v_uid uuid := auth.uid();
  v_result public.case_action_items;
begin
  if p_status not in ('open', 'in_progress', 'done', 'cancelled') then
    raise exception 'estado de item inválido' using errcode = 'check_violation';
  end if;

  select case_id, assigned_to into v_case_id, v_assigned_to
  from public.case_action_items where id = p_action_item_id;
  if v_case_id is null then
    raise exception 'item % não encontrado', p_action_item_id using errcode = 'no_data_found';
  end if;

  -- Authority: the assignee, OR a content-writer of the case (coordinator/admin or
  -- a case-write grantee — ADR 0033 D4). HC027 otherwise.
  if not (
    (v_assigned_to is not null and v_assigned_to = v_uid)
    or app.can_write_case_content(v_case_id, v_uid)
  ) then
    raise exception 'você não pode alterar este item de ação' using errcode = 'HC027';
  end if;

  update public.case_action_items
  set status = p_status,
      completed_at = case when p_status = 'done' then coalesce(completed_at, now()) else null end,
      completed_by = case when p_status = 'done' then coalesce(completed_by, v_uid) else null end,
      updated_at = now()
  where id = p_action_item_id
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "app"."advance_action_item_core"("p_action_item_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."capa_action" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "capa_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "owner" "text",
    "assignee_user_id" "uuid",
    "due_date" "date",
    "action_strength" "text" DEFAULT 'intermediaria'::"text" NOT NULL,
    "success_measure" "text",
    "root_cause_id" "uuid",
    "status" "text" DEFAULT 'pendente'::"text" NOT NULL,
    "position" integer NOT NULL,
    "completed_at" timestamp with time zone,
    "completed_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "capa_action_action_strength_check" CHECK (("action_strength" = ANY (ARRAY['forte'::"text", 'intermediaria'::"text", 'fraca'::"text"]))),
    CONSTRAINT "capa_action_status_check" CHECK (("status" = ANY (ARRAY['pendente'::"text", 'em_andamento'::"text", 'concluida'::"text", 'cancelada'::"text"]))),
    CONSTRAINT "capa_action_title_not_blank" CHECK (("btrim"("title") <> ''::"text"))
);


ALTER TABLE "public"."capa_action" OWNER TO "postgres";


COMMENT ON TABLE "public"."capa_action" IS 'CAPA corrective actions (Phase 14d). owner = displayed free-text party; assignee_user_id = the platform user the narrow advance gate keys on. root_cause_id FKs the 14c rca_root_causes(id).';



CREATE OR REPLACE FUNCTION "app"."advance_capa_action_core"("p_action_id" "uuid", "p_status" "text") RETURNS "public"."capa_action"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_assignee uuid;
  v_capa_id uuid;
  v_uid uuid := auth.uid();
  v_result public.capa_action;
begin
  if p_status not in ('pendente', 'em_andamento', 'concluida', 'cancelada') then
    raise exception 'estado de ação inválido' using errcode = 'check_violation';
  end if;

  select assignee_user_id, capa_id into v_assignee, v_capa_id
  from public.capa_action where id = p_action_id;
  if v_capa_id is null then
    raise exception 'ação % não encontrada', p_action_id using errcode = 'no_data_found';
  end if;

  -- BUG-NSP-004: the PQS arm must use can_write_capa, which carries the non-event
  -- fallback (event/rca-sourced → per-org; manual/indicator/audit/meeting → any-org,
  -- since a non-event CAPA has NO org to scope to). The bare
  -- is_pqs_member_of(org_of_event(...)) here made manual-source CAPA actions
  -- unadvanceable by a non-assignee PQS member (NULL event-org → false). Identical
  -- authority to the 8 capa_*_write policies + assert_capa_writable now.
  if not (
    (v_assignee is not null and v_assignee = v_uid)
    or app.can_write_capa(v_capa_id, v_uid)
  ) then
    raise exception 'você não pode alterar esta ação corretiva' using errcode = 'HC050';
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.capa_action
  set status = p_status,
      completed_at = case when p_status = 'concluida' then coalesce(completed_at, now()) else null end,
      completed_by = case when p_status = 'concluida' then coalesce(completed_by, v_uid) else null end,
      updated_at = now()
  where id = p_action_id
  returning * into v_result;
  perform set_config('app.in_safety_rpc', 'off', true);

  return v_result;
end;
$$;


ALTER FUNCTION "app"."advance_capa_action_core"("p_action_id" "uuid", "p_status" "text") OWNER TO "postgres";


