CREATE OR REPLACE FUNCTION "app"."advance_meeting_action_item_core"("p_action_item_id" "uuid", "p_status" "text") RETURNS "public"."meeting_action_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_assigned_to uuid;
  v_uid uuid := auth.uid();
  v_result public.meeting_action_items;
begin
  if p_status not in ('open', 'in_progress', 'done', 'cancelled') then
    raise exception 'estado de item inválido' using errcode = 'check_violation';
  end if;

  select commission_id, assigned_to into v_commission_id, v_assigned_to
  from public.meeting_action_items where id = p_action_item_id;
  if v_commission_id is null then
    raise exception 'item de ação não encontrado' using errcode = 'no_data_found';
  end if;

  if not (
    (v_assigned_to is not null and v_assigned_to = v_uid)
    or app.is_staff_admin_of(v_commission_id)
    or app.is_org_admin_of_commission(v_commission_id)
  ) then
    raise exception 'você não pode alterar este item de ação' using errcode = 'HC037';
  end if;

  update public.meeting_action_items
  set status = p_status,
      completed_at = case when p_status = 'done' then coalesce(completed_at, now()) else null end,
      completed_by = case when p_status = 'done' then coalesce(completed_by, v_uid) else null end,
      updated_at = now()
  where id = p_action_item_id returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "app"."advance_meeting_action_item_core"("p_action_item_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."answer_map"("p_response_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
  with
  -- (a) Scalar answers — non-choice input items only.
  scalars as (
    select a.question_key, a.value
    from public.answers a
    join public.form_items i on i.id = a.item_id
    where a.response_id = p_response_id
      and a.value is not null
      and i.item_type = any (array['free_text','short_text','number','date','time'])
  ),
  -- The selected option codes of this response, sourced through the parent answer
  -- (answer_id -> answers), with the item's question_key + type, ordered by
  -- option.position for the checkbox array.
  selected as (
    select i.question_key,
           i.item_type,
           o.code,
           o.position
    from public.answer_selected_options s
    join public.answers a on a.id = s.answer_id
    join public.form_items i on i.id = a.item_id
    join public.form_item_options o on o.id = s.option_id
    where a.response_id = p_response_id
      and i.item_type = any (array['multiple_choice','dropdown','checkbox'])
  ),
  -- (b) Single-select — exactly one code per question_key as a jsonb string.
  single as (
    select question_key, to_jsonb(min(code)) as value
    from selected
    where item_type = any (array['multiple_choice','dropdown'])
    group by question_key
  ),
  -- (c) Checkbox — a jsonb array of codes ordered by option.position.
  multi as (
    select question_key, jsonb_agg(to_jsonb(code) order by position) as value
    from selected
    where item_type = 'checkbox'
    group by question_key
  ),
  merged as (
    select question_key, value from scalars
    union all
    select question_key, value from single
    union all
    select question_key, value from multi
  )
  select coalesce(jsonb_object_agg(question_key, value), '{}'::jsonb)
  from merged;
$$;


ALTER FUNCTION "app"."answer_map"("p_response_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."answer_map"("p_response_id" "uuid") IS 'form-model-normalization: rebuilds question_key -> jsonb from answers (scalars) + answer_selected_options (single-select=scalar code, checkbox=array of codes ordered by option.position). The SAME shapes the unchanged evaluator (app.eval_condition/eval_visibility) consumes — codes are the clone-stable identity conditions store. Canonical spec for the TS answersByItemId/answersByKey rehydration.';



CREATE OR REPLACE FUNCTION "app"."answer_map_by_item"("p_response_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
  with
  scalars as (
    select a.item_id, a.value
    from public.answers a
    join public.form_items i on i.id = a.item_id
    where a.response_id = p_response_id
      and a.value is not null
      and i.item_type = any (array['free_text','short_text','number','date','time'])
  ),
  selected as (
    select a.item_id, i.item_type, o.code, o.position
    from public.answer_selected_options s
    join public.answers a on a.id = s.answer_id
    join public.form_items i on i.id = a.item_id
    join public.form_item_options o on o.id = s.option_id
    where a.response_id = p_response_id
      and i.item_type = any (array['multiple_choice','dropdown','checkbox'])
  ),
  single as (
    select item_id, to_jsonb(min(code)) as value
    from selected
    where item_type = any (array['multiple_choice','dropdown'])
    group by item_id
  ),
  multi as (
    select item_id, jsonb_agg(to_jsonb(code) order by position) as value
    from selected
    where item_type = 'checkbox'
    group by item_id
  ),
  merged as (
    select item_id, value from scalars
    union all select item_id, value from single
    union all select item_id, value from multi
  )
  select coalesce(jsonb_object_agg(item_id::text, value), '{}'::jsonb)
  from merged;
$$;


ALTER FUNCTION "app"."answer_map_by_item"("p_response_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."answer_map_by_item"("p_response_id" "uuid") IS 'form-model-normalization: item_id::text -> value, SAME shapes as app.answer_map (single-select=scalar code, checkbox=array of codes by position, scalars=raw value), sourced from answers + answer_selected_options. The canonical SQL home for by-item_id materialization (twin of TS buildAnswerMaps'' answersByItemId).';



