CREATE TABLE IF NOT EXISTS "public"."case_referral" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "code" "text" NOT NULL,
    "source_case_id" "uuid" NOT NULL,
    "source_commission_id" "uuid" NOT NULL,
    "target_commission_id" "uuid" NOT NULL,
    "referral_type_id" "uuid",
    "type_label" "text" NOT NULL,
    "subject" "text" NOT NULL,
    "status" "text" DEFAULT 'rascunho'::"text" NOT NULL,
    "description_md" "text",
    "response_expected" boolean DEFAULT true NOT NULL,
    "target_case_id" "uuid",
    "has_patient" boolean DEFAULT false NOT NULL,
    "created_by" "uuid",
    "sent_at" timestamp with time zone,
    "sent_by" "uuid",
    "received_at" timestamp with time zone,
    "received_by" "uuid",
    "decided_at" timestamp with time zone,
    "decided_by" "uuid",
    "concluded_at" timestamp with time zone,
    "concluded_by" "uuid",
    "withdrawn_at" timestamp with time zone,
    "withdrawn_by" "uuid",
    "decline_note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source_commission_name" "text",
    "target_commission_name" "text",
    CONSTRAINT "case_referral_code_not_blank" CHECK (("btrim"("code") <> ''::"text")),
    CONSTRAINT "case_referral_distinct_commissions" CHECK (("source_commission_id" <> "target_commission_id")),
    CONSTRAINT "case_referral_status_check" CHECK (("status" = ANY (ARRAY['rascunho'::"text", 'enviada'::"text", 'recebida'::"text", 'aceita'::"text", 'recusada'::"text", 'em_analise'::"text", 'concluida'::"text", 'retirada'::"text"]))),
    CONSTRAINT "case_referral_subject_not_blank" CHECK (("btrim"("subject") <> ''::"text")),
    CONSTRAINT "case_referral_type_label_not_blank" CHECK (("btrim"("type_label") <> ''::"text"))
);


ALTER TABLE "public"."case_referral" OWNER TO "postgres";


COMMENT ON TABLE "public"."case_referral" IS 'Inter-committee referral message + lifecycle (Phase 22). The list/inbox/dashboard surface (subject/status/code/commission names/dates) is PHI-FREE (Decision 16); list queries select those columns only. The lone PHI-bearing column is description_md, loaded only by the audited detail door (see its own COMMENT). code = global ENC-NNNN. has_patient is the denormalized 0..1 referral_patient flag (a boolean is not PHI).';



COMMENT ON COLUMN "public"."case_referral"."description_md" IS 'PHI-bearing free-text cover note A wrote (sanitized Markdown, Rule 7). Direct SELECT is REVOKED from authenticated (column-level grant omits it); loaded ONLY via the audited get_referral_detail door, gated by can_read_referral_phi; NEVER on list/hub paths; NEVER copied into the audit log (Rule 11).';



COMMENT ON COLUMN "public"."case_referral"."decline_note" IS 'PHI-bearing free-text decline rationale B wrote. Direct SELECT is REVOKED from authenticated (column-level grant omits it); loaded ONLY via the audited get_referral_detail door, gated by can_read_referral_phi.';



CREATE OR REPLACE FUNCTION "app"."assert_referral_draft_writable"("p_referral_id" "uuid") RETURNS "public"."case_referral"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_referral public.case_referral;
begin
  select * into v_referral from public.case_referral where id = p_referral_id;
  if v_referral.id is null then
    raise exception 'encaminhamento não encontrado' using errcode = 'P0002';
  end if;
  if not app.can_manage_referral_source(p_referral_id, auth.uid()) then
    raise exception 'apenas a coordenação da comissão de origem pode editar este encaminhamento'
      using errcode = 'HC071';
  end if;
  if v_referral.status <> 'rascunho' then
    raise exception 'o encaminhamento não está em rascunho' using errcode = 'HC070';
  end if;
  return v_referral;
end;
$$;


