CREATE OR REPLACE FUNCTION "app"."compute_case_phase_result"("p_case_phase_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_case_id uuid;
  v_ruleset jsonb;
  v_override_id uuid;
  v_emits boolean;
  v_position integer;
  v_is_manual boolean;
  v_answers jsonb;
  r_rule jsonb;
  v_chosen uuid;
begin
  if not app.feature_enabled('case_phase_results') then
    return;
  end if;

  select case_id, result_ruleset, result_override_id, emits_result, position
    into v_case_id, v_ruleset, v_override_id, v_emits, v_position
  from public.case_phases where id = p_case_phase_id;

  if v_case_id is null then
    return;
  end if;

  -- MANUAL mode = emits a result but has no automatic ruleset. The result is the
  -- filler's stashed pick — MANDATORY. No override at conclude → reject.
  v_is_manual := coalesce(v_emits, false) and v_ruleset is null;
  if v_is_manual and v_override_id is null then
    raise exception
      'selecione o resultado da fase % antes de enviar', v_position
      using errcode = 'HC061';
  end if;

  -- Override path: honor a stashed override verbatim (validated at set-time
  -- against the allowed subset + live vocabulary).
  if v_override_id is not null then
    perform set_config('app.in_case_rpc', 'on', true);
    update public.case_phases
    set result_id = v_override_id,
        result_source = 'manual',
        result_computed_at = now(),
        updated_at = now()
    where id = p_case_phase_id;
    perform set_config('app.in_case_rpc', 'off', true);
    return;
  end if;

  -- Computed path. No override AND no ruleset: clear the effective result.
  if v_ruleset is null then
    perform set_config('app.in_case_rpc', 'on', true);
    update public.case_phases
    set result_id = null, result_source = null, result_computed_at = null,
        updated_at = now()
    where id = p_case_phase_id
      and (result_id is not null or result_source is not null);
    perform set_config('app.in_case_rpc', 'off', true);
    return;
  end if;

  v_answers := app.case_phase_answer_map(p_case_phase_id);

  v_chosen := null;
  for r_rule in select * from jsonb_array_elements(v_ruleset -> 'rules')
  loop
    if app.eval_condition(r_rule -> 'when', v_answers) then
      v_chosen := (r_rule ->> 'result_id')::uuid;
      exit;
    end if;
  end loop;

  if v_chosen is null then
    v_chosen := (v_ruleset ->> 'default_result_id')::uuid;
  end if;

  if v_chosen is not null and not exists (
    select 1 from public.case_phase_offered_results
    where case_id = v_case_id and result_id = v_chosen
  ) then
    v_chosen := null;
  end if;

  perform set_config('app.in_case_rpc', 'on', true);
  if v_chosen is null then
    update public.case_phases
    set result_id = null, result_source = null, result_computed_at = null,
        updated_at = now()
    where id = p_case_phase_id
      and (result_id is not null or result_source is not null);
  else
    update public.case_phases
    set result_id = v_chosen,
        result_source = 'computed',
        result_computed_at = now(),
        updated_at = now()
    where id = p_case_phase_id;
  end if;
  perform set_config('app.in_case_rpc', 'off', true);
end;
$$;


ALTER FUNCTION "app"."compute_case_phase_result"("p_case_phase_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."compute_sentinel_determination"("p_reach" "text", "p_harm" "text", "p_natural_course" boolean, "p_has_designated" boolean) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'app', 'pg_catalog'
    AS $$
  select coalesce(p_has_designated, false)
    or (
      -- general-criteria path: reached the patient AND sentinel-tier harm AND
      -- unrelated to the natural course of illness (natural_course = false).
      coalesce(p_reach in ('no_harm', 'adverse', 'sentinel'), false)
      and coalesce(p_harm in ('severe', 'permanent', 'death'), false)
      and p_natural_course is false
    );
$$;


ALTER FUNCTION "app"."compute_sentinel_determination"("p_reach" "text", "p_harm" "text", "p_natural_course" boolean, "p_has_designated" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."derive_patient_key"("p_value" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'pg_catalog'
    AS $$
declare
  v_pepper text;
  v_norm text;
begin
  select nullif(btrim(value), '') into v_pepper
  from app.app_secrets where key = 'mrn_pepper';

  if v_pepper is null then
    raise exception 'o segredo app_secrets[''mrn_pepper''] não está configurado — não é possível derivar a chave do paciente'
      using errcode = 'check_violation';
  end if;
  v_norm := app.normalize_identifier(p_value);
  if v_norm is null then
    return null;
  end if;
  return encode(extensions.hmac(v_norm, v_pepper, 'sha256'), 'hex');
end;
$$;


ALTER FUNCTION "app"."derive_patient_key"("p_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app"."derive_patient_key"("p_value" "text") IS 'ADR 0039 — HMAC-SHA256(normalize(value), app.app_secrets[mrn_pepper]) hex. Deterministic (cross-committee match) + irreversible without the pepper. RAISES if the pepper row is missing/empty (never a constant empty-pepper key); NULL value/norm -> NULL key. extensions.hmac is schema-qualified (not on search_path).';



CREATE OR REPLACE FUNCTION "app"."eval_condition"("p_visible_when" "jsonb", "p_answers" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_key text;
  v_op text;
  v_target jsonb;
  v_answer jsonb;
  v_present boolean;
  v_match boolean;
  v_cmp integer;
  v_a_text text;
  v_b_text text;
begin
  if p_visible_when is null then
    return true;
  end if;

  v_key := p_visible_when ->> 'question_key';
  v_op := p_visible_when ->> 'op';
  v_target := p_visible_when -> 'value';

  v_present := (p_answers ? v_key);
  v_answer := p_answers -> v_key;

  if not v_present or v_answer is null or v_answer = 'null'::jsonb then
    v_match := false;
  elsif jsonb_typeof(v_answer) = 'array' then
    v_match := v_answer @> jsonb_build_array(v_target);
  else
    v_match := (v_answer = v_target);
  end if;

  if v_op = 'equals' then
    return v_match;
  elsif v_op = 'not_equals' then
    return not v_match;
  elsif v_op = 'in' then
    if not v_present or v_answer is null or jsonb_typeof(v_target) <> 'array' then
      return false;
    end if;
    if jsonb_typeof(v_answer) = 'array' then
      return exists (
        select 1
        from jsonb_array_elements(v_answer) sel
        where v_target @> jsonb_build_array(sel.value)
      );
    else
      return v_target @> jsonb_build_array(v_answer);
    end if;
  elsif v_op in ('gt','gte','lt','lte') then
    -- Ordered comparison: undefined (no order) -> false for every op.
    if not v_present or v_answer is null or v_answer = 'null'::jsonb
       or jsonb_typeof(v_answer) = 'array' or jsonb_typeof(v_target) = 'array'
       or jsonb_typeof(v_answer) = 'object' or jsonb_typeof(v_target) = 'object' then
      return false;
    end if;

    if jsonb_typeof(v_answer) = 'number' and jsonb_typeof(v_target) = 'number' then
      v_cmp := sign((v_answer)::text::numeric - (v_target)::text::numeric)::integer;
    else
      v_a_text := v_answer #>> '{}';
      v_b_text := v_target #>> '{}';
      if v_a_text < v_b_text then
        v_cmp := -1;
      elsif v_a_text > v_b_text then
        v_cmp := 1;
      else
        v_cmp := 0;
      end if;
    end if;

    if v_op = 'gt' then
      return v_cmp > 0;
    elsif v_op = 'gte' then
      return v_cmp >= 0;
    elsif v_op = 'lt' then
      return v_cmp < 0;
    else -- 'lte'
      return v_cmp <= 0;
    end if;
  else
    raise exception 'unknown condition op: %', v_op;
  end if;
end;
$$;


ALTER FUNCTION "app"."eval_condition"("p_visible_when" "jsonb", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."eval_visibility"("p_rule" "jsonb", "p_answers" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_match text;
  v_result boolean;
begin
  if p_rule is null then
    return true;
  end if;

  if p_rule ? 'conditions' then
    v_match := p_rule ->> 'match';
    if v_match = 'any' then
      select coalesce(bool_or(app.eval_condition(c.value, p_answers)), false)
        into v_result
        from jsonb_array_elements(p_rule -> 'conditions') c;
    else
      -- 'all' (AND); empty -> true (bool_and over empty), though the CHECK
      -- forbids an empty group.
      select coalesce(bool_and(app.eval_condition(c.value, p_answers)), true)
        into v_result
        from jsonb_array_elements(p_rule -> 'conditions') c;
    end if;
    return v_result;
  end if;

  -- Legacy single shape.
  return app.eval_condition(p_rule, p_answers);
end;
$$;


