CREATE OR REPLACE FUNCTION "app"."is_valid_condition"("p" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select p is not null
     and jsonb_typeof(p) = 'object'
     and (p ? 'question_key')
     and (p ? 'op')
     and (p ? 'value')
     and jsonb_typeof(p -> 'question_key') = 'string'
     and (p ->> 'op') = any (array[
       'equals','not_equals','in','gt','gte','lt','lte'
     ]);
$$;


ALTER FUNCTION "app"."is_valid_condition"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."is_valid_recommend_cond"("p" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select
    p is not null
    and jsonb_typeof(p) = 'object'
    and (p ? 'from_phase')
    and jsonb_typeof(p -> 'from_phase') = 'number'
    and (
      case
        -- Result condition (source = 'result').
        when (p ->> 'source') = 'result' then
          case
            -- Result-adverse: an `adverse` boolean (no op/value).
            when (p ? 'adverse') then
              jsonb_typeof(p -> 'adverse') = 'boolean'
            -- Result-specific: op in the choice set + a value.
            else
              (p ? 'op')
              and (p ->> 'op') = any (array['equals','not_equals','in'])
              and (p ? 'value')
          end
        -- Answer condition (source absent or 'answer').
        when (not (p ? 'source')) or (p ->> 'source') = 'answer' then
          (p ? 'question_key')
          and jsonb_typeof(p -> 'question_key') = 'string'
          and (p ? 'op')
          and (p ->> 'op') = any (array['equals','not_equals','in'])
          and (p ? 'value')
        else false
      end
    );
$$;


ALTER FUNCTION "app"."is_valid_recommend_cond"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."is_valid_recommend_when"("p" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select
    p is null
    or (
      -- group shape
      (p ? 'conditions')
      and jsonb_typeof(p) = 'object'
      and (p ->> 'match') = any (array['all','any'])
      and jsonb_typeof(p -> 'conditions') = 'array'
      and jsonb_array_length(p -> 'conditions') > 0
      and not exists (
        select 1
        from jsonb_array_elements(p -> 'conditions') c
        where not app.is_valid_recommend_cond(c.value)
      )
    )
    or (
      -- legacy single (answer-only) shape — byte-for-byte the previous CHECK.
      not (p ? 'conditions')
      and jsonb_typeof(p) = 'object'
      and (p ? 'from_phase')
      and jsonb_typeof(p -> 'from_phase') = 'number'
      and (p ? 'question_key')
      and jsonb_typeof(p -> 'question_key') = 'string'
      and (p ? 'op')
      and (p ->> 'op') = any (array['equals','not_equals','in'])
      and (p ? 'value')
    );
$$;


ALTER FUNCTION "app"."is_valid_recommend_when"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."is_valid_visibility"("p" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select
    p is null
    or (
      -- group shape
      (p ? 'conditions')
      and jsonb_typeof(p) = 'object'
      and (p ->> 'match') = any (array['all','any'])
      and jsonb_typeof(p -> 'conditions') = 'array'
      and jsonb_array_length(p -> 'conditions') > 0
      and not exists (
        select 1
        from jsonb_array_elements(p -> 'conditions') c
        where not app.is_valid_condition(c.value)
      )
    )
    or (
      -- legacy single shape
      not (p ? 'conditions')
      and app.is_valid_condition(p)
    );
$$;


ALTER FUNCTION "app"."is_valid_visibility"("p" "jsonb") OWNER TO "postgres";


