CREATE OR REPLACE FUNCTION "app"."mint_capa_code"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $_$
declare
  v_next integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('pqs:capa_code', 0));

  v_next := coalesce(
    (select max((substring(code from 6))::integer)
     from public.capa_plan
     where code ~ '^CAPA-[0-9]+$'),
    0
  ) + 1;

  new.code := 'CAPA-' || lpad(v_next::text, 4, '0');
  return new;
end;
$_$;


ALTER FUNCTION "app"."mint_capa_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."mint_case_number"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
begin
  -- Serialize concurrent inserts for the SAME commission; other commissions are
  -- unaffected (distinct advisory-lock keys).
  perform pg_advisory_xact_lock(hashtextextended(new.commission_id::text, 0));

  new.case_number := coalesce(
    (select max(case_number) from public.cases where commission_id = new.commission_id),
    0
  ) + 1;

  return new;
end;
$$;


ALTER FUNCTION "app"."mint_case_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."mint_event_code"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $_$
declare
  v_next integer;
  v_org uuid := app.org_of_commission(new.reporting_commission_id);
begin
  -- Per-org advisory lock so two orgs mint concurrently without serializing on one key.
  perform pg_advisory_xact_lock(hashtextextended('pqs:event_code:' || coalesce(v_org::text, ''), 0));

  -- Highest existing EV-#### suffix + 1, FILTERED to this org's events (so an org
  -- cannot infer another org's event volume from gaps).
  v_next := coalesce(
    (select max((substring(e.code from 4))::integer)
     from public.patient_safety_event e
     join public.commissions c on c.id = e.reporting_commission_id
     where e.code ~ '^EV-[0-9]+$'
       and c.organization_id = v_org),
    0
  ) + 1;

  new.code := 'EV-' || lpad(v_next::text, 4, '0');
  return new;
end;
$_$;


ALTER FUNCTION "app"."mint_event_code"() OWNER TO "postgres";


