    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case when p_key is null or length(p_key) < 32 then null else (
    substr(p_key, 1, 8)  || '-' ||
    substr(p_key, 9, 4)  || '-' ||
    substr(p_key, 13, 4) || '-' ||
    substr(p_key, 17, 4) || '-' ||
