CREATE OR REPLACE FUNCTION "app"."recompute_case_status"("p_case_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_old_status text;
  v_new_status text;
  v_has_active boolean;
  v_has_concluded boolean;
begin
  select status into v_old_status from public.cases where id = p_case_id;
  if v_old_status is null then
    return;  -- case gone (e.g. mid-cascade); nothing to do.
  end if;

  -- Never override a manual terminal status.
  if v_old_status in ('concluido', 'cancelado') then
    return;
  end if;

  select bool_or(status = 'ativa'), bool_or(status = 'concluida')
    into v_has_active, v_has_concluded
  from public.case_phases
  where case_id = p_case_id;

  if coalesce(v_has_active, false) then
    v_new_status := 'em_revisao';
  elsif coalesce(v_has_concluded, false) then
    v_new_status := 'pendente';
  else
    v_new_status := 'nao_iniciado';
  end if;

  if v_new_status is distinct from v_old_status then
    perform set_config('app.in_case_rpc', 'on', true);
    update public.cases set status = v_new_status where id = p_case_id;
    perform set_config('app.in_case_rpc', 'off', true);
  end if;
end;
$$;


ALTER FUNCTION "app"."recompute_case_status"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."referral_target_analyst"("p_referral_id" "uuid", "p_uid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1
    from public.case_referral r
    where r.id = p_referral_id
      and r.target_case_id is not null
      and (
        exists (select 1 from public.case_phases cp
                where cp.case_id = r.target_case_id and cp.assigned_to = p_uid)
        or exists (select 1 from public.case_narratives cn
                   where cn.case_id = r.target_case_id and cn.assigned_to = p_uid)
        or exists (select 1 from public.case_access ca
                   where ca.case_id = r.target_case_id and ca.user_id = p_uid)
      )
  );
$$;


ALTER FUNCTION "app"."referral_target_analyst"("p_referral_id" "uuid", "p_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."response_required_complete"("p_response_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_version_id uuid;
  v_answers jsonb;
  r_section record;
  v_missing integer;
begin
  select form_version_id into v_version_id
  from public.responses
  where id = p_response_id;

  if v_version_id is null then
    return false;
  end if;

  v_answers := app.answer_map(p_response_id);

  for r_section in
    select s.id, s.visible_when
    from public.form_sections s
    where s.form_version_id = v_version_id
    order by s.position
  loop
    -- Hidden sections require nothing (group-aware visibility).
    if not app.eval_visibility(r_section.visible_when, v_answers) then
      continue;
    end if;

    select count(*) into v_missing
    from public.form_items i
    where i.section_id = r_section.id
      and i.required = true
      and i.question_key is not null
      -- A per-item visibility condition can hide a required item; honour it.
      and app.eval_visibility(i.visible_when, v_answers)
      and not (
        exists (
          select 1 from public.answers a
          where a.response_id = p_response_id
            and a.item_id = i.id
            and a.value is not null
            and a.value <> 'null'::jsonb
        )
        or exists (
          select 1
          from public.answer_selected_options s
          join public.answers a on a.id = s.answer_id
          where a.response_id = p_response_id
            and a.item_id = i.id
        )
      );

    if v_missing > 0 then
      return false;
    end if;
  end loop;

  return true;
end;
$$;


ALTER FUNCTION "app"."response_required_complete"("p_response_id" "uuid") OWNER TO "postgres";


