CREATE OR REPLACE FUNCTION "app"."trg_xref_maintain"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_module text := case TG_TABLE_NAME
                     when 'event_patient' then 'event'
                     when 'referral_patient' then 'referral'
                     when 'case_patient' then 'case'
                   end;
  v_id_col text := case TG_TABLE_NAME
                     when 'event_patient' then 'event_id'
                     when 'referral_patient' then 'referral_id'
                     when 'case_patient' then 'case_id'
                   end;
  v_entity uuid;
  v_comm uuid;
  v_reason text;
begin
  if TG_OP = 'DELETE' then
    v_entity := (to_jsonb(old) ->> v_id_col)::uuid;
    v_reason := coalesce(nullif(btrim(coalesce(current_setting('app.phi_dispose_reason', true), '')), ''), 'other');
    -- Retain the xref row, stamp it disposed. If no xref row exists (name-only PHI
    -- never indexed), this updates nothing — fine.
    update public.patient_xref
       set disposed_at = coalesce(disposed_at, now()),
           disposed_reason = v_reason
     where module = v_module and entity_id = v_entity;
    return old;
  end if;

  -- INSERT / UPDATE
  v_entity := (to_jsonb(new) ->> v_id_col)::uuid;

  -- Skip when there is nothing to index (both keys NULL): name-only PHI (no MRN /
  -- encounter). No xref row is created.
  if new.patient_key is null and new.encounter_key is null then
    return new;
  end if;

  v_comm := case v_module
              when 'event' then app.commission_of_event(v_entity)
              when 'referral' then app.commission_of_referral(v_entity)
              when 'case' then app.commission_of_case(v_entity)
            end;

  insert into public.patient_xref (module, entity_id, commission_id, patient_key, encounter_key)
  values (v_module, v_entity, v_comm, new.patient_key, new.encounter_key)
  on conflict (module, entity_id) do update
    set patient_key = excluded.patient_key,
        encounter_key = excluded.encounter_key,
        commission_id = excluded.commission_id;
  -- NOTE: a live UPDATE of identifiers does NOT clear an earlier disposed stamp —
  -- disposal deletes the PHI row, so a subsequent UPDATE on it cannot occur.

  return new;
end;
$$;


ALTER FUNCTION "app"."trg_xref_maintain"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."validate_template_allowed_results"("p_template_id" "uuid", "p_position" integer, "p_allowed_result_ids" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_id uuid;
  r_el jsonb;
begin
  if p_allowed_result_ids is null then
    return true;
  end if;

  select t.commission_id into v_commission_id
  from public.process_template_phases ph
  join public.process_templates t on t.id = ph.template_id
  where ph.template_id = p_template_id and ph.position = p_position;

  if v_commission_id is null then
    raise exception 'fase % não encontrada no processo', p_position
      using errcode = 'no_data_found';
  end if;

  for r_el in select * from jsonb_array_elements(p_allowed_result_ids)
  loop
    v_id := (r_el #>> '{}')::uuid;
    if v_id is null or not exists (
      select 1 from public.phase_results
      where id = v_id and commission_id = v_commission_id and archived = false
    ) then
      raise exception
        'os resultados permitidos da fase % referenciam uma opção inválida ou arquivada', p_position
        using errcode = 'HC059';
    end if;
  end loop;

  return true;
end;
$$;


ALTER FUNCTION "app"."validate_template_allowed_results"("p_template_id" "uuid", "p_position" integer, "p_allowed_result_ids" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."validate_template_phase_blocks"("p_template_id" "uuid", "p_position" integer, "p_blocks" integer[]) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_missing integer;
begin
  if p_blocks is null or cardinality(p_blocks) = 0 then
    return true;
  end if;

  -- Earlier-only (defensive; the column trigger also enforces it).
  select b into v_missing
  from unnest(p_blocks) as b
  where b < 1 or b >= p_position
  limit 1;
  if found then
    raise exception
      'um bloqueio da fase % deve referenciar uma fase anterior (fase informada: %)',
      p_position, v_missing
      using errcode = 'HC016';
  end if;

  -- Every referenced position must exist as a slot in this template.
  select b into v_missing
  from unnest(p_blocks) as b
  where not exists (
    select 1 from public.process_template_phases
    where template_id = p_template_id and position = b
  )
  limit 1;
  if found then
    raise exception
      'um bloqueio da fase % referencia a fase %, que não existe no processo',
      p_position, v_missing
      using errcode = 'HC016';
  end if;

  return true;
end;
$$;


ALTER FUNCTION "app"."validate_template_phase_blocks"("p_template_id" "uuid", "p_position" integer, "p_blocks" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."validate_template_phase_result"("p_template_id" "uuid", "p_position" integer) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_emits boolean;
  v_ruleset jsonb;
  v_allowed jsonb;
begin
  select emits_result, result_ruleset, allowed_result_ids
    into v_emits, v_ruleset, v_allowed
  from public.process_template_phases
  where template_id = p_template_id and position = p_position;

  if v_emits and v_allowed is null then
    raise exception
      'a fase % emite um resultado, mas nenhum resultado permitido foi selecionado', p_position
      using errcode = 'HC059';
  end if;

  perform app.validate_template_result_ruleset(p_template_id, p_position, v_ruleset);
  perform app.validate_template_allowed_results(p_template_id, p_position, v_allowed);
  return true;
end;
$$;


ALTER FUNCTION "app"."validate_template_phase_result"("p_template_id" "uuid", "p_position" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."validate_template_recommend_when"("p_template_id" "uuid", "p_position" integer, "p_recommend_when" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  rc jsonb;                -- one sub-condition
  v_commission_id uuid;
  v_from_phase integer;
  v_question_key text;
  v_source_form_id uuid;
  v_source_version uuid;
  v_source_emits boolean;
  v_source_allowed jsonb;
  v_is_result boolean;
  v_id uuid;
  v_target_type text;
begin
  if p_recommend_when is null then
    return true;
  end if;

  select commission_id into v_commission_id
  from public.process_templates
  where id = p_template_id;

  for rc in select cond from app.recommend_when_conditions(p_recommend_when) cond loop
    v_from_phase := (rc ->> 'from_phase')::integer;
    v_is_result := (rc ->> 'source') = 'result';

    if v_from_phase is null or v_from_phase < 1 or v_from_phase >= p_position then
      raise exception
        'a recomendação da fase % deve referenciar uma fase anterior (fase informada: %)',
        p_position, coalesce(v_from_phase::text, 'nula')
        using errcode = 'HC016';
    end if;

    select form_id, emits_result, allowed_result_ids
      into v_source_form_id, v_source_emits, v_source_allowed
    from public.process_template_phases
    where template_id = p_template_id and position = v_from_phase;

    if v_source_form_id is null then
      raise exception
        'a recomendação da fase % referencia a fase %, que não existe no processo',
        p_position, v_from_phase
        using errcode = 'HC016';
    end if;

    if v_is_result then
      if not coalesce(v_source_emits, false) then
        raise exception
          'a recomendação da fase % usa o resultado da fase %, que não emite resultado',
          p_position, v_from_phase
          using errcode = 'HC063';
      end if;

      if not (rc ? 'adverse') then
        for v_id in
          select (e #>> '{}')::uuid
          from jsonb_array_elements(
                 case when jsonb_typeof(rc -> 'value') = 'array'
                      then rc -> 'value'
                      else jsonb_build_array(rc -> 'value') end
               ) e
        loop
          if v_id is null then
            raise exception
              'a recomendação da fase % referencia um resultado inválido', p_position
              using errcode = 'HC064';
          end if;
          if v_source_allowed is null or not exists (
            select 1 from jsonb_array_elements_text(v_source_allowed) as a(id)
            where a.id::uuid = v_id
          ) then
            raise exception
              'a recomendação da fase % referencia um resultado que não está entre as opções permitidas da fase %',
              p_position, v_from_phase
              using errcode = 'HC064';
          end if;
          if not exists (
            select 1 from public.phase_results
            where id = v_id and commission_id = v_commission_id and archived = false
          ) then
            raise exception
              'a recomendação da fase % referencia uma opção de resultado inválida ou arquivada',
              p_position
              using errcode = 'HC064';
          end if;
        end loop;
      end if;
    else
      -- Answer condition: question_key must exist as an input item; and (NEW) the
      -- value codes must exist on it when it is a choice question.
      v_question_key := rc ->> 'question_key';

      v_source_version := app.published_version_of_form(v_source_form_id);
      if v_source_version is null then
        raise exception
          'o formulário da fase % (origem da recomendação) ainda não foi publicado',
          v_from_phase
          using errcode = 'HC017';
      end if;

      if not app.version_has_input_key(v_source_version, v_question_key) then
        raise exception
          'a recomendação da fase % referencia a pergunta "%", que não existe no formulário da fase %',
          p_position, v_question_key, v_from_phase
          using errcode = 'HC016';
      end if;

      -- form-model-normalization: the answer value(s) are option CODES; assert
      -- they exist on the choice question (no-op for non-choice targets).
      v_target_type := app.item_question_type(v_source_version, v_question_key);
      perform app.assert_condition_value_codes(
        v_source_version, v_question_key, v_target_type, rc -> 'value',
        format('a recomendação da fase %s', p_position)
      );
    end if;
  end loop;

  return true;
end;
$$;


ALTER FUNCTION "app"."validate_template_recommend_when"("p_template_id" "uuid", "p_position" integer, "p_recommend_when" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."validate_template_result_ruleset"("p_template_id" "uuid", "p_position" integer, "p_result_ruleset" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_form_id uuid;
  v_version uuid;
  r_rule jsonb;
  v_qkey text;
  v_result_id uuid;
  v_default_id uuid;
  v_target_type text;
begin
  if p_result_ruleset is null then
    return true;
  end if;

  select t.commission_id, ph.form_id
    into v_commission_id, v_form_id
  from public.process_template_phases ph
  join public.process_templates t on t.id = ph.template_id
  where ph.template_id = p_template_id and ph.position = p_position;

  if v_form_id is null then
    raise exception 'fase % não encontrada no processo', p_position
      using errcode = 'no_data_found';
  end if;

  v_version := app.published_version_of_form(v_form_id);
  if v_version is null then
    raise exception 'o formulário da fase % ainda não foi publicado', p_position
      using errcode = 'HC017';
  end if;

  for r_rule in select * from jsonb_array_elements(p_result_ruleset -> 'rules')
  loop
    v_qkey := r_rule -> 'when' ->> 'question_key';
    if v_qkey is null or not app.version_has_input_key(v_version, v_qkey) then
      raise exception
        'o resultado da fase % referencia a pergunta "%", que não existe no formulário publicado',
        p_position, coalesce(v_qkey, 'nula')
        using errcode = 'HC016';
    end if;

    -- form-model-normalization: the when value(s) are option CODES; assert they
    -- exist on the choice question (no-op for non-choice targets).
    v_target_type := app.item_question_type(v_version, v_qkey);
    perform app.assert_condition_value_codes(
      v_version, v_qkey, v_target_type, r_rule -> 'when' -> 'value',
      format('o resultado da fase %s', p_position)
    );

    v_result_id := (r_rule ->> 'result_id')::uuid;
    if v_result_id is null or not exists (
      select 1 from public.phase_results
      where id = v_result_id and commission_id = v_commission_id and archived = false
    ) then
      raise exception
        'o resultado da fase % referencia uma opção de resultado inválida ou arquivada',
        p_position
        using errcode = 'HC059';
    end if;
  end loop;

  v_default_id := (p_result_ruleset ->> 'default_result_id')::uuid;
  if v_default_id is not null and not exists (
    select 1 from public.phase_results
    where id = v_default_id and commission_id = v_commission_id and archived = false
  ) then
    raise exception
      'o resultado padrão da fase % é uma opção inválida ou arquivada', p_position
      using errcode = 'HC059';
  end if;

  return true;
end;
$$;


ALTER FUNCTION "app"."validate_template_result_ruleset"("p_template_id" "uuid", "p_position" integer, "p_result_ruleset" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."version_has_input_key"("p_version_id" "uuid", "p_question_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1 from public.form_items
    where form_version_id = p_version_id
      and question_key = p_question_key
      and item_type in ('multiple_choice', 'dropdown', 'checkbox', 'free_text')
  );
$$;


ALTER FUNCTION "app"."version_has_input_key"("p_version_id" "uuid", "p_question_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."version_has_option_code"("p_version_id" "uuid", "p_question_key" "text", "p_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1
    from public.form_items i
    join public.form_item_options o on o.item_id = i.id
    where i.form_version_id = p_version_id
      and i.question_key = p_question_key
      and o.code = p_code
  );
$$;


ALTER FUNCTION "app"."version_has_option_code"("p_version_id" "uuid", "p_question_key" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app"."visibility_conditions"("p_rule" "jsonb") RETURNS SETOF "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select c.value
  from jsonb_array_elements(p_rule -> 'conditions') c
  where p_rule is not null and (p_rule ? 'conditions')
  union all
  select p_rule
  where p_rule is not null and not (p_rule ? 'conditions');
$$;


ALTER FUNCTION "app"."visibility_conditions"("p_rule" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_referral"("p_referral_id" "uuid") RETURNS "public"."case_referral"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_row public.case_referral;
begin
  perform app.assert_referrals_enabled();
  perform app.assert_referral_target_acts(p_referral_id, array['recebida']);

  perform set_config('app.in_referral_rpc', 'on', true);
  update public.case_referral
  set status = 'aceita', decided_at = now(), decided_by = auth.uid(), updated_at = now()
  where id = p_referral_id
  returning * into v_row;
  perform set_config('app.in_referral_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."accept_referral"("p_referral_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."patient_safety_event" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "code" "text" NOT NULL,
    "reporting_commission_id" "uuid" NOT NULL,
    "case_id" "uuid",
    "discovered_at" "date",
    "reported_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "location" "text",
    "reported_by" "uuid",
    "event_type_id" "uuid",
    "suspected_harm_level" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "title" "text" NOT NULL,
    "description_md" "text",
    "status" "text" DEFAULT 'reported'::"text" NOT NULL,
    "current_owner_kind" "text" DEFAULT 'pqs'::"text" NOT NULL,
    "current_owner_commission_id" "uuid",
    "acknowledged_by" "uuid",
    "acknowledged_at" timestamp with time zone,
    "closed_by" "uuid",
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "has_patient" boolean DEFAULT false NOT NULL,
    "phi_disposed_at" timestamp with time zone,
    "phi_disposed_by" "uuid",
    "phi_disposed_reason" "text",
    CONSTRAINT "patient_safety_event_current_owner_kind_check" CHECK (("current_owner_kind" = ANY (ARRAY['pqs'::"text", 'commission'::"text"]))),
    CONSTRAINT "patient_safety_event_owner_shape" CHECK (((("current_owner_kind" = 'pqs'::"text") AND ("current_owner_commission_id" IS NULL)) OR (("current_owner_kind" = 'commission'::"text") AND ("current_owner_commission_id" IS NOT NULL)))),
    CONSTRAINT "patient_safety_event_phi_disposed_reason_check" CHECK ((("phi_disposed_reason" IS NULL) OR ("phi_disposed_reason" = ANY (ARRAY['retention_expired'::"text", 'subject_request'::"text", 'entered_in_error'::"text", 'duplicate'::"text", 'other'::"text"])))),
    CONSTRAINT "patient_safety_event_status_check" CHECK (("status" = ANY (ARRAY['reported'::"text", 'acknowledged'::"text", 'triaged'::"text", 'closed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "patient_safety_event_suspected_harm_level_check" CHECK (("suspected_harm_level" = ANY (ARRAY['none'::"text", 'mild'::"text", 'moderate'::"text", 'severe'::"text", 'death'::"text", 'unknown'::"text"]))),
    CONSTRAINT "patient_safety_event_title_not_blank" CHECK (("btrim"("title") <> ''::"text"))
);


ALTER TABLE "public"."patient_safety_event" OWNER TO "postgres";


COMMENT ON TABLE "public"."patient_safety_event" IS 'Patient-safety event GOVERNANCE METADATA — no patient identifiers (those are isolated on public.event_patient, B3). current_owner_* is the denormalized head of the public.event_custody ledger and drives access-follows-custody RLS (ADR 0031).';



COMMENT ON COLUMN "public"."patient_safety_event"."description_md" IS 'PHI-BEARING free text (WS B; Rule 11/12). Reporter narrative (sanitized Markdown, Rule 7); audited via safety_event.viewed; never copied into the audit log.';



COMMENT ON COLUMN "public"."patient_safety_event"."has_patient" IS 'Denormalized "an isolated event_patient (PHI) row exists" flag (WS A). Set true by set_event_patient, false by PHI disposal (WS C). Lets governance/list reads derive hasPatient WITHOUT the event_patient(event_id) embed, which breaks once direct SELECT on event_patient is revoked.';



COMMENT ON COLUMN "public"."patient_safety_event"."phi_disposed_at" IS 'WS C: when the event PHI was disposed (NULL until disposal). PHI-safe accountability stamp set by dispose_event_phi; one-shot.';



COMMENT ON COLUMN "public"."patient_safety_event"."phi_disposed_by" IS 'WS C: who disposed the event PHI (NULL until disposal). PHI-safe accountability stamp set by dispose_event_phi.';



COMMENT ON COLUMN "public"."patient_safety_event"."phi_disposed_reason" IS 'WS C: WHY the PHI was disposed — a CONSTRAINED CATEGORY (retention_expired/subject_request/entered_in_error/duplicate/other), NEVER free text (Rule 11 + LGPD Art. 18). NULL until disposal.';



CREATE OR REPLACE FUNCTION "public"."acknowledge_event"("p_event_id" "uuid") RETURNS "public"."patient_safety_event"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_event public.patient_safety_event;
  v_status text;
begin
  perform app.assert_patient_safety_enabled();

  if not app.can_read_event(p_event_id, auth.uid()) then
    raise exception 'evento não encontrado' using errcode = 'P0002';
  end if;
  if not app.event_current_custodian(p_event_id, auth.uid()) then
    raise exception 'apenas quem detém a custódia do evento pode reconhecê-lo'
      using errcode = 'HC044';
  end if;

  select status into v_status from public.patient_safety_event where id = p_event_id;
  if v_status <> 'reported' then
    raise exception 'apenas eventos notificados podem ser reconhecidos' using errcode = 'HC043';
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.patient_safety_event
  set status = 'acknowledged', acknowledged_by = auth.uid(), acknowledged_at = now(),
      updated_at = now()
  where id = p_event_id
  returning * into v_event;
  perform set_config('app.in_safety_rpc', 'off', true);

  return v_event;
end;
$$;


ALTER FUNCTION "public"."acknowledge_event"("p_event_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."case_phases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "case_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "form_id" "uuid" NOT NULL,
    "form_version_id" "uuid" NOT NULL,
    "title" "text",
    "status" "text" DEFAULT 'pendente'::"text" NOT NULL,
    "recommended" boolean DEFAULT false NOT NULL,
    "recommend_when" "jsonb",
    "assigned_to" "uuid",
    "is_ad_hoc" boolean DEFAULT false NOT NULL,
    "activated_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "skipped_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "default_due_days" integer,
    "due_date" "date",
    "blocks" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "display_position" integer,
    "result_ruleset" "jsonb",
    "result_id" "uuid",
    "result_computed_at" timestamp with time zone,
    "result_source" "text",
    "result_override_id" "uuid",
    "result_override_by" "uuid",
    "result_override_at" timestamp with time zone,
    "result_override_reason" "text",
    "emits_result" boolean DEFAULT false NOT NULL,
    "allowed_result_ids" "jsonb",
    CONSTRAINT "case_phases_allowed_shape" CHECK ((("allowed_result_ids" IS NULL) OR (("jsonb_typeof"("allowed_result_ids") = 'array'::"text") AND ("jsonb_array_length"("allowed_result_ids") >= 1)))),
    CONSTRAINT "case_phases_default_due_days_nonneg" CHECK ((("default_due_days" IS NULL) OR ("default_due_days" >= 0))),
    CONSTRAINT "case_phases_recommend_when_shape" CHECK ("app"."is_valid_recommend_when"("recommend_when")),
    CONSTRAINT "case_phases_result_emits" CHECK (("emits_result" OR (("result_ruleset" IS NULL) AND ("allowed_result_ids" IS NULL)))),
    CONSTRAINT "case_phases_result_source_check" CHECK ((("result_source" IS NULL) OR ("result_source" = ANY (ARRAY['computed'::"text", 'manual'::"text"])))),
    CONSTRAINT "case_phases_status_check" CHECK (("status" = ANY (ARRAY['pendente'::"text", 'ativa'::"text", 'concluida'::"text", 'nao_necessaria'::"text"])))
);


ALTER TABLE "public"."case_phases" OWNER TO "postgres";


COMMENT ON COLUMN "public"."case_phases"."result_ruleset" IS 'SNAPSHOT of the template phase''s result_ruleset at case creation (phase-results feature), exactly as recommend_when is snapshotted. compute_case_phase_result reads THIS so concluded phases stay stable against later template edits.';



COMMENT ON COLUMN "public"."case_phases"."result_id" IS 'The EFFECTIVE per-phase result option (phase-results feature). Written in the SAME statement that flips the phase to concluida (computed or honored-override); null = not concluded / no ruleset and no override / flag off. Never rewritten afterward.';



COMMENT ON COLUMN "public"."case_phases"."result_source" IS 'computed | manual — whether the effective result_id came from the ruleset walk or a human override. NULL until a result is written.';



COMMENT ON COLUMN "public"."case_phases"."result_override_reason" IS 'Optional human justification for a result override. NOT copied into the audit log (Rule 11) — the override audit row records only the fact + chosen option id.';



CREATE OR REPLACE FUNCTION "public"."activate_phase"("p_case_phase_id" "uuid", "p_assigned_to" "uuid", "p_due_date" "date" DEFAULT NULL::"date") RETURNS "public"."case_phases"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_case_id uuid;
  v_status text;
  v_case_status text;
  v_commission_id uuid;
  v_blocks integer[];
  v_blocking integer;
  v_result public.case_phases;
begin
  perform app.assert_cases_enabled();

  select cp.case_id, cp.status, cp.blocks, c.status, c.commission_id
    into v_case_id, v_status, v_blocks, v_case_status, v_commission_id
  from public.case_phases cp
  join public.cases c on c.id = cp.case_id
  where cp.id = p_case_phase_id;

  if v_case_id is null then
    raise exception 'fase % não encontrada', p_case_phase_id using errcode = 'no_data_found';
  end if;
  if v_case_status in ('concluido', 'cancelado') then
    raise exception 'este caso não está aberto' using errcode = 'HC020';
  end if;
  if v_status <> 'pendente' then
    raise exception 'esta fase não está pendente' using errcode = 'HC019';
  end if;

  -- Blocker gate (D1/D4): a phase is blocked while ANY phase it lists is not yet
  -- concluida/nao_necessaria. Empty blocks -> never blocked (parallel-friendly).
  if v_blocks is not null and cardinality(v_blocks) > 0 then
    select count(*) into v_blocking
    from public.case_phases
    where case_id = v_case_id
      and position = any(v_blocks)
      and status not in ('concluida', 'nao_necessaria');
    if v_blocking > 0 then
      raise exception 'conclua ou marque as fases que bloqueiam esta antes de ativá-la'
        using errcode = 'HC018';
    end if;
  end if;

  if not app.is_member_of_for(v_commission_id, p_assigned_to) then
    raise exception 'o responsável deve ser membro da comissão' using errcode = 'HC021';
  end if;

  perform set_config('app.in_case_rpc', 'on', true);
  update public.case_phases
  set status = 'ativa',
      assigned_to = p_assigned_to,
      due_date = p_due_date,
      activated_at = now(),
      updated_at = now()
  where id = p_case_phase_id
  returning * into v_result;
  perform set_config('app.in_case_rpc', 'off', true);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."activate_phase"("p_case_phase_id" "uuid", "p_assigned_to" "uuid", "p_due_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_ad_hoc_phase"("p_case_id" "uuid", "p_form_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_recommend_when" "jsonb" DEFAULT NULL::"jsonb", "p_assigned_to" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."case_phases"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_case_status text;
  v_commission_id uuid;
  v_position integer;
  v_display_position integer;
  v_version uuid;
  v_from_phase integer;
  v_source_version uuid;
  v_result public.case_phases;
begin
  perform app.assert_cases_enabled();

  select status, commission_id into v_case_status, v_commission_id
  from public.cases where id = p_case_id;
  if v_case_status is null then
    raise exception 'caso % não encontrado', p_case_id using errcode = 'no_data_found';
  end if;
  if v_case_status in ('concluido', 'cancelado') then
    raise exception 'este caso não está aberto' using errcode = 'HC020';
  end if;

  if not exists (
    select 1 from public.forms where id = p_form_id and commission_id = v_commission_id
  ) then
    raise exception 'o formulário não pertence a esta comissão' using errcode = 'check_violation';
  end if;

  v_version := app.published_version_of_form(p_form_id);
  if v_version is null then
    raise exception 'este formulário ainda não foi publicado' using errcode = 'HC017';
  end if;

  -- Immutable phase number: counts only phases (referenced by blocks / recommend_when).
  select coalesce(max(position), 0) + 1 into v_position
  from public.case_phases where case_id = p_case_id;

  -- Display slot: next position in the merged phases+narratives interleave.
  -- Mirrors the add_template_narrative / get_case_detail coalesce convention:
  -- phases fall back to `position` when display_position is null.
  select coalesce(max(dp), 0) + 1 into v_display_position
  from (
    select coalesce(display_position, position) as dp
    from public.case_phases where case_id = p_case_id
    union all
    select display_position as dp
    from public.case_narratives where case_id = p_case_id
  ) s;

  -- Validate recommend_when against the existing (earlier) phases' pinned versions.
  if p_recommend_when is not null then
    v_from_phase := (p_recommend_when ->> 'from_phase')::integer;
    if v_from_phase is null or v_from_phase < 1 or v_from_phase >= v_position then
      raise exception 'a recomendação deve referenciar uma fase anterior'
        using errcode = 'HC016';
    end if;
    select form_version_id into v_source_version
    from public.case_phases where case_id = p_case_id and position = v_from_phase;
    if v_source_version is null then
      raise exception 'a recomendação referencia uma fase inexistente'
        using errcode = 'HC016';
    end if;
    if not app.version_has_input_key(v_source_version, p_recommend_when ->> 'question_key') then
      raise exception 'a recomendação referencia uma pergunta inexistente no formulário de origem'
        using errcode = 'HC016';
    end if;
  end if;

  if p_assigned_to is not null and not app.is_member_of_for(v_commission_id, p_assigned_to) then
    raise exception 'o responsável deve ser membro da comissão' using errcode = 'HC021';
  end if;

  perform set_config('app.in_case_rpc', 'on', true);
  insert into public.case_phases
    (case_id, position, display_position, form_id, form_version_id, title,
     recommend_when, is_ad_hoc, assigned_to)
  values
    (p_case_id, v_position, v_display_position, p_form_id, v_version,
     nullif(btrim(p_title), ''), p_recommend_when, true, p_assigned_to)
  returning * into v_result;
  perform set_config('app.in_case_rpc', 'off', true);

  perform public.recompute_recommendations(p_case_id);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."add_ad_hoc_phase"("p_case_id" "uuid", "p_form_id" "uuid", "p_title" "text", "p_recommend_when" "jsonb", "p_assigned_to" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_capa_action"("p_capa_id" "uuid", "p_title" "text", "p_owner" "text" DEFAULT NULL::"text", "p_assignee_user_id" "uuid" DEFAULT NULL::"uuid", "p_due_date" "date" DEFAULT NULL::"date", "p_action_strength" "text" DEFAULT 'intermediaria'::"text", "p_success_measure" "text" DEFAULT NULL::"text", "p_root_cause_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."capa_action"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_row public.capa_action;
begin
  perform app.assert_patient_safety_enabled();
  perform app.assert_capa_writable(p_capa_id);
  if btrim(coalesce(p_title, '')) = '' then
    raise exception 'informe um título para a ação corretiva' using errcode = 'check_violation';
  end if;
  if coalesce(p_action_strength, 'intermediaria') not in ('forte', 'intermediaria', 'fraca') then
    raise exception 'força da ação inválida' using errcode = 'check_violation';
  end if;
  if p_assignee_user_id is not null
     and not exists (select 1 from public.profiles where id = p_assignee_user_id) then
    raise exception 'responsável não encontrado' using errcode = 'no_data_found';
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.capa_plan set status = 'em_execucao', updated_at = now()
  where id = p_capa_id and status = 'aberto';
  insert into public.capa_action (
    capa_id, title, owner, assignee_user_id, due_date, action_strength,
    success_measure, root_cause_id, position
  ) values (
    p_capa_id, btrim(p_title), p_owner, p_assignee_user_id, p_due_date,
    coalesce(p_action_strength, 'intermediaria'), p_success_measure, p_root_cause_id,
    coalesce((select max(position) from public.capa_action where capa_id = p_capa_id), 0) + 1
  )
  returning * into v_row;
  perform set_config('app.in_safety_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."add_capa_action"("p_capa_id" "uuid", "p_title" "text", "p_owner" "text", "p_assignee_user_id" "uuid", "p_due_date" "date", "p_action_strength" "text", "p_success_measure" "text", "p_root_cause_id" "uuid") OWNER TO "postgres";


