    "organization_id" "uuid" NOT NULL
);


ALTER TABLE "public"."pqs_members" OWNER TO "postgres";


COMMENT ON TABLE "public"."pqs_members" IS 'PER-ORG PQS/NSP roster (NSP-per-org, ADR 0042; was a global PK(user_id) roster). Enrollment in (organization_id, user_id) is what grants that org''s PHI READ via app.is_pqs_member_of. Curated by the org''s nsp_coordinator (pqs_members_coordinator_all); NO platform-admin escape hatch (duty separation).';



COMMENT ON COLUMN "public"."pqs_members"."organization_id" IS 'The organization whose PHI this enrollment grants read of. Part of the composite PK (organization_id, user_id).';



CREATE OR REPLACE FUNCTION "public"."add_pqs_member"("p_org_id" "uuid", "p_user_id" "uuid") RETURNS "public"."pqs_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_row public.pqs_members;
begin
  -- Per-org coordinator only (NOT org_admin, NOT platform_admin — duty separation).
  if not app.is_nsp_coordinator_of(p_org_id) then
    raise exception 'apenas o coordenador do NSP da organização pode gerenciar a equipe'
      using errcode = '42501';
  end if;
  insert into public.pqs_members (organization_id, user_id, added_by)
  values (p_org_id, p_user_id, auth.uid())
  on conflict (organization_id, user_id) do nothing;
  select * into v_row from public.pqs_members
    where organization_id = p_org_id and user_id = p_user_id;
  return v_row;
end;
$$;


