ALTER TABLE "public"."referral_reply_attachment" OWNER TO "postgres";


COMMENT ON TABLE "public"."referral_reply_attachment" IS 'Optional B-side reply attachments (Decision 10; PHI-bearing). Immutable: a fresh storage_path per upload (Rule 6), no UPDATE/DELETE. Lives in the referral-attachments bucket; downloaded via the audited get_referral_attachment_url door.';



CREATE OR REPLACE FUNCTION "public"."add_referral_reply_attachment"("p_referral_id" "uuid", "p_title" "text", "p_storage_path" "text", "p_mime_type" "text" DEFAULT NULL::"text", "p_size_bytes" bigint DEFAULT NULL::bigint) RETURNS "public"."referral_reply_attachment"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_row public.referral_reply_attachment;
begin
  perform app.assert_referrals_enabled();
  perform app.assert_referral_target_acts(p_referral_id, array['aceita', 'em_analise']);
  if btrim(coalesce(p_title, '')) = '' then
    raise exception 'informe um título para o anexo' using errcode = 'check_violation';
  end if;
  if btrim(coalesce(p_storage_path, '')) = '' then
    raise exception 'caminho do anexo inválido' using errcode = 'check_violation';
  end if;

  insert into public.referral_reply_attachment (
    referral_id, title, storage_path, mime_type, size_bytes, uploaded_by
  ) values (
    p_referral_id, btrim(p_title), p_storage_path, p_mime_type, p_size_bytes, auth.uid()
  )
  returning * into v_row;
  return v_row;
end;
$$;


ALTER FUNCTION "public"."add_referral_reply_attachment"("p_referral_id" "uuid", "p_title" "text", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."referral_shared_item" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "referral_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "source_narrative_id" "uuid",
    "source_document_id" "uuid",
    "frozen_title" "text",
    "frozen_body_md" "text",
    "frozen_storage_path" "text",
    "frozen_mime_type" "text",
    "frozen_size_bytes" bigint,
    "position" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "referral_shared_item_kind_check" CHECK (("kind" = ANY (ARRAY['narrative'::"text", 'document'::"text"]))),
    CONSTRAINT "referral_shared_item_shape" CHECK (((("kind" = 'narrative'::"text") AND ("frozen_body_md" IS NOT NULL) AND ("frozen_storage_path" IS NULL)) OR (("kind" = 'document'::"text") AND ("frozen_storage_path" IS NOT NULL) AND ("frozen_body_md" IS NULL))))
);


ALTER TABLE "public"."referral_shared_item" OWNER TO "postgres";


COMMENT ON TABLE "public"."referral_shared_item" IS 'Frozen point-in-time SNAPSHOT rows B reads (Decision 3/9). Decoupled from A''s live case: a narrative freezes a body_md copy, a document freezes the storage REFERENCE (Rule 6 — the object is never re-uploaded). source_*_id are provenance back-pointers (SET NULL on source delete). Immutable once the referral is sent (guard_referral_snapshot_lock).';



COMMENT ON COLUMN "public"."referral_shared_item"."frozen_body_md" IS 'PHI-bearing frozen narrative copy (sanitized Markdown). Loaded ONLY via the audited get_referral_detail door; never on list reads; never copied into the audit log (Rule 11/12).';



CREATE OR REPLACE FUNCTION "public"."add_referral_shared_item"("p_referral_id" "uuid", "p_kind" "text", "p_source_narrative_id" "uuid" DEFAULT NULL::"uuid", "p_source_document_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."referral_shared_item"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_referral public.case_referral;
  v_narrative public.case_narratives;
  v_document public.case_documents;
  v_next_pos integer;
  v_row public.referral_shared_item;
begin
  perform app.assert_referrals_enabled();
  v_referral := app.assert_referral_draft_writable(p_referral_id);

  if p_kind not in ('narrative', 'document') then
    raise exception 'tipo de item inválido' using errcode = 'HC077';
  end if;

  select coalesce(max(position), -1) + 1 into v_next_pos
  from public.referral_shared_item where referral_id = p_referral_id;

  perform set_config('app.in_referral_rpc', 'on', true);

  if p_kind = 'narrative' then
    if p_source_narrative_id is null then
      raise exception 'selecione a narrativa a compartilhar' using errcode = 'HC077';
    end if;
    select * into v_narrative from public.case_narratives
      where id = p_source_narrative_id and case_id = v_referral.source_case_id;
    if v_narrative.id is null then
      raise exception 'narrativa não encontrada neste caso' using errcode = 'HC077';
    end if;
    insert into public.referral_shared_item (
      referral_id, kind, source_narrative_id, frozen_title, frozen_body_md, position
    ) values (
      p_referral_id, 'narrative', v_narrative.id,
      coalesce(v_narrative.title, v_narrative.type_label),
      coalesce(v_narrative.body_md, ''), v_next_pos
    )
    returning * into v_row;
  else
    if p_source_document_id is null then
      raise exception 'selecione o documento a compartilhar' using errcode = 'HC077';
    end if;
    select * into v_document from public.case_documents
      where id = p_source_document_id and case_id = v_referral.source_case_id and deleted_at is null;
    if v_document.id is null then
      raise exception 'documento não encontrado neste caso' using errcode = 'HC077';
    end if;
    insert into public.referral_shared_item (
      referral_id, kind, source_document_id, frozen_title,
      frozen_storage_path, frozen_mime_type, frozen_size_bytes, position
    ) values (
      p_referral_id, 'document', v_document.id, v_document.title,
      v_document.storage_path, v_document.mime_type, v_document.size_bytes, v_next_pos
    )
    returning * into v_row;
  end if;

  perform set_config('app.in_referral_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."add_referral_shared_item"("p_referral_id" "uuid", "p_kind" "text", "p_source_narrative_id" "uuid", "p_source_document_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."process_template_narratives" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "template_id" "uuid" NOT NULL,
    "narrative_type_id" "uuid" NOT NULL,
    "display_position" integer NOT NULL,
    "title" "text",
    "instructions" "text",
    "is_expected" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."process_template_narratives" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_template_narrative"("p_template_id" "uuid", "p_narrative_type_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_instructions" "text" DEFAULT NULL::"text", "p_is_expected" boolean DEFAULT false) RETURNS "public"."process_template_narratives"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_commission_id uuid;
  v_position integer;
  v_result public.process_template_narratives;
begin
  perform app.assert_narratives_enabled();

  select status, commission_id into v_status, v_commission_id
  from public.process_templates
  where id = p_template_id;

  if v_status is null then
    raise exception 'processo % não encontrado', p_template_id
      using errcode = 'no_data_found';
  end if;
  if v_status <> 'draft' then
    raise exception 'apenas processos em rascunho podem ser editados'
      using errcode = 'check_violation';
  end if;

  -- Next display_position over BOTH slot kinds (the interleave). Phases fall back
  -- to `position` when their display_position is null — a phase added to the draft
  -- by the (unmodified) add_template_phase RPC leaves display_position null, but
  -- `position` is always present and the merge treats it as the display order
  -- (coalesce(display_position, position), same as get_case_detail / mergeCaseLayout).
  select coalesce(max(dp), 0) + 1 into v_position
  from (
    select coalesce(display_position, position) as dp
    from public.process_template_phases where template_id = p_template_id
    union all
    select display_position as dp
    from public.process_template_narratives where template_id = p_template_id
  ) s;

  insert into public.process_template_narratives
    (template_id, narrative_type_id, display_position, title, instructions, is_expected)
  values
    (p_template_id, p_narrative_type_id, v_position,
     nullif(btrim(p_title), ''), nullif(btrim(p_instructions), ''),
     coalesce(p_is_expected, false))
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."add_template_narrative"("p_template_id" "uuid", "p_narrative_type_id" "uuid", "p_title" "text", "p_instructions" "text", "p_is_expected" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."process_template_phases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "template_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "form_id" "uuid" NOT NULL,
    "title" "text",
    "recommend_when" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "default_due_days" integer,
    "blocks" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "display_position" integer,
    "result_ruleset" "jsonb",
    "emits_result" boolean DEFAULT false NOT NULL,
    "allowed_result_ids" "jsonb",
    CONSTRAINT "process_template_phases_allowed_shape" CHECK ((("allowed_result_ids" IS NULL) OR (("jsonb_typeof"("allowed_result_ids") = 'array'::"text") AND ("jsonb_array_length"("allowed_result_ids") >= 1)))),
    CONSTRAINT "process_template_phases_default_due_days_nonneg" CHECK ((("default_due_days" IS NULL) OR ("default_due_days" >= 0))),
    CONSTRAINT "process_template_phases_recommend_when_shape" CHECK ("app"."is_valid_recommend_when"("recommend_when")),
    CONSTRAINT "process_template_phases_result_emits" CHECK (("emits_result" OR (("result_ruleset" IS NULL) AND ("allowed_result_ids" IS NULL)))),
    CONSTRAINT "process_template_phases_result_ruleset_shape" CHECK ((("result_ruleset" IS NULL) OR (("jsonb_typeof"("result_ruleset") = 'object'::"text") AND ("result_ruleset" ? 'rules'::"text") AND ("jsonb_typeof"(("result_ruleset" -> 'rules'::"text")) = 'array'::"text") AND ("result_ruleset" ? 'default_result_id'::"text") AND ("jsonb_typeof"(("result_ruleset" -> 'default_result_id'::"text")) = ANY (ARRAY['string'::"text", 'null'::"text"])))))
);


ALTER TABLE "public"."process_template_phases" OWNER TO "postgres";


COMMENT ON COLUMN "public"."process_template_phases"."result_ruleset" IS 'Optional per-phase RESULT ruleset (phase-results feature): { "rules": [ { "when": {question_key,op,value}, "result_id": uuid }, … ], "default_result_id": uuid|null }. `when` is a PLAIN condition over THIS phase''s OWN answers (no from_phase). Deep-validated at publish (validate_template_result_ruleset); snapshotted onto case_phases.result_ruleset at case creation. Draft-only.';



COMMENT ON COLUMN "public"."process_template_phases"."emits_result" IS 'Whether this phase emits a result at all. false → NONE; true + result_ruleset → AUTOMATIC; true + no result_ruleset → MANUAL.';



COMMENT ON COLUMN "public"."process_template_phases"."allowed_result_ids" IS 'The author-selected allowed result subset (a non-empty jsonb array of phase_results uuids), present whenever the phase emits a result. MANUAL: the options the filler picks from. AUTOMATIC: the options the rules/default may reference. NULL when the phase emits no result.';



CREATE OR REPLACE FUNCTION "public"."add_template_phase"("p_template_id" "uuid", "p_form_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_recommend_when" "jsonb" DEFAULT NULL::"jsonb", "p_default_due_days" integer DEFAULT NULL::integer, "p_blocks" integer[] DEFAULT '{}'::integer[], "p_result_ruleset" "jsonb" DEFAULT NULL::"jsonb", "p_emits_result" boolean DEFAULT false, "p_allowed_result_ids" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."process_template_phases"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_commission_id uuid;
  v_position integer;
  v_blocks integer[];
  v_result public.process_template_phases;
begin
  perform app.assert_cases_enabled();

  select status, commission_id into v_status, v_commission_id
  from public.process_templates
  where id = p_template_id;

  if v_status is null then
    raise exception 'processo % não encontrado', p_template_id
      using errcode = 'no_data_found';
  end if;
  if v_status <> 'draft' then
    raise exception 'apenas processos em rascunho podem ser editados'
      using errcode = 'check_violation';
  end if;

  if not exists (
    select 1 from public.forms
    where id = p_form_id and commission_id = v_commission_id
  ) then
    raise exception 'o formulário não pertence a esta comissão'
      using errcode = 'check_violation';
  end if;

  select coalesce(max(position), 0) + 1 into v_position
  from public.process_template_phases
  where template_id = p_template_id;

  v_blocks := coalesce(
    (select array_agg(distinct b order by b)
     from unnest(p_blocks) as b
     where b is not null),
    '{}');

  insert into public.process_template_phases
    (template_id, position, form_id, title, recommend_when, default_due_days,
     blocks, result_ruleset, emits_result, allowed_result_ids)
  values
    (p_template_id, v_position, p_form_id, nullif(btrim(p_title), ''),
     p_recommend_when, p_default_due_days, v_blocks,
     p_result_ruleset, p_emits_result, p_allowed_result_ids)
  returning * into v_result;

  perform app.validate_template_recommend_when(p_template_id, v_position, p_recommend_when);
  perform app.validate_template_phase_blocks(p_template_id, v_position, v_blocks);
  perform app.validate_template_result_ruleset(p_template_id, v_position, p_result_ruleset);
  perform app.validate_template_allowed_results(p_template_id, v_position, p_allowed_result_ids);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."add_template_phase"("p_template_id" "uuid", "p_form_id" "uuid", "p_title" "text", "p_recommend_when" "jsonb", "p_default_due_days" integer, "p_blocks" integer[], "p_result_ruleset" "jsonb", "p_emits_result" boolean, "p_allowed_result_ids" "jsonb") OWNER TO "postgres";


