    "phi_disposed_by" "uuid",
    "phi_disposed_reason" "text",
    CONSTRAINT "cases_phi_disposed_reason_check" CHECK ((("phi_disposed_reason" IS NULL) OR ("phi_disposed_reason" = ANY (ARRAY['retention_expired'::"text", 'subject_request'::"text", 'entered_in_error'::"text", 'duplicate'::"text", 'other'::"text"])))),
    CONSTRAINT "cases_status_check" CHECK (("status" = ANY (ARRAY['nao_iniciado'::"text", 'pendente'::"text", 'em_revisao'::"text", 'concluido'::"text", 'cancelado'::"text"])))
);


ALTER TABLE "public"."cases" OWNER TO "postgres";


COMMENT ON COLUMN "public"."cases"."has_patient" IS 'Denormalized "an isolated case_patient (PHI) row exists" flag. Set true by set_case_patient, false by PHI disposal (dispose_case_phi). Lets governance/list reads derive hasPatient WITHOUT embedding case_patient (which is not directly SELECT-able). A boolean is not PHI.';



COMMENT ON COLUMN "public"."cases"."patient_enabled" IS 'Snapshotted at case creation from process_templates.collects_patient (immutable per case). When true (AND the case_patient flag is on) the create dialog + detail panel offer the optional PHI block. Existing/other templates stay PHI-free.';



COMMENT ON COLUMN "public"."cases"."phi_disposed_at" IS 'When the case PHI was disposed (NULL until disposal). PHI-safe accountability stamp set by dispose_case_phi; one-shot.';



COMMENT ON COLUMN "public"."cases"."phi_disposed_by" IS 'Who disposed the case PHI (NULL until disposal). PHI-safe accountability stamp set by dispose_case_phi.';



COMMENT ON COLUMN "public"."cases"."phi_disposed_reason" IS 'WHY the PHI was disposed — a CONSTRAINED CATEGORY (retention_expired/subject_request/entered_in_error/duplicate/other), NEVER free text (Rule 11 + LGPD Art. 18). NULL until disposal.';



CREATE OR REPLACE FUNCTION "public"."cancel_case"("p_case_id" "uuid") RETURNS "public"."cases"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_result public.cases;
begin
  perform app.assert_cases_enabled();

  select status into v_status from public.cases where id = p_case_id;
  if v_status is null then
    raise exception 'caso % não encontrado', p_case_id using errcode = 'no_data_found';
  end if;
  if v_status in ('concluido', 'cancelado') then
    raise exception 'este caso está em um estado final e não pode mais ser alterado'
      using errcode = 'HC025';
  end if;

  perform set_config('app.in_case_rpc', 'on', true);

  -- Terminal FIRST: freeze the case, then the phase flips' recompute no-ops.
  update public.cases
  set status = 'cancelado', closed_at = now(), closed_by = auth.uid()
  where id = p_case_id
  returning * into v_result;

  update public.case_phases
  set status = 'nao_necessaria', skipped_at = coalesce(skipped_at, now()), updated_at = now()
  where case_id = p_case_id and status in ('pendente', 'ativa');

  perform set_config('app.in_case_rpc', 'off', true);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."cancel_case"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_event"("p_event_id" "uuid") RETURNS "public"."patient_safety_event"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_event public.patient_safety_event;
  v_status text;
begin
  perform app.assert_patient_safety_enabled();

  if not app.can_read_event(p_event_id, auth.uid()) then
    raise exception 'evento não encontrado' using errcode = 'P0002';
  end if;
  if not app.event_current_custodian(p_event_id, auth.uid()) then
    raise exception 'apenas quem detém a custódia do evento pode cancelá-lo'
      using errcode = 'HC044';
  end if;

  select status into v_status from public.patient_safety_event where id = p_event_id;
  if v_status in ('closed', 'cancelled') then
    raise exception 'este evento já está em um estado final' using errcode = 'HC043';
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.patient_safety_event
  set status = 'cancelled', closed_by = auth.uid(), closed_at = now(), updated_at = now()
  where id = p_event_id
  returning * into v_event;
  perform set_config('app.in_safety_rpc', 'off', true);

  return v_event;
end;
$$;


ALTER FUNCTION "public"."cancel_event"("p_event_id" "uuid") OWNER TO "postgres";


