CREATE OR REPLACE FUNCTION "public"."clone_form_version"("p_source_version_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_form_id uuid;
  v_next_number integer;
  v_new_version_id uuid;
  v_uid uuid := auth.uid();
  v_existing_draft uuid;
begin
  select form_id into v_form_id
  from public.form_versions
  where id = p_source_version_id;

  if v_form_id is null then
    raise exception 'versão % não encontrada', p_source_version_id
      using errcode = 'no_data_found';
  end if;

  -- ADR 0012: at most one draft per form — return the existing draft if present.
  select id into v_existing_draft
  from public.form_versions
  where form_id = v_form_id and status = 'draft'
  limit 1;

  if v_existing_draft is not null then
    return v_existing_draft;
  end if;

  select coalesce(max(version_number), 0) + 1 into v_next_number
  from public.form_versions
  where form_id = v_form_id;

  insert into public.form_versions (form_id, version_number, status, created_by)
  values (v_form_id, v_next_number, 'draft', v_uid)
  returning id into v_new_version_id;

  create temp table _clone_section_map (old_id uuid, new_id uuid) on commit drop;
  create temp table _clone_item_map (old_id uuid, new_id uuid) on commit drop;

  with src as (
    select id, position, title, description, is_default,
           visible_when, requires_signoff, signoff_role
    from public.form_sections
    where form_version_id = p_source_version_id
  ),
  ins as (
    insert into public.form_sections (
      form_version_id, position, title, description, is_default,
      visible_when, requires_signoff, signoff_role
    )
    select v_new_version_id, position, title, description, is_default,
           visible_when, requires_signoff, signoff_role
    from src
    order by position
    returning id, position
  )
  insert into _clone_section_map (old_id, new_id)
  select src.id, ins.id
  from src
  join ins on ins.position = src.position;

  -- Copy items into the remapped sections, capturing the old->new item id map
  -- (keyed by the remapped section + position, unique per version) so the option
  -- copy can rewrite item_id and the parent_item_id remap can run. config +
  -- visible_when + default_value copy verbatim (all reference clone-stable ids:
  -- question_key + option code, both preserved). parent_item_id is copied here as
  -- the OLD id, then remapped below.
  with src as (
    select i.id, m.new_id as new_section_id, i.position, i.item_type,
           i.question_key, i.label, i.question_explanation, i.config,
           i.visible_when, i.required, i.content, i.default_value, i.parent_item_id
    from public.form_items i
    join public.form_sections s on s.id = i.section_id
    join _clone_section_map m on m.old_id = i.section_id
    where s.form_version_id = p_source_version_id
  ),
  ins as (
    insert into public.form_items (
      section_id, position, item_type,
      question_key, label, question_explanation, config, visible_when,
      required, content, default_value
    )
    select new_section_id, position, item_type,
           question_key, label, question_explanation, config, visible_when,
           required, content, default_value
    from src
    returning id, section_id, position
  )
  insert into _clone_item_map (old_id, new_id)
  select src.id, ins.id
  from src
  join ins on ins.section_id = src.new_section_id and ins.position = src.position;

  -- Remap parent_item_id from the source item id to the newly-cloned item id.
  -- All values are NULL today, so this is inert but keeps the model coherent for
  -- when repeating groups ship.
  update public.form_items c
  set parent_item_id = pm.new_id
  from public.form_items src
  join _clone_item_map im on im.old_id = src.id
  join _clone_item_map pm on pm.old_id = src.parent_item_id
  where c.id = im.new_id
    and src.parent_item_id is not null;

  -- Copy option rows into the remapped items, preserving code/label/color_token/
  -- score/analytics_code/position VERBATIM (the sync trigger refills
  -- form_version_id from the item).
  insert into public.form_item_options (
    item_id, position, code, label, color_token, score, analytics_code
  )
  select m.new_id, o.position, o.code, o.label, o.color_token, o.score, o.analytics_code
  from public.form_item_options o
  join _clone_item_map m on m.old_id = o.item_id;

  drop table _clone_section_map;
  drop table _clone_item_map;

  return v_new_version_id;
end;
$$;


ALTER FUNCTION "public"."clone_form_version"("p_source_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_capa_plan"("p_capa_id" "uuid", "p_lessons_learned_md" "text" DEFAULT NULL::"text") RETURNS "public"."capa_plan"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_plan public.capa_plan;
  v_status text;
  v_event uuid;
begin
  perform app.assert_patient_safety_enabled();
  perform app.assert_capa_writable(p_capa_id);

  select status into v_status from public.capa_plan where id = p_capa_id;
  if v_status not in ('em_execucao', 'em_verificacao') then
    raise exception 'apenas um plano em execução ou verificação pode ser encerrado'
      using errcode = 'HC049';
  end if;
  -- Conclude gate: no unsettled (non-terminal) action.
  if exists (
    select 1 from public.capa_action
    where capa_id = p_capa_id and status not in ('concluida', 'cancelada')
  ) then
    raise exception 'conclua ou cancele todas as ações antes de encerrar o plano'
      using errcode = 'HC051';
  end if;
  -- Conclude gate: an effectiveness verdict is required.
  if not exists (select 1 from public.capa_effectiveness where capa_id = p_capa_id) then
    raise exception 'registre a verificação de eficácia antes de encerrar o plano'
      using errcode = 'HC052';
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.capa_plan
  set status = 'concluido', lessons_learned_md = p_lessons_learned_md,
      closed_by = auth.uid(), closed_at = now(), updated_at = now()
  where id = p_capa_id
  returning * into v_plan;

  -- Close->event side effect (best-effort): if the event is fully settled + triaged.
  v_event := app.event_of_capa(p_capa_id);
  if v_event is not null and app.event_capa_fully_settled(v_event) then
    update public.patient_safety_event
    set status = 'closed', closed_by = auth.uid(), closed_at = now(), updated_at = now()
    where id = v_event and status = 'triaged';
  end if;
  perform set_config('app.in_safety_rpc', 'off', true);

  return v_plan;
end;
$$;


ALTER FUNCTION "public"."close_capa_plan"("p_capa_id" "uuid", "p_lessons_learned_md" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_case"("p_case_id" "uuid") RETURNS "public"."cases"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_outcome_id uuid;
  v_unsettled integer;
  v_offered integer;
  v_result public.cases;
begin
  perform app.assert_cases_enabled();

  select status, outcome_id into v_status, v_outcome_id
  from public.cases where id = p_case_id;
  if v_status is null then
    raise exception 'caso % não encontrado', p_case_id using errcode = 'no_data_found';
  end if;
  if v_status in ('concluido', 'cancelado') then
    raise exception 'este caso está em um estado final e não pode mais ser alterado'
      using errcode = 'HC025';
  end if;

  -- D3 gate 1: every phase must be settled (concluida or nao_necessaria).
  select count(*) into v_unsettled
  from public.case_phases
  where case_id = p_case_id and status in ('pendente', 'ativa');
  if v_unsettled > 0 then
    raise exception 'conclua ou marque todas as fases antes de concluir o caso'
      using errcode = 'HC031';
  end if;

  -- D3 gate 2: a process that OFFERS outcomes requires one selected.
  select count(*) into v_offered
  from public.case_offered_outcomes where case_id = p_case_id;
  if v_offered > 0 and v_outcome_id is null then
    raise exception 'selecione um desfecho antes de concluir o caso'
      using errcode = 'HC028';
  end if;

  -- Phase 22 (Decision 5): a reply-expecting referral still in flight blocks the
  -- close. rascunho (unsent) is excluded; response_expected=false never blocks.
  if app.feature_enabled('case_referrals') and exists (
    select 1 from public.case_referral r
    where r.source_case_id = p_case_id and r.response_expected = true
      and r.status in ('enviada', 'recebida', 'aceita', 'em_analise')
  ) then
    raise exception 'há encaminhamentos aguardando resposta; conclua, recuse ou retire antes de encerrar o caso'
      using errcode = 'HC076';
  end if;

  perform set_config('app.in_case_rpc', 'on', true);

  -- Terminal FIRST: freeze the case, then any residual phase flip no-ops.
  update public.cases
  set status = 'concluido', closed_at = now(), closed_by = auth.uid()
  where id = p_case_id
  returning * into v_result;

  update public.case_phases
  set status = 'nao_necessaria', skipped_at = coalesce(skipped_at, now()), updated_at = now()
  where case_id = p_case_id and status in ('pendente', 'ativa');

  perform set_config('app.in_case_rpc', 'off', true);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."close_case"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commission_derive_organization_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if new.hospital_id is not null then
    select h.organization_id into new.organization_id
    from public.hospitals h
    where h.id = new.hospital_id;
  else
    -- No hospital => no org. Transient pre-reseed state only.
    new.organization_id := null;
  end if;
  return new;
end;
$$;


