    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "event_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "due_date" "date",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "what_md" "text",
    "expected_md" "text",
    "detected" "text",
    "impact" "text",
    "scope" "text",
    "summary_md" "text",
    "submitted_by" "uuid",
    "submitted_at" timestamp with time zone,
    "completed_by" "uuid",
    "completed_at" timestamp with time zone,
    CONSTRAINT "rca_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'in_progress'::"text", 'in_review'::"text", 'completed'::"text"])))
);


ALTER TABLE "public"."rca" OWNER TO "postgres";


COMMENT ON TABLE "public"."rca" IS 'FORWARD-SAFE RCA shell (Phase 14b seam; ADR 0032). Created by confirm_triage when pathway = rca, with the configurable 45-day due_date. Phase 14c EXTENDS this table (its ALTERs must tolerate pre-existing rows: nullable/defaulted columns only).';



COMMENT ON COLUMN "public"."rca"."what_md" IS 'PHI-BEARING free text (WS B; Rule 11/12). RCA problem statement (what happened); audited via rca.viewed; never copied into the audit log.';



COMMENT ON COLUMN "public"."rca"."expected_md" IS 'PHI-BEARING free text (WS B; Rule 11/12). RCA expected-course narrative; audited via rca.viewed; never copied into the audit log.';



COMMENT ON COLUMN "public"."rca"."impact" IS 'PHI-BEARING free text (WS B; Rule 11/12). RCA impact narrative; audited via rca.viewed; never copied into the audit log.';



COMMENT ON COLUMN "public"."rca"."scope" IS 'PHI-BEARING free text (WS B; Rule 11/12). RCA scope narrative; audited via rca.viewed; never copied into the audit log.';



COMMENT ON COLUMN "public"."rca"."summary_md" IS 'PHI-BEARING free text (WS B; Rule 11/12). RCA summary/conclusion narrative; audited via rca.viewed; never copied into the audit log.';



CREATE OR REPLACE FUNCTION "public"."complete_rca"("p_rca_id" "uuid") RETURNS "public"."rca"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_rca public.rca;
begin
  perform app.assert_patient_safety_enabled();
  perform app.assert_rca_writable(p_rca_id);

  if (select status from public.rca where id = p_rca_id) <> 'in_review' then
    raise exception 'apenas uma análise em revisão pode ser concluída' using errcode = 'HC047';
  end if;
  if not exists (select 1 from public.rca_root_causes where rca_id = p_rca_id) then
    raise exception 'conclua a análise com ao menos uma causa raiz identificada'
      using errcode = 'HC047';
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.rca
  set status = 'completed', completed_by = auth.uid(), completed_at = now(), updated_at = now()
  where id = p_rca_id
  returning * into v_rca;
  perform set_config('app.in_safety_rpc', 'off', true);

  return v_rca;
end;
$$;


ALTER FUNCTION "public"."complete_rca"("p_rca_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."conclude_interview"("p_interview_id" "uuid") RETURNS "public"."case_interviews"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_status text;
  v_case_id uuid;
  v_number integer;
  v_summary text;
  v_conducted timestamptz;
  v_existing_event uuid;
  v_subject_count integer;
  v_subjects text;
  v_title text;
  v_body text;
  v_event_id uuid;
  v_result public.case_interviews;
begin
  perform app.assert_interviews_enabled();
  v_commission_id := app.assert_interview_writable(p_interview_id);

  select status, case_id, interview_number, summary_md, conducted_at, registry_event_id
    into v_status, v_case_id, v_number, v_summary, v_conducted, v_existing_event
  from public.case_interviews where id = p_interview_id;

  if v_status <> 'em_andamento' then
    raise exception 'apenas entrevistas em andamento podem ser concluídas' using errcode = 'HC038';
  end if;

  -- Require >= 1 interviewee (resolved decision; HC041).
  select count(*) into v_subject_count
  from public.case_interview_subjects where interview_id = p_interview_id;
  if v_subject_count < 1 then
    raise exception 'adicione ao menos um entrevistado antes de concluir' using errcode = 'HC041';
  end if;

  -- Compose the timeline entry. Subjects roster = resolved display names.
  select string_agg(coalesce(p.full_name, s.external_name, 'Entrevistado'), ', ')
    into v_subjects
  from public.case_interview_subjects s
  left join public.profiles p on p.id = s.user_id
  where s.interview_id = p_interview_id;

  v_title := 'Entrevista nº ' || v_number
    || coalesce(': ' || nullif(btrim(v_subjects), ''), '');
  v_body := coalesce(nullif(btrim(v_summary), ''), 'Entrevista concluída.');

  perform set_config('app.in_interview_rpc', 'on', true);

  if v_existing_event is null then
    insert into public.case_events (case_id, kind, title, body, occurred_at, created_by)
    values (v_case_id, 'interview', v_title, v_body,
            coalesce(v_conducted::date, current_date), auth.uid())
    returning id into v_event_id;
  else
    -- Re-conclude after a reopen: UPDATE the same row (no duplicate timeline entry).
    update public.case_events
    set title = v_title, body = v_body,
        occurred_at = coalesce(v_conducted::date, current_date),
        updated_at = now()
    where id = v_existing_event;
    v_event_id := v_existing_event;
  end if;

  update public.case_interviews
  set status = 'concluida', concluded_at = now(), concluded_by = auth.uid(),
      registry_event_id = v_event_id
  where id = p_interview_id
  returning * into v_result;

  perform set_config('app.in_interview_rpc', 'off', true);
  return v_result;
end;
$$;


ALTER FUNCTION "public"."conclude_interview"("p_interview_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."conclude_meeting"("p_meeting_id" "uuid") RETURNS "public"."meetings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_status text;
  v_rule text;
  v_value numeric;
  v_present integer;
  v_eligible integer;
  v_quorum_met boolean;
  v_result public.meetings;
  r_link record;
begin
  perform app.assert_meetings_enabled();

  select commission_id, status into v_commission_id, v_status
  from public.meetings where id = p_meeting_id;
  if v_commission_id is null then
    raise exception 'reunião % não encontrada', p_meeting_id using errcode = 'no_data_found';
  end if;
  -- DEFINER: internal staff_admin gate (the RLS bypass is intentional, so the
  -- gate is the authority).
  if not (app.is_staff_admin_of(v_commission_id) or app.is_org_admin_of_commission(v_commission_id)) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;
  -- Conclude is reachable from agendada OR realizada. The lifecycle is
  -- agendada -> realizada -> em_assinatura; "Concluir" is the single staff action
  -- that records the meeting as HELD and sends the ata to signature, so when the
  -- meeting is still agendada it is first advanced through realizada (a guarded
  -- step) before the conclusion flip. This keeps the frozen frontend contract
  -- (concludeMeeting(meetingId), no separate "mark held" action) intact.
  if v_status not in ('agendada', 'realizada') then
    raise exception 'apenas reuniões agendadas ou realizadas podem ser concluídas'
      using errcode = 'HC033';
  end if;

  -- Quorum math (snapshot at conclusion; resolved design decision 7).
  -- present_count counts PRESENT PLATFORM attendees only: external guests
  -- (user_id is null) never count toward quorum (ADR 0025 / plan §7), and this
  -- must match the sign_meeting auto-flip's "required signers" set, which is
  -- likewise `user_id is not null and attendance = 'presente'`.
  select count(*) into v_eligible
  from public.commission_members where commission_id = v_commission_id;
  select count(*) into v_present
  from public.meeting_attendees
  where meeting_id = p_meeting_id and attendance = 'presente' and user_id is not null;

  if v_present < 1 then
    raise exception 'registre ao menos um participante presente antes de concluir'
      using errcode = 'HC034';
  end if;

  select quorum_rule_type, quorum_value into v_rule, v_value
  from public.commission_meeting_settings where commission_id = v_commission_id;
  v_rule := coalesce(v_rule, 'maioria_simples');

  v_quorum_met := case v_rule
    when 'maioria_simples' then v_present > v_eligible / 2.0
    when 'fixed_count' then v_present >= coalesce(v_value, 0)
    when 'percentage' then v_present >= ceil(v_eligible * coalesce(v_value, 0) / 100.0)
    else false
  end;

  perform set_config('app.in_meeting_rpc', 'on', true);

  -- The guard permits agendada->realizada and realizada->em_assinatura, but NOT
  -- agendada->em_assinatura directly. If still agendada, step through realizada
  -- first (under the flag) so both legal transitions are honoured.
  if v_status = 'agendada' then
    update public.meetings set status = 'realizada', updated_at = now()
    where id = p_meeting_id;
  end if;

  update public.meetings
  set status = 'em_assinatura',
      quorum_rule_type = v_rule,
      quorum_value = v_value,
      present_count = v_present,
      eligible_member_count = v_eligible,
      quorum_met = v_quorum_met,
      concluded_at = now(),
      concluded_by = auth.uid(),
      updated_at = now()
  where id = p_meeting_id
  returning * into v_result;

  -- Write a case_events (kind='meeting') row per linked case (resolved design
  -- decision 4) so the discussion shows on the case timeline.
  for r_link in
    select mc.case_id, mc.summary, mc.decision, m.meeting_number
    from public.meeting_cases mc
    join public.meetings m on m.id = mc.meeting_id
    where mc.meeting_id = p_meeting_id
  loop
    insert into public.case_events (case_id, kind, title, body, occurred_at, created_by)
    values (
      r_link.case_id,
      'meeting',
      'Discutido na Reunião nº ' || r_link.meeting_number,
      coalesce(
        nullif(btrim(concat_ws(E'\n\n',
          nullif(btrim(r_link.summary), ''),
          case when nullif(btrim(r_link.decision), '') is not null
               then 'Decisão: ' || btrim(r_link.decision) end
        )), ''),
        'Caso discutido nesta reunião.'
      ),
      current_date,
      auth.uid()
    );
  end loop;

  perform set_config('app.in_meeting_rpc', 'off', true);
  return v_result;
end;
$$;


ALTER FUNCTION "public"."conclude_meeting"("p_meeting_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."conclude_narrative"("p_narrative" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission uuid;
  v_case_status text;
  v_status text;
  v_assigned uuid;
begin
  perform app.assert_case_access_enabled();

  select c.commission_id, c.status, cn.status, cn.assigned_to
    into v_commission, v_case_status, v_status, v_assigned
  from public.case_narratives cn
  join public.cases c on c.id = cn.case_id
  where cn.id = p_narrative;

  if v_status is null then
    raise exception 'narrativa % não encontrada', p_narrative using errcode = 'no_data_found';
  end if;
  -- The assignee OR a coordinator/admin may conclude.
  if not (v_assigned = auth.uid()
          or app.is_staff_admin_of(v_commission) or app.is_org_admin_of_commission(v_commission)) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;
  if v_case_status in ('concluido', 'cancelado') then
    raise exception 'este caso está em um estado final e não pode mais ser alterado'
      using errcode = 'HC020';
  end if;
  if v_status <> 'aberta' then
    raise exception 'a narrativa não está no estado necessário para esta ação'
      using errcode = 'HC055';
  end if;

  perform set_config('app.in_narrative_rpc', 'on', true);
  update public.case_narratives
  set status = 'concluida', concluded_at = now(), concluded_by = auth.uid(),
      updated_by = auth.uid()
  where id = p_narrative;
  perform set_config('app.in_narrative_rpc', 'off', true);
end;
$$;


ALTER FUNCTION "public"."conclude_narrative"("p_narrative" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."conclude_referral"("p_referral_id" "uuid", "p_reply_outcome_id" "uuid" DEFAULT NULL::"uuid", "p_result_md" "text" DEFAULT NULL::"text", "p_acknowledged_only" boolean DEFAULT false) RETURNS "public"."case_referral"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_referral public.case_referral;
  v_outcome public.reply_outcomes;
  v_ack boolean;
  v_row public.case_referral;
begin
  perform app.assert_referrals_enabled();
  v_referral := app.assert_referral_target_acts(p_referral_id, array['em_analise']);

  -- A reply IS expected unless the referral was marked no-reply AND the caller
  -- explicitly acknowledges only.
  v_ack := coalesce(p_acknowledged_only, false) and not v_referral.response_expected;

  if v_referral.response_expected then
    if btrim(coalesce(p_result_md, '')) = '' then
      raise exception 'descreva o resultado da análise para concluir' using errcode = 'HC075';
    end if;
    if p_reply_outcome_id is null then
      raise exception 'selecione o desfecho da análise para concluir' using errcode = 'HC075';
    end if;
  end if;

  if p_reply_outcome_id is not null then
    select * into v_outcome from public.reply_outcomes where id = p_reply_outcome_id;
    if v_outcome.id is null then
      raise exception 'desfecho de resposta inválido' using errcode = 'HC074';
    end if;
  end if;

  perform set_config('app.in_referral_rpc', 'on', true);

  insert into public.referral_reply (
    referral_id, reply_outcome_id, outcome_label, result_md, acknowledged_only,
    replied_by, replied_at
  ) values (
    p_referral_id, v_outcome.id, v_outcome.label,
    case when v_ack then null else p_result_md end, v_ack,
    auth.uid(), now()
  )
  on conflict (referral_id) do update
  set reply_outcome_id = excluded.reply_outcome_id, outcome_label = excluded.outcome_label,
      result_md = excluded.result_md, acknowledged_only = excluded.acknowledged_only,
      replied_by = excluded.replied_by, replied_at = excluded.replied_at, updated_at = now();

  update public.case_referral
  set status = 'concluida', concluded_at = now(), concluded_by = auth.uid(), updated_at = now()
  where id = p_referral_id
  returning * into v_row;

  perform set_config('app.in_referral_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."conclude_referral"("p_referral_id" "uuid", "p_reply_outcome_id" "uuid", "p_result_md" "text", "p_acknowledged_only" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."event_triage" (
    "event_id" "uuid" NOT NULL,
    "is_pse" boolean,
    "pse_closure_reason" "text",
    "reach" "text",
    "harm_severity" "text",
    "natural_course" boolean,
    "sentinel_determination" boolean DEFAULT false NOT NULL,
    "review_pathway" "text",
    "disposition_notes_md" "text",
    "triaged_by" "uuid",
    "triaged_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "event_triage_harm_severity_check" CHECK (("harm_severity" = ANY (ARRAY['none'::"text", 'mild'::"text", 'moderate'::"text", 'severe'::"text", 'permanent'::"text", 'death'::"text"]))),
    CONSTRAINT "event_triage_pse_closure_reason_check" CHECK (("pse_closure_reason" = ANY (ARRAY['natural'::"text", 'expected'::"text", 'nonclinical'::"text", 'duplicate'::"text"]))),
    CONSTRAINT "event_triage_pse_shape" CHECK ((("is_pse" IS NULL) OR (("is_pse" = false) AND ("pse_closure_reason" IS NOT NULL) AND ("reach" IS NULL) AND ("harm_severity" IS NULL)) OR (("is_pse" = true) AND ("pse_closure_reason" IS NULL)))),
    CONSTRAINT "event_triage_reach_check" CHECK (("reach" = ANY (ARRAY['unsafe'::"text", 'near_miss'::"text", 'no_harm'::"text", 'adverse'::"text", 'sentinel'::"text"]))),
    CONSTRAINT "event_triage_review_pathway_check" CHECK (("review_pathway" = ANY (ARRAY['rca'::"text", 'peer_review'::"text", 'mm'::"text", 'fmea'::"text", 'tracking_only'::"text"])))
);


ALTER TABLE "public"."event_triage" OWNER TO "postgres";


COMMENT ON TABLE "public"."event_triage" IS 'The 1:1 triage worksheet (Phase 14b). PHI-FREE governance metadata. Reach/harm are FIXED CHECK enums; sentinel_determination is auto-computed. Frozen once the parent event reaches "triaged" (app.guard_event_triage). disposition_notes_md is clinical free text — NEVER copied into the audit log (Rule 11).';



COMMENT ON COLUMN "public"."event_triage"."disposition_notes_md" IS 'PHI-BEARING free text (WS B; Rule 11/12). Triage disposition rationale (sanitized Markdown); audited via triage.viewed; never copied into the audit log.';



CREATE OR REPLACE FUNCTION "public"."confirm_triage"("p_event_id" "uuid") RETURNS "public"."event_triage"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_triage public.event_triage;
  v_event public.patient_safety_event;
  v_due_days integer;
  v_anchor date;
  v_pathway text;
begin
  perform app.assert_patient_safety_enabled();

  if not app.can_read_event(p_event_id, auth.uid()) then
    raise exception 'evento não encontrado' using errcode = 'P0002';
  end if;
  if not app.is_pqs_member_of(app.org_of_event(p_event_id)) then
    raise exception 'apenas o NSP pode triar eventos' using errcode = '42501';
  end if;

  select * into v_event from public.patient_safety_event where id = p_event_id;
  if v_event.status <> 'acknowledged' then
    raise exception 'a triagem só pode ser confirmada a partir de um evento reconhecido'
      using errcode = 'HC045';
  end if;

  select * into v_triage from public.event_triage where event_id = p_event_id;
  if not found or v_triage.is_pse is null then
    raise exception 'complete a triagem antes de confirmá-la' using errcode = 'HC046';
  end if;

  if v_triage.is_pse = false then
    if v_triage.pse_closure_reason is null then
      raise exception 'selecione o motivo de encerramento' using errcode = 'HC046';
    end if;

    perform set_config('app.in_safety_rpc', 'on', true);
    update public.event_triage
    set review_pathway = null, triaged_by = auth.uid(), triaged_at = now(), updated_at = now()
    where event_id = p_event_id
    returning * into v_triage;

    update public.patient_safety_event
    set status = 'closed', closed_by = auth.uid(), closed_at = now(), updated_at = now()
    where id = p_event_id;
    perform set_config('app.in_safety_rpc', 'off', true);

    return v_triage;
  end if;

  if v_triage.reach is null then
    raise exception 'classifique o alcance do evento antes de confirmar' using errcode = 'HC046';
  end if;

  if v_triage.sentinel_determination then
    if v_triage.review_pathway is not null and v_triage.review_pathway <> 'rca' then
      raise exception 'eventos sentinela exigem RCA — o desfecho não pode ser alterado'
        using errcode = 'HC046';
    end if;
    v_pathway := 'rca';
  else
    v_pathway := coalesce(v_triage.review_pathway, 'peer_review');
    if v_pathway = 'rca' then
      null;
    end if;
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.event_triage
  set review_pathway = v_pathway, triaged_by = auth.uid(), triaged_at = now(), updated_at = now()
  where event_id = p_event_id
  returning * into v_triage;

  update public.patient_safety_event
  set status = 'triaged', updated_at = now()
  where id = p_event_id;

  -- Pathway = rca ⇒ mint the configurable due date from THIS event's ORG config.
  if v_pathway = 'rca' then
    select rca_default_due_days into v_due_days
    from public.pqs_department where organization_id = app.org_of_event(p_event_id);
    v_due_days := coalesce(v_due_days, 45);
    v_anchor := coalesce(v_event.discovered_at, v_event.reported_at::date);

    insert into public.rca (event_id, status, due_date, created_by)
    values (p_event_id, 'draft', v_anchor + v_due_days, auth.uid())
    on conflict (event_id) do nothing;
  end if;

  perform set_config('app.in_safety_rpc', 'off', true);
  return v_triage;
end;
$$;


ALTER FUNCTION "public"."confirm_triage"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_action_item"("p_case_id" "uuid", "p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_assigned_to" "uuid" DEFAULT NULL::"uuid", "p_due_date" "date" DEFAULT NULL::"date", "p_source_case_phase_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."case_action_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_result public.case_action_items;
begin
  perform app.assert_extras_enabled();

  v_commission_id := app.commission_of_case(p_case_id);
  if v_commission_id is null then
    raise exception 'caso % não encontrado', p_case_id using errcode = 'no_data_found';
  end if;
  -- Authority broadened (ADR 0033 D4): coordinator/admin OR a case-write grantee.
  if not app.can_write_case_content(p_case_id, auth.uid()) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;
  if nullif(btrim(p_title), '') is null then
    raise exception 'informe o título do item' using errcode = 'check_violation';
  end if;
  if p_assigned_to is not null and not app.is_member_of_for(v_commission_id, p_assigned_to) then
    raise exception 'o responsável deve ser membro da comissão' using errcode = 'HC021';
  end if;
  if p_source_case_phase_id is not null and not exists (
    select 1 from public.case_phases where id = p_source_case_phase_id and case_id = p_case_id
  ) then
    raise exception 'a fase de origem não pertence a este caso' using errcode = 'check_violation';
  end if;

  insert into public.case_action_items
    (case_id, source_case_phase_id, title, description, assigned_to, due_date, created_by)
  values
    (p_case_id, p_source_case_phase_id, btrim(p_title), nullif(btrim(p_description), ''),
     p_assigned_to, p_due_date, auth.uid())
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_action_item"("p_case_id" "uuid", "p_title" "text", "p_description" "text", "p_assigned_to" "uuid", "p_due_date" "date", "p_source_case_phase_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_case"("p_commission_id" "uuid", "p_label" "text" DEFAULT NULL::"text", "p_patient_enabled" boolean DEFAULT false, "p_outcome_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "public"."cases"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_case public.cases;
  v_attempt integer := 0;
  v_bad uuid;
begin
  perform app.assert_cases_enabled();
  perform app.assert_processless_cases_enabled();

  -- The commission must exist (DEFINER bypasses RLS -> validate explicitly).
  if not exists (select 1 from public.commissions where id = p_commission_id) then
    raise exception 'comissão % não encontrada', p_commission_id using errcode = 'no_data_found';
  end if;

  -- Authority: staff_admin of THIS commission OR platform admin. (The template
  -- minter omits is_admin(); creating a process-less case adds it so an admin
  -- can open one directly — consistent with the action's authorizeCommission.)
  if not (app.is_staff_admin_of(p_commission_id) or app.is_admin()) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;

  -- Validate the optional offered-outcome set: every id must exist, belong to
  -- THIS commission, and be non-archived (the per-case join table has NO guard
  -- trigger, so we validate here — the HC030 same-commission idiom).
  if cardinality(p_outcome_ids) > 0 then
    perform app.assert_extras_enabled();

    select oid into v_bad
    from unnest(p_outcome_ids) as oid
    where not exists (
      select 1 from public.case_outcomes o
      where o.id = oid
        and o.commission_id = p_commission_id
        and o.archived = false
    )
    limit 1;
    if found then
      raise exception 'este desfecho não pertence à comissão deste caso'
        using errcode = 'HC030';
    end if;
  end if;

  -- Insert the case; the mint_case_number_trg BEFORE-INSERT trigger sets
  -- case_number (it fires fine for a null-template insert). status defaults to
  -- 'nao_iniciado'. Bounded unique_violation retry for the per-commission number
  -- race (copied verbatim from the template minter).
  perform set_config('app.in_case_rpc', 'on', true);

  loop
    v_attempt := v_attempt + 1;
    begin
      insert into public.cases (commission_id, template_id, label, created_by, patient_enabled)
      values (p_commission_id, null, nullif(btrim(p_label), ''), auth.uid(), coalesce(p_patient_enabled, false))
      returning * into v_case;
      exit;
    exception
      when unique_violation then
        if v_attempt >= 3 then
          raise;
        end if;
    end;
  end loop;

  -- Persist the OFFERED outcome set when non-empty (the PK dedups). The conclude
  -- gate + selector read THIS. NO phases / narratives / offered-results / recompute.
  if cardinality(p_outcome_ids) > 0 then
    insert into public.case_offered_outcomes (case_id, outcome_id)
    select v_case.id, oid from unnest(p_outcome_ids) as oid
    on conflict do nothing;
  end if;

  perform set_config('app.in_case_rpc', 'off', true);

  return v_case;
end;
$$;


ALTER FUNCTION "public"."create_case"("p_commission_id" "uuid", "p_label" "text", "p_patient_enabled" boolean, "p_outcome_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_case_from_template"("p_template_id" "uuid", "p_label" "text" DEFAULT NULL::"text") RETURNS "public"."cases"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_status text;
  v_collects boolean;
  v_case public.cases;
  r_slot record;
  v_version uuid;
  v_attempt integer := 0;
  v_narratives_on boolean := app.feature_enabled('case_narratives');
begin
  perform app.assert_cases_enabled();

  select commission_id, status, collects_patient
    into v_commission_id, v_status, v_collects
  from public.process_templates where id = p_template_id;

  if v_commission_id is null then
    raise exception 'processo % não encontrado', p_template_id using errcode = 'no_data_found';
  end if;

  if not app.is_staff_admin_of(v_commission_id) then
    raise exception 'processo % não encontrado', p_template_id using errcode = 'no_data_found';
  end if;

  if v_status <> 'active' then
    raise exception 'apenas processos publicados podem iniciar casos'
      using errcode = 'check_violation';
  end if;

  perform set_config('app.in_case_rpc', 'on', true);

  loop
    v_attempt := v_attempt + 1;
    begin
      insert into public.cases (commission_id, template_id, label, created_by, patient_enabled)
      values (v_commission_id, p_template_id, nullif(btrim(p_label), ''), auth.uid(), coalesce(v_collects, false))
      returning * into v_case;
      exit;
    exception
      when unique_violation then
        if v_attempt >= 3 then
          raise;
        end if;
    end;
  end loop;

  for r_slot in
    select position, form_id, title, recommend_when, default_due_days, blocks,
           display_position, result_ruleset, emits_result, allowed_result_ids
    from public.process_template_phases
    where template_id = p_template_id
    order by position
  loop
    v_version := app.published_version_of_form(r_slot.form_id);
    if v_version is null then
      raise exception
        'o formulário da fase % ainda não foi publicado', r_slot.position
        using errcode = 'HC017';
    end if;

    -- Re-validate the recommend_when at materialization time against the now-
    -- published source forms (group-aware; ADR 0043). Replaces the former inline
    -- single-shape from_phase/question_key check.
    if r_slot.recommend_when is not null then
      perform app.validate_template_recommend_when(
        p_template_id, r_slot.position, r_slot.recommend_when
      );
    end if;

    insert into public.case_phases
      (case_id, position, form_id, form_version_id, title, recommend_when,
       is_ad_hoc, default_due_days, blocks, display_position, result_ruleset,
       emits_result, allowed_result_ids)
    values
      (v_case.id, r_slot.position, r_slot.form_id, v_version, r_slot.title,
       r_slot.recommend_when, false, r_slot.default_due_days, r_slot.blocks,
       coalesce(r_slot.display_position, r_slot.position), r_slot.result_ruleset,
       r_slot.emits_result, r_slot.allowed_result_ids);
  end loop;

  insert into public.case_offered_outcomes (case_id, outcome_id)
  select v_case.id, pto.outcome_id
  from public.process_template_outcomes pto
  where pto.template_id = p_template_id;

  -- Freeze the OFFERED RESULT set: every reachable result option for this case —
  -- automatic ruleset result_ids + default_result_id, PLUS every phase's allowed
  -- subset. The computed-path guard reads THIS; the override path (manual / adjust)
  -- is validated against the allowed subset + live vocabulary at set-time.
  insert into public.case_phase_offered_results (case_id, result_id)
  select distinct v_case.id, ids.rid
  from public.process_template_phases ph
  cross join lateral (
    select (r ->> 'result_id')::uuid as rid
    from jsonb_array_elements(coalesce(ph.result_ruleset -> 'rules', '[]'::jsonb)) as r
    union
    select (ph.result_ruleset ->> 'default_result_id')::uuid
    union
    select (m #>> '{}')::uuid
    from jsonb_array_elements(coalesce(ph.allowed_result_ids, '[]'::jsonb)) as m
  ) ids
  where ph.template_id = p_template_id
    and ids.rid is not null
  on conflict do nothing;

  if v_narratives_on then
    insert into public.case_narratives
      (case_id, narrative_type_id, type_label, display_position, title,
       instructions, is_expected, created_by)
    select v_case.id, ptn.narrative_type_id,
           coalesce(nullif(btrim(ptn.title), ''), cnt.label),
           ptn.display_position, ptn.title, ptn.instructions, ptn.is_expected,
           auth.uid()
    from public.process_template_narratives ptn
    join public.case_narrative_types cnt on cnt.id = ptn.narrative_type_id
    where ptn.template_id = p_template_id;
  end if;

  perform set_config('app.in_case_rpc', 'off', true);

  perform public.recompute_recommendations(v_case.id);

  return v_case;
end;
$$;


ALTER FUNCTION "public"."create_case_from_template"("p_template_id" "uuid", "p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_case_narrative_type"("p_commission_id" "uuid", "p_label" "text", "p_description" "text" DEFAULT NULL::"text") RETURNS "public"."case_narrative_types"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_position integer;
  v_result public.case_narrative_types;
begin
  perform app.assert_narratives_enabled();
  if not (app.is_staff_admin_of(p_commission_id) or app.is_org_admin_of_commission(p_commission_id)) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;
  if nullif(btrim(p_label), '') is null then
    raise exception 'informe o nome da narrativa' using errcode = 'check_violation';
  end if;

  select coalesce(max(position), 0) + 1 into v_position
  from public.case_narrative_types where commission_id = p_commission_id;

  insert into public.case_narrative_types
    (commission_id, label, description, position)
  values
    (p_commission_id, btrim(p_label), nullif(btrim(p_description), ''), v_position)
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_case_narrative_type"("p_commission_id" "uuid", "p_label" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_case_outcome"("p_commission_id" "uuid", "p_label" "text", "p_color_token" "text" DEFAULT 'muted'::"text", "p_requires_action_plan" boolean DEFAULT false, "p_is_adverse" boolean DEFAULT false) RETURNS "public"."case_outcomes"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_position integer;
  v_result public.case_outcomes;
begin
  perform app.assert_extras_enabled();
  if not (app.is_staff_admin_of(p_commission_id) or app.is_org_admin_of_commission(p_commission_id)) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;
  if nullif(btrim(p_label), '') is null then
    raise exception 'informe o nome do desfecho' using errcode = 'check_violation';
  end if;

  select coalesce(max(position), 0) + 1 into v_position
  from public.case_outcomes where commission_id = p_commission_id;

  insert into public.case_outcomes
    (commission_id, label, color_token, requires_action_plan, is_adverse, position)
