CREATE OR REPLACE FUNCTION "public"."get_event_patient"("p_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_event public.patient_safety_event;
  v_patient public.event_patient;
begin
  -- WS A: the SINGLE audited door to the isolated PHI identifiers. Direct SELECT
  -- on public.event_patient is revoked from authenticated, so this DEFINER RPC is
  -- the only read path — the Rule-11 read-audit can never be skipped. Mirrors
  -- public.get_case_detail (re-gate -> read -> audit). Returns NULL (no leak) when
  -- out of scope OR when no PHI row exists; an audit row is written ONLY on a real,
  -- entitled read of an existing row.
  select * into v_event from public.patient_safety_event where id = p_event_id;
  if v_event.id is null then
    return null;
  end if;

  -- Re-gate with the TIGHT identifier predicate (PQS member OR custodian
  -- staff_admin; NO reporting-provenance, NO admin fallback). Out of scope -> NULL,
  -- no audit row.
  if not app.can_read_event_patient(p_event_id, auth.uid()) then
    return null;
  end if;

  select * into v_patient from public.event_patient where event_id = p_event_id;
  if v_patient.event_id is null then
    -- Entitled, but no PHI on file: nothing was read, so no audit row.
    return null;
  end if;

  -- AUDIT (Rule 11/12): record THAT the identifiers were read + WHO, never the
  -- payload (empty metadata). Attributed to the reporting (provenance) commission.
  perform public.log_audit_access(
    'event_patient.read',
    'event_patient',
    p_event_id,
    v_event.reporting_commission_id,
    'Leitura dos identificadores do paciente do evento ' || v_event.code,
    '{}'::jsonb
  );

  return to_jsonb(v_patient);
end;
$$;


ALTER FUNCTION "public"."get_event_patient"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_patient_trajectory_for_entity"("p_module" "text", "p_entity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_patient_key text;
  v_encounter_key text;
  v_commission uuid;
  v_org uuid;
  v_bundle jsonb;
  v_count integer;
  v_audit_key text;
begin
  perform app.assert_patient_index_enabled();

  if p_module is null or p_module not in ('event', 'referral', 'case') then
    raise exception 'módulo inválido' using errcode = 'check_violation';
  end if;

  select patient_key, encounter_key, commission_id
    into v_patient_key, v_encounter_key, v_commission
  from public.patient_xref
  where module = p_module and entity_id = p_entity_id;

  -- Unknown entity OR name-only (never indexed) -> nothing to pivot on.
  if v_patient_key is null and v_encounter_key is null then
    return jsonb_build_object('matchedOn', null, 'matchCount', 0, 'entries', '[]'::jsonb);
  end if;

  v_org := app.org_of_commission(v_commission);
  -- ORG scope + duty separation: must be enrolled in the pivot entity's org.
  if v_org is null or not app.is_pqs_member_of(v_org) then
    return jsonb_build_object('matchedOn', null, 'matchCount', 0, 'entries', '[]'::jsonb);
  end if;

  v_bundle := app.patient_trajectory_bundle(v_patient_key, v_encounter_key, v_org);
  v_count := coalesce((v_bundle ->> 'matchCount')::integer, 0);

  if v_count >= 1 then
    v_audit_key := coalesce(v_patient_key, v_encounter_key);
    perform app.audit_write(
      'patient.viewed', 'patient', p_entity_id, null,
      'Trajetória de paciente aberta a partir de um registro (' || v_count::text || ' registro(s))',
      jsonb_build_object('patient_key', left(v_audit_key, 12) || '…', 'matches', v_count),
      v_org
    );
  end if;

  return v_bundle;
end;
$$;


