CREATE TABLE IF NOT EXISTS "public"."meeting_cases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "meeting_id" "uuid" NOT NULL,
    "case_id" "uuid" NOT NULL,
    "agenda_item_id" "uuid",
    "summary" "text",
    "decision" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."meeting_cases" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_meeting_case"("p_meeting_id" "uuid", "p_case_id" "uuid", "p_agenda_item_id" "uuid" DEFAULT NULL::"uuid", "p_summary" "text" DEFAULT NULL::"text", "p_decision" "text" DEFAULT NULL::"text") RETURNS "public"."meeting_cases"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_result public.meeting_cases;
begin
  perform app.assert_meetings_enabled();
  perform app.assert_meeting_staff_admin(p_meeting_id);
  -- The same-commission guard (HC032) + agenda-item-belongs check run in the
  -- BEFORE INSERT trigger app.guard_meeting_cases.

  perform set_config('app.in_meeting_rpc', 'on', true);
  insert into public.meeting_cases (meeting_id, case_id, agenda_item_id, summary, decision)
  values (p_meeting_id, p_case_id, p_agenda_item_id,
          nullif(btrim(p_summary), ''), nullif(btrim(p_decision), ''))
  returning * into v_result;
  perform set_config('app.in_meeting_rpc', 'off', true);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."link_meeting_case"("p_meeting_id" "uuid", "p_case_id" "uuid", "p_agenda_item_id" "uuid", "p_summary" "text", "p_decision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_referral_case"("p_referral_id" "uuid", "p_target_case_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."case_referral"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_referral public.case_referral;
  v_case_commission uuid;
  v_row public.case_referral;
begin
  perform app.assert_referrals_enabled();
  v_referral := app.assert_referral_target_acts(p_referral_id, array['recebida', 'aceita', 'em_analise']);

  if p_target_case_id is not null then
    select commission_id into v_case_commission from public.cases where id = p_target_case_id;
    if v_case_commission is null then
      raise exception 'caso não encontrado' using errcode = 'HC079';
    end if;
    if v_case_commission <> v_referral.target_commission_id then
      raise exception 'o caso selecionado não pertence à comissão de destino' using errcode = 'HC079';
    end if;
  end if;

  perform set_config('app.in_referral_rpc', 'on', true);
  update public.case_referral
  set target_case_id = p_target_case_id, updated_at = now()
  where id = p_referral_id
  returning * into v_row;
  perform set_config('app.in_referral_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."link_referral_case"("p_referral_id" "uuid", "p_target_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_case_access"("p_case" "uuid") RETURNS TABLE("user_id" "uuid", "level" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission uuid;
begin
  -- Respect the case_access feature flag, exactly like grant_case_access.
  perform app.assert_case_access_enabled();

  select commission_id into v_commission from public.cases where id = p_case;
  if v_commission is null then
    raise exception 'caso % não encontrado', p_case using errcode = 'no_data_found';
  end if;
  -- DEFINER: the RLS bypass is intentional, so this internal coordinator/admin
  -- gate is the authority (mirrors grant_case_access / revoke_case_access).
  if not (app.is_staff_admin_of(v_commission) or app.is_org_admin_of_commission(v_commission)) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;

  return query
    select ca.user_id, ca.level
    from public.case_access ca
    where ca.case_id = p_case
    order by ca.granted_at;
end;
$$;


ALTER FUNCTION "public"."list_case_access"("p_case" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_case_access"("p_case" "uuid") IS 'Coordinator/admin-gated read of the explicit case_access grant rows for a case (ADR 0033 D6). SECURITY DEFINER; mirrors grant_case_access authz (assert_case_access_enabled + staff_admin/org-admin-of-commission). Returns (user_id, level); grants are config (not PHI), so no audit row.';



CREATE OR REPLACE FUNCTION "public"."list_cases_board"("p_commission_id" "uuid") RETURNS TABLE("case_id" "uuid", "case_number" integer, "label" "text", "status" "text", "outcome_id" "uuid", "outcome" "jsonb", "created_at" timestamp with time zone, "closed_at" timestamp with time zone, "phases" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if not app.is_staff_admin_of(p_commission_id) then
    return;
  end if;

  return query
  select c.id,
         c.case_number,
         c.label,
         c.status,
         c.outcome_id,
         case when o.id is null then null else jsonb_build_object(
           'id', o.id,
           'label', o.label,
           'color_token', o.color_token,
           'requires_action_plan', o.requires_action_plan,
           'is_adverse', o.is_adverse
         ) end as outcome,
         c.created_at,
         c.closed_at,
         coalesce(
           (select jsonb_agg(jsonb_build_object(
               'position', cp.position,
               'title', cp.title,
               'status', cp.status,
               'recommended', cp.recommended,
               'assigned_to', cp.assigned_to,
               'assignee_name', pr.full_name,
               'due_date', cp.due_date,
               'result', case when prr.id is null then null else jsonb_build_object(
                 'id', prr.id,
                 'label', prr.label,
                 'color_token', prr.color_token,
                 'is_adverse', prr.is_adverse,
                 'source', cp.result_source
               ) end
             ) order by cp.position)
            from public.case_phases cp
            left join public.profiles pr on pr.id = cp.assigned_to
            left join public.phase_results prr on prr.id = cp.result_id
            where cp.case_id = c.id),
           '[]'::jsonb) as phases
  from public.cases c
  left join public.case_outcomes o on o.id = c.outcome_id
  where c.commission_id = p_commission_id
  order by c.case_number desc;
end;
$$;


ALTER FUNCTION "public"."list_cases_board"("p_commission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_my_cases"("p_commission" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
begin
  perform app.assert_case_access_enabled();

  if v_uid is null then
    return '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(row_obj order by created_at desc, case_number desc), '[]'::jsonb)
    into v_result
  from (
    select
      c.id,
      c.created_at,
      c.case_number,
      jsonb_build_object(
        'case_id', c.id,
        'case_number', c.case_number,
        'label', c.label,
        'status', c.status,
        'my_role',
          case
            when app.is_staff_admin_of_for(c.commission_id, v_uid)
                 or app.is_org_admin_of_commission_for(c.commission_id, v_uid) then 'coordinator'
            when exists (
              select 1 from public.case_access ca
              where ca.case_id = c.id and ca.user_id = v_uid and ca.level = 'write'
            ) then 'collaborator'
            else 'viewer'
          end,
        'items', (
          select coalesce(jsonb_agg(item order by display_position), '[]'::jsonb)
          from (
            -- the caller's PHASES of this case
            select
              coalesce(cp.display_position, cp.position) as display_position,
              jsonb_build_object(
                'kind', 'phase',
                'id', cp.id,
                'title', coalesce(nullif(btrim(cp.title), ''), f.title, 'Fase ' || cp.position),
                'status', cp.status,
                'display_position', coalesce(cp.display_position, cp.position),
                'actionable', (cp.status = 'ativa')
              ) as item
            from public.case_phases cp
            join public.forms f on f.id = cp.form_id
            where cp.case_id = c.id and cp.assigned_to = v_uid
            union all
            -- the caller's NARRATIVES of this case
            select
              cn.display_position,
              jsonb_build_object(
                'kind', 'narrative',
                'id', cn.id,
                'title', cn.type_label,
                'status', cn.status,
                'display_position', cn.display_position,
                'actionable', (cn.status = 'aberta')
              ) as item
            from public.case_narratives cn
            where cn.case_id = c.id and cn.assigned_to = v_uid
          ) items
        )
      ) as row_obj
    from public.cases c
    where c.commission_id = p_commission
      -- "Meus Casos" is the caller's PERSONAL list: cases they are attributed to
      -- (phase/narrative assignee) OR granted (ADR 0033 D7). A coordinator/admin is
      -- NOT auto-included for every case (the board is their management surface) —
      -- they appear here only when personally attributed/granted, and then carry the
      -- 'coordinator' role chip.
      and (
        exists (select 1 from public.case_access ca
                where ca.case_id = c.id and ca.user_id = v_uid)
        or exists (select 1 from public.case_phases cp
                   where cp.case_id = c.id and cp.assigned_to = v_uid)
        or exists (select 1 from public.case_narratives cn
                   where cn.case_id = c.id and cn.assigned_to = v_uid)
      )
  ) rows;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."list_my_cases"("p_commission" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_org_eligible_users_for_pqs"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_result jsonb;
begin
  if not (app.is_nsp_coordinator_of(p_org_id) or app.is_org_admin_of(p_org_id)) then
    raise exception 'apenas o coordenador do NSP ou um administrador da organização pode listar os usuários elegíveis'
      using errcode = '42501';
  end if;
  with eligible as (
    -- org-level members
    select om.user_id
    from public.organization_members om
    where om.organization_id = p_org_id
    union
    -- members of any commission in the org
    select cm.user_id
    from public.commission_members cm
    join public.commissions c on c.id = cm.commission_id
    where c.organization_id = p_org_id
  )
  select coalesce(jsonb_agg(
           jsonb_build_object(
             'userId', p.id,
             'fullName', p.full_name,
             'email', p.email
           )
           order by p.full_name
         ), '[]'::jsonb)
    into v_result
    from eligible e
    join public.profiles p on p.id = e.user_id;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."list_org_eligible_users_for_pqs"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_pqs_members"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_result jsonb;
begin
  if not app.is_nsp_coordinator_of(p_org_id) then
    raise exception 'apenas o coordenador do NSP da organização pode listar a equipe'
      using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(
           jsonb_build_object(
             'userId', m.user_id,
             'fullName', p.full_name,
             'email', p.email,
             'addedAt', m.added_at,
             'addedBy', m.added_by
           )
           order by p.full_name
         ), '[]'::jsonb)
    into v_result
    from public.pqs_members m
    join public.profiles p on p.id = m.user_id
    where m.organization_id = p_org_id;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."list_pqs_members"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_referral_target_commissions"("p_source_commission_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
begin
  perform app.assert_referrals_enabled();
  -- Gate matches the …626000 canonical (multi-tenancy dropped the is_admin() arm —
  -- the vendor platform_admin is NOT a tenant-path grant, ADR 0041). NSP-per-org adds
  -- only the same-org target filter below; it does NOT re-introduce is_admin().
  if not app.is_staff_admin_of(p_source_commission_id) then
    raise exception 'apenas a coordenação da comissão de origem pode listar destinos'
      using errcode = 'HC071';
  end if;
  return query
    select c.id, c.name
    from public.commissions c
    where c.id <> p_source_commission_id
      and c.organization_id = app.org_of_commission(p_source_commission_id)  -- same org only
    order by c.name asc;
end;
$$;


ALTER FUNCTION "public"."list_referral_target_commissions"("p_source_commission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_signoff_queue"("p_commission_id" "uuid") RETURNS TABLE("response_id" "uuid", "form_id" "uuid", "form_title" "text", "version_number" integer, "respondent_id" "uuid", "respondent_name" "text", "section_id" "uuid", "section_title" "text", "pending_count" integer, "started_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  -- Internal gate: non-staff_admins get an empty set (no leak, no error).
  if not app.is_staff_admin_of(p_commission_id) then
    return;
  end if;

  return query
  with candidate as (
    select r.id,
           r.form_version_id,
           r.created_by,
           r.started_at,
           r.updated_at,
           app.answer_map(r.id) as answers
    from public.responses r
    where r.commission_id = p_commission_id
      and r.status = 'in_progress'
  ),
  pending_sections as (
    -- Visible, unsigned, staff_admin-role sign-off sections of each candidate.
    select c.id as response_id,
           s.id as section_id,
           s.title as section_title,
           s.position
    from candidate c
    join public.form_sections s
      on s.form_version_id = c.form_version_id
     and s.requires_signoff = true
     and s.signoff_role = 'staff_admin'
    where app.eval_condition(s.visible_when, c.answers)
      and not exists (
        select 1 from public.response_section_signoffs so
        where so.response_id = c.id
          and so.section_id = s.id
      )
  ),
  ranked as (
    -- One representative pending section per response (lowest position) + count.
    select ps.response_id,
           ps.section_id,
           ps.section_title,
           count(*) over (partition by ps.response_id) as pending_count,
           row_number() over (partition by ps.response_id order by ps.position) as rn
    from pending_sections ps
  )
  select c.id,
         fv.form_id,
         f.title,
         fv.version_number,
         c.created_by,
         p.full_name,
         rk.section_id,
         rk.section_title,
         rk.pending_count::integer,
         c.started_at,
         c.updated_at
  from candidate c
  join ranked rk on rk.response_id = c.id and rk.rn = 1
  join public.form_versions fv on fv.id = c.form_version_id
  join public.forms f on f.id = fv.form_id
  join public.profiles p on p.id = c.created_by
  -- Submit-readiness: don't surface drafts that can't be submitted even once
  -- the staff_admin signs (missing required answers in visible sections).
  where app.response_required_complete(c.id)
  order by c.updated_at desc;
end;
$$;


ALTER FUNCTION "public"."list_signoff_queue"("p_commission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_audit_access"("p_action" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_commission" "uuid", "p_summary" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
begin
  if p_action not in (
    'response.opened_foreign', 'response.exported', 'audit.exported',
    'event_patient.read', 'case.opened',
    'safety_event.viewed', 'triage.viewed', 'rca.viewed', 'capa.viewed',
    'meeting.viewed', 'interview.viewed',
    -- Phase 22 (referrals): the audited PHI-identifier read + the PHI-bearing
    -- detail open (snapshot/reply bodies).
    'referral_patient.read', 'referral.viewed',
    -- case_patient (ADR 0038): the audited case-identifier read door.
    'case_patient.read'
  ) then
    raise exception 'log_audit_access: ação de acesso não permitida (%)', p_action
      using errcode = 'check_violation';
  end if;
  perform app.audit_write(p_action, p_entity_type, p_entity_id, p_commission, p_summary, p_metadata);
end;
$$;


ALTER FUNCTION "public"."log_audit_access"("p_action" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_commission" "uuid", "p_summary" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_meeting_held"("p_meeting_id" "uuid") RETURNS "public"."meetings"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_result public.meetings;
begin
  perform app.assert_meetings_enabled();
  perform app.assert_meeting_staff_admin(p_meeting_id);

  select status into v_status from public.meetings where id = p_meeting_id;
  if v_status <> 'agendada' then
    raise exception 'apenas reuniões agendadas podem ser marcadas como realizadas'
      using errcode = 'HC033';
  end if;

  perform set_config('app.in_meeting_rpc', 'on', true);
  update public.meetings
  set status = 'realizada', updated_at = now()
  where id = p_meeting_id returning * into v_result;
  perform set_config('app.in_meeting_rpc', 'off', true);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."mark_meeting_held"("p_meeting_id" "uuid") OWNER TO "postgres";


