CREATE OR REPLACE FUNCTION "public"."recompute_recommendations"("p_case_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  r record;                -- one pending case-phase carrying a recommend_when
  rc jsonb;                -- one sub-condition
  v_match text;            -- 'all' | 'any' (single → 'all')
  v_should boolean;
  v_cond_result boolean;
  v_source_phase_id uuid;
  v_from_phase integer;
  v_is_result boolean;
  v_answers jsonb;
  v_result_id uuid;
  v_is_adverse boolean;
  v_synth_map jsonb;
  v_synth_cond jsonb;
begin
  perform set_config('app.in_case_rpc', 'on', true);

  for r in
    select id, position, recommend_when
    from public.case_phases
    where case_id = p_case_id
      and status = 'pendente'
      and recommend_when is not null
  loop
    -- The combinator: a group's `match`, or 'all' for a legacy single (which
    -- app.recommend_when_conditions normalizes to a single answer condition).
    v_match := case
                 when (r.recommend_when ? 'conditions')
                   then coalesce(r.recommend_when ->> 'match', 'all')
                 else 'all'
               end;

    -- Fold the conditions. Start neutral for the combinator: AND → true, OR → false.
    v_should := (v_match <> 'any');

    for rc in select cond from app.recommend_when_conditions(r.recommend_when) cond loop
      v_from_phase := (rc ->> 'from_phase')::integer;
      v_is_result := (rc ->> 'source') = 'result';

      -- Resolve from_phase (a case-phase position) to the source phase id.
      select id into v_source_phase_id
      from public.case_phases
      where case_id = p_case_id and position = v_from_phase;

      if v_is_result then
        -- Effective result of the source phase + its adverse flag (null → no
        -- result, treated as the answer-style missing-value semantics).
        v_result_id := null;
        v_is_adverse := null;
        if v_source_phase_id is not null then
          select cp.result_id, pr.is_adverse
            into v_result_id, v_is_adverse
          from public.case_phases cp
          left join public.phase_results pr on pr.id = cp.result_id
          where cp.id = v_source_phase_id;
        end if;

        if rc ? 'adverse' then
          -- Result-adverse: synthetic boolean map; key absent when no result.
          if v_is_adverse is null then
            v_synth_map := '{}'::jsonb;
          else
            v_synth_map := jsonb_build_object('__phase_result_adverse__', to_jsonb(v_is_adverse));
          end if;
          v_synth_cond := jsonb_build_object(
            'question_key', '__phase_result_adverse__',
            'op', 'equals',
            'value', (rc -> 'adverse')
          );
        else
          -- Result-specific: synthetic id (text) map; key absent when no result.
          if v_result_id is null then
            v_synth_map := '{}'::jsonb;
          else
            v_synth_map := jsonb_build_object('__phase_result__', to_jsonb(v_result_id::text));
          end if;
          v_synth_cond := jsonb_build_object(
            'question_key', '__phase_result__',
            'op', (rc ->> 'op'),
            'value', (rc -> 'value')
          );
        end if;

        v_cond_result := app.eval_condition(v_synth_cond, v_synth_map);
      else
        -- Answer condition: source's submitted answer map; strip from_phase/source
        -- → a plain visible_when the UNCHANGED evaluator accepts.
        if v_source_phase_id is null then
          v_answers := '{}'::jsonb;
        else
          v_answers := app.case_phase_answer_map(v_source_phase_id);
        end if;
        v_cond_result := app.eval_condition(
          (rc - 'from_phase' - 'source'), v_answers
        );
      end if;

      if v_match = 'any' then
        v_should := v_should or v_cond_result;
      else
        v_should := v_should and v_cond_result;
      end if;
    end loop;

    update public.case_phases
    set recommended = v_should, updated_at = now()
    where id = r.id
      and recommended is distinct from v_should;
  end loop;

  perform set_config('app.in_case_rpc', 'off', true);
end;
$$;


ALTER FUNCTION "public"."recompute_recommendations"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_item_options"("p_item_id" "uuid", "p_options" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_dup text;
begin
  if p_options is null or jsonb_typeof(p_options) <> 'array' then
    raise exception 'lista de opções inválida' using errcode = 'check_violation';
  end if;

  -- Reject a payload with duplicate codes (would make the reconcile ambiguous).
  select code into v_dup
  from (
    select e ->> 'code' as code, count(*) as n
    from jsonb_array_elements(p_options) e
    group by e ->> 'code'
    having count(*) > 1
  ) d
  limit 1;
  if v_dup is not null then
    raise exception 'código de opção duplicado: %', v_dup using errcode = 'HC013';
  end if;

  -- Normalize the payload to a working set with a 0-based target position.
  create temp table _reconcile_opts on commit drop as
  select (e.value ->> 'code')::text as code,
         (e.value ->> 'label')::text as label,
         nullif(e.value ->> 'color_token', '')::text as color_token,
         case when e.value -> 'score' is null or jsonb_typeof(e.value -> 'score') = 'null'
              then null else (e.value ->> 'score')::numeric end as score,
         nullif(e.value ->> 'analytics_code', '')::text as analytics_code,
         (e.ordinality - 1)::integer as position
  from jsonb_array_elements(p_options) with ordinality e;

  -- 1) DELETE existing rows whose code is no longer in the payload. Doing this
  -- FIRST frees any positions/codes so the subsequent inserts/reorder are clean.
  -- The staff_admin-write RLS + published-structure guard apply to the caller.
  delete from public.form_item_options o
  where o.item_id = p_item_id
    and not exists (select 1 from _reconcile_opts r where r.code = o.code);

  -- 2) UPDATE kept rows' content (NOT position yet — positions are assigned in a
  -- single statement in step 4 to avoid transient collisions with new rows).
  update public.form_item_options o
  set label = r.label,
      color_token = r.color_token,
      score = r.score,
      analytics_code = r.analytics_code
  from _reconcile_opts r
  where o.item_id = p_item_id and o.code = r.code;

  -- 3) INSERT new rows (codes not yet on the item) at a HIGH temporary position
  -- band (base + n) so they cannot collide with existing rows before the reorder.
  -- form_version_id is filled by the sync trigger; parent-is-choice + code
  -- immutability triggers still apply.
  insert into public.form_item_options
    (item_id, position, code, label, color_token, score, analytics_code)
  select p_item_id,
         1000000 + r.position,   -- temp band, well above any real position
         r.code, r.label, r.color_token, r.score, r.analytics_code
  from _reconcile_opts r
  where not exists (
    select 1 from public.form_item_options o
    where o.item_id = p_item_id and o.code = r.code
  );

  -- 4) Assign ALL final positions in ONE statement. The DEFERRABLE unique
  -- constraint tolerates the transient duplicate positions within this update
  -- (mirrors reorder_phase_results / reorder_item).
  update public.form_item_options o
  set position = r.position
  from _reconcile_opts r
  where o.item_id = p_item_id and o.code = r.code;

  drop table _reconcile_opts;
end;
$$;


ALTER FUNCTION "public"."reconcile_item_options"("p_item_id" "uuid", "p_options" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reconcile_item_options"("p_item_id" "uuid", "p_options" "jsonb") IS 'form-model-normalization: atomically reconcile an item''s form_item_options to the ordered payload (delete removed / update kept / insert new / assign all positions in one statement). Fixes the cross-transaction DEFERRABLE-unique reorder bug. SECURITY INVOKER — staff_admin-write RLS + guard_published_structure (draft-only) apply. Caller supplies codes (app-side gen for new rows, Decision 2).';



CREATE TABLE IF NOT EXISTS "public"."capa_effectiveness" (
    "capa_id" "uuid" NOT NULL,
    "verdict" "text" NOT NULL,
    "method_md" "text",
    "verified_by" "uuid",
    "verified_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "capa_effectiveness_verdict_check" CHECK (("verdict" = ANY (ARRAY['eficaz'::"text", 'parcial'::"text", 'ineficaz'::"text"])))
);


ALTER TABLE "public"."capa_effectiveness" OWNER TO "postgres";


COMMENT ON TABLE "public"."capa_effectiveness" IS 'The 1:1 CAPA effectiveness verdict (Phase 14d). Required before close (HC052); revoked by reopen_capa_plan. method_md is sanitized Markdown — NEVER audited.';



COMMENT ON COLUMN "public"."capa_effectiveness"."method_md" IS 'PHI-BEARING free text (WS B; Rule 11/12). CAPA effectiveness-verification method narrative (sanitized Markdown); audited via capa.viewed; never copied into the audit log.';



CREATE OR REPLACE FUNCTION "public"."record_capa_effectiveness"("p_capa_id" "uuid", "p_verdict" "text", "p_method_md" "text" DEFAULT NULL::"text") RETURNS "public"."capa_effectiveness"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_row public.capa_effectiveness;
  v_status text;
begin
  perform app.assert_patient_safety_enabled();
  perform app.assert_capa_writable(p_capa_id);
  if p_verdict not in ('eficaz', 'parcial', 'ineficaz') then
    raise exception 'veredito de eficácia inválido' using errcode = 'check_violation';
  end if;

  select status into v_status from public.capa_plan where id = p_capa_id;

  perform set_config('app.in_safety_rpc', 'on', true);
  -- Advance em_execucao -> em_verificacao when the verdict is first recorded.
  if v_status = 'em_execucao' then
    update public.capa_plan set status = 'em_verificacao', updated_at = now() where id = p_capa_id;
  end if;

  insert into public.capa_effectiveness (capa_id, verdict, method_md, verified_by)
  values (p_capa_id, p_verdict, p_method_md, auth.uid())
  on conflict (capa_id) do update
  set verdict = excluded.verdict, method_md = excluded.method_md,
      verified_by = excluded.verified_by, verified_at = now(), updated_at = now()
  returning * into v_row;
  perform set_config('app.in_safety_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."record_capa_effectiveness"("p_capa_id" "uuid", "p_verdict" "text", "p_method_md" "text") OWNER TO "postgres";


