CREATE OR REPLACE FUNCTION "public"."save_narrative_body"("p_narrative" "uuid", "p_body_md" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_case_status text;
  v_status text;
begin
  perform app.assert_case_access_enabled();

  select c.status, cn.status into v_case_status, v_status
  from public.case_narratives cn
  join public.cases c on c.id = cn.case_id
  where cn.id = p_narrative;

  if v_status is null then
    raise exception 'narrativa % não encontrada', p_narrative using errcode = 'no_data_found';
  end if;
  -- Q14 write predicate (the authority).
  if not app.can_write_case_narrative(p_narrative, auth.uid()) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;
  if v_case_status in ('concluido', 'cancelado') then
    raise exception 'as narrativas deste caso estão bloqueadas' using errcode = 'HC054';
  end if;
  if v_status <> 'aberta' then
    raise exception 'a narrativa não está no estado necessário para esta ação'
      using errcode = 'HC055';
  end if;

  perform set_config('app.in_narrative_rpc', 'on', true);
  update public.case_narratives set body_md = p_body_md, updated_by = auth.uid()
  where id = p_narrative;
  perform set_config('app.in_narrative_rpc', 'off', true);
end;
$$;


ALTER FUNCTION "public"."save_narrative_body"("p_narrative" "uuid", "p_body_md" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_section_answers"("p_response_id" "uuid", "p_section_id" "uuid", "p_answers" "jsonb" DEFAULT '{}'::"jsonb", "p_clear_item_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_observations" "jsonb" DEFAULT NULL::"jsonb", "p_selections" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."responses"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_version_id uuid;
  v_status text;
  v_result public.responses;
  v_bad_item uuid;
  v_section_version uuid;
  v_bad_code text;
begin
  select form_version_id, status into v_version_id, v_status
  from public.responses
  where id = p_response_id;

  if v_version_id is null then
    raise exception 'resposta % não encontrada', p_response_id
      using errcode = 'no_data_found';
  end if;

  if v_status <> 'in_progress' then
    raise exception 'esta resposta já foi enviada e não pode mais ser editada'
      using errcode = 'check_violation';
  end if;

  -- Cross-version section guard (the saved section becomes last_section_id).
  select form_version_id into v_section_version
  from public.form_sections
  where id = p_section_id;

  if v_section_version is null or v_section_version <> v_version_id then
    raise exception 'a seção % não pertence a esta versão do formulário', p_section_id
      using errcode = 'HC013';
  end if;

  -- ---- Scalar answers. The answers upsert targets the top-level partial-unique
  -- (group_instance_id is null). answered_at refreshed on change. ----
  if p_answers is not null and p_answers <> '{}'::jsonb then
    select (e.key)::uuid into v_bad_item
    from jsonb_each(p_answers) e
    where not exists (
      select 1 from public.form_items i
      where i.id = (e.key)::uuid
        and i.form_version_id = v_version_id
    )
    limit 1;

    if v_bad_item is not null then
      raise exception 'o item % não pertence a esta versão do formulário', v_bad_item
        using errcode = 'HC013';
    end if;

    insert into public.answers (response_id, item_id, question_key, value, group_instance_id, answered_at)
    select p_response_id, i.id, i.question_key, e.value, null, now()
    from jsonb_each(p_answers) e
    join public.form_items i on i.id = (e.key)::uuid
    on conflict (response_id, item_id) where group_instance_id is null
    do update set value = excluded.value,
                  question_key = excluded.question_key,
                  answered_at = now();
  end if;

  -- ---- Choice selections (REPLACE semantics). For each item: upsert the PARENT
  -- answers row, delete its existing selection rows (via answer_id), then insert
  -- one row per code resolved to the option row of THAT item. Cross-version +
  -- code-existence are HC013. ----
  if p_selections is not null and p_selections <> '{}'::jsonb then
    select (e.key)::uuid into v_bad_item
    from jsonb_each(p_selections) e
    where not exists (
      select 1 from public.form_items i
      where i.id = (e.key)::uuid
        and i.form_version_id = v_version_id
    )
    limit 1;

    if v_bad_item is not null then
      raise exception 'o item % não pertence a esta versão do formulário', v_bad_item
        using errcode = 'HC013';
    end if;

    select sel.code into v_bad_code
    from (
      select (e.key)::uuid as item_id, c.value #>> '{}' as code
      from jsonb_each(p_selections) e
      cross join lateral jsonb_array_elements(e.value) c
    ) sel
    where not exists (
      select 1 from public.form_item_options o
      where o.item_id = sel.item_id and o.code = sel.code
    )
    limit 1;

    if v_bad_code is not null then
      raise exception 'a opção "%" não pertence a este item do formulário', v_bad_code
        using errcode = 'HC013';
    end if;

    -- Upsert the parent answers row for every choice item (value stays null;
    -- answered_at refreshed) so each selection has an answer_id to hang off.
    insert into public.answers (response_id, item_id, question_key, value, group_instance_id, answered_at)
    select p_response_id, i.id, i.question_key, null, null, now()
    from jsonb_each(p_selections) e
    join public.form_items i on i.id = (e.key)::uuid
    on conflict (response_id, item_id) where group_instance_id is null
    do update set answered_at = now();

    -- Replace: delete every keyed item's existing selections (via answer_id).
    delete from public.answer_selected_options s
    using public.answers a
    where s.answer_id = a.id
      and a.response_id = p_response_id
      and a.group_instance_id is null
      and a.item_id in (select (e.key)::uuid from jsonb_each(p_selections) e);

    insert into public.answer_selected_options (answer_id, option_id)
    select a.id, o.id
    from (
      select (e.key)::uuid as item_id, c.value #>> '{}' as code
      from jsonb_each(p_selections) e
      cross join lateral jsonb_array_elements(e.value) c
    ) sel
    join public.answers a
      on a.response_id = p_response_id
     and a.group_instance_id is null
     and a.item_id = sel.item_id
    join public.form_item_options o
      on o.item_id = sel.item_id and o.code = sel.code;
  end if;

  -- ---- Observation upsert (touches ONLY answers.observation). ----
  if p_observations is not null and p_observations <> '{}'::jsonb then
    select (e.key)::uuid into v_bad_item
    from jsonb_each(p_observations) e
    where not exists (
      select 1 from public.form_items i
      where i.id = (e.key)::uuid
        and i.form_version_id = v_version_id
    )
    limit 1;

    if v_bad_item is not null then
      raise exception 'o item % não pertence a esta versão do formulário', v_bad_item
        using errcode = 'HC013';
    end if;

    insert into public.answers (response_id, item_id, question_key, observation, group_instance_id)
    select p_response_id, i.id, i.question_key,
           nullif(btrim(e.value #>> '{}'), ''), null
    from jsonb_each(p_observations) e
    join public.form_items i on i.id = (e.key)::uuid
    on conflict (response_id, item_id) where group_instance_id is null
    do update set observation = excluded.observation;
  end if;

  -- ---- Orphan-clear: delete answers of now-hidden items (selections cascade). ----
  if p_clear_item_ids is not null and array_length(p_clear_item_ids, 1) is not null then
    delete from public.answers
    where response_id = p_response_id
      and item_id = any (p_clear_item_ids);
  end if;

  update public.responses
  set last_section_id = p_section_id,
      updated_at = now()
  where id = p_response_id
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."save_section_answers"("p_response_id" "uuid", "p_section_id" "uuid", "p_answers" "jsonb", "p_clear_item_ids" "uuid"[], "p_observations" "jsonb", "p_selections" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_triage"("p_event_id" "uuid", "p_is_pse" boolean DEFAULT NULL::boolean, "p_pse_closure_reason" "text" DEFAULT NULL::"text", "p_reach" "text" DEFAULT NULL::"text", "p_harm_severity" "text" DEFAULT NULL::"text", "p_natural_course" boolean DEFAULT NULL::boolean, "p_review_pathway" "text" DEFAULT NULL::"text", "p_disposition_notes_md" "text" DEFAULT NULL::"text", "p_sentinel_criteria_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "public"."event_triage"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_triage public.event_triage;
  v_reach text := p_reach;
  v_harm text := p_harm_severity;
  v_natural boolean := p_natural_course;
  v_has_designated boolean := coalesce(array_length(p_sentinel_criteria_ids, 1), 0) > 0;
  v_sentinel boolean;
begin
  perform app.assert_patient_safety_enabled();

  if not app.can_read_event(p_event_id, auth.uid()) then
    raise exception 'evento não encontrado' using errcode = 'P0002';
  end if;
  -- Triage is an NSP activity (per-org).
  if not app.is_pqs_member_of(app.org_of_event(p_event_id)) then
    raise exception 'apenas o NSP pode triar eventos' using errcode = '42501';
  end if;

  if (select status from public.patient_safety_event where id = p_event_id) <> 'acknowledged' then
    raise exception 'o evento precisa estar reconhecido pelo NSP para ser triado'
      using errcode = 'HC045';
  end if;

  if v_reach is not null and v_reach not in ('unsafe', 'near_miss', 'no_harm', 'adverse', 'sentinel') then
    raise exception 'alcance inválido' using errcode = 'HC046';
  end if;
  if v_harm is not null and v_harm not in ('none', 'mild', 'moderate', 'severe', 'permanent', 'death') then
    raise exception 'gravidade de dano inválida' using errcode = 'HC046';
  end if;
  if p_review_pathway is not null
     and p_review_pathway not in ('rca', 'peer_review', 'mm', 'fmea', 'tracking_only') then
    raise exception 'desfecho inválido' using errcode = 'HC046';
  end if;

  if p_is_pse is false then
    if p_pse_closure_reason is null
       or p_pse_closure_reason not in ('natural', 'expected', 'nonclinical', 'duplicate') then
      raise exception 'selecione o motivo de encerramento (não é evento de segurança)'
        using errcode = 'HC046';
    end if;
    v_reach := null;
    v_harm := null;
    v_natural := null;
    v_has_designated := false;
    p_sentinel_criteria_ids := '{}';
  end if;

  if coalesce(p_is_pse, true) and v_reach is not null then
    if v_reach in ('unsafe', 'near_miss', 'no_harm') then
      v_harm := 'none';
      v_natural := null;
    elsif v_reach = 'sentinel' then
      if v_harm is null or v_harm in ('none', 'mild', 'moderate') then
        v_harm := 'severe';
      end if;
    end if;
  end if;

  v_sentinel := app.compute_sentinel_determination(v_reach, v_harm, v_natural, v_has_designated);

  perform set_config('app.in_safety_rpc', 'on', true);

  insert into public.event_triage (
    event_id, is_pse, pse_closure_reason, reach, harm_severity, natural_course,
    sentinel_determination, review_pathway, disposition_notes_md, updated_at
  ) values (
    p_event_id, p_is_pse,
    case when p_is_pse is false then p_pse_closure_reason else null end,
    v_reach, v_harm, v_natural, v_sentinel, p_review_pathway, p_disposition_notes_md, now()
  )
  on conflict (event_id) do update
  set is_pse = excluded.is_pse,
      pse_closure_reason = excluded.pse_closure_reason,
      reach = excluded.reach,
      harm_severity = excluded.harm_severity,
      natural_course = excluded.natural_course,
      sentinel_determination = excluded.sentinel_determination,
      review_pathway = excluded.review_pathway,
      disposition_notes_md = excluded.disposition_notes_md,
      updated_at = now()
  returning * into v_triage;

  delete from public.event_triage_sentinel_flags where event_id = p_event_id;
  if v_has_designated then
    insert into public.event_triage_sentinel_flags (event_id, criteria_id, criteria_key, criteria_label)
    select p_event_id, c.id, c.key, c.label
    from public.pqs_sentinel_criteria c
    where c.id = any (p_sentinel_criteria_ids);
  end if;

  perform set_config('app.in_safety_rpc', 'off', true);
  return v_triage;
end;
$$;


ALTER FUNCTION "public"."save_triage"("p_event_id" "uuid", "p_is_pse" boolean, "p_pse_closure_reason" "text", "p_reach" "text", "p_harm_severity" "text", "p_natural_course" boolean, "p_review_pathway" "text", "p_disposition_notes_md" "text", "p_sentinel_criteria_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_interview"("p_interview_id" "uuid", "p_scheduled_start" timestamp with time zone, "p_scheduled_end" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."case_interviews"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_result public.case_interviews;
begin
  perform app.assert_interviews_enabled();
  perform app.assert_interview_writable(p_interview_id);

  if p_scheduled_start is null then
    raise exception 'informe a data e hora da entrevista' using errcode = 'check_violation';
  end if;

  select status into v_status from public.case_interviews where id = p_interview_id;
  if v_status <> 'rascunho' then
    raise exception 'apenas entrevistas em rascunho podem ser agendadas' using errcode = 'HC038';
  end if;

  perform set_config('app.in_interview_rpc', 'on', true);
  update public.case_interviews
  set status = 'agendada', scheduled_start = p_scheduled_start, scheduled_end = p_scheduled_end
  where id = p_interview_id
  returning * into v_result;
  perform set_config('app.in_interview_rpc', 'off', true);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."schedule_interview"("p_interview_id" "uuid", "p_scheduled_start" timestamp with time zone, "p_scheduled_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_patient_xref"("p_mrn" "text" DEFAULT NULL::"text", "p_encounter" "text" DEFAULT NULL::"text", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_patient_key text;
  v_encounter_key text;
  v_bundle jsonb;
  v_count integer;
  v_audit_key text;
begin
  perform app.assert_patient_index_enabled();

  -- Duty separation + ORG scope: must be enrolled in THIS org's roster (a non-member,
  -- incl. another org's member or a non-PQS admin, gets the empty bundle).
  if p_org_id is null or not app.is_pqs_member_of(p_org_id) then
    return jsonb_build_object('matchedOn', null, 'matchCount', 0, 'entries', '[]'::jsonb);
  end if;

  v_patient_key := app.derive_patient_key(p_mrn);
  v_encounter_key := app.derive_patient_key(p_encounter);

  if v_patient_key is null and v_encounter_key is null then
    return jsonb_build_object('matchedOn', null, 'matchCount', 0, 'entries', '[]'::jsonb);
  end if;

  v_bundle := app.patient_trajectory_bundle(v_patient_key, v_encounter_key, p_org_id);
  v_count := coalesce((v_bundle ->> 'matchCount')::integer, 0);

  if v_count >= 1 then
    v_audit_key := coalesce(v_patient_key, v_encounter_key);
    perform app.audit_write(
      'patient.searched', 'patient', app.patient_key_to_uuid(v_audit_key), null,
      'Pesquisa de paciente entre comissões (' || v_count::text || ' registro(s))',
      jsonb_build_object('patient_key', left(v_audit_key, 12) || '…', 'matches', v_count),
      p_org_id
    );
  end if;

  return v_bundle;
end;
$$;


ALTER FUNCTION "public"."search_patient_xref"("p_mrn" "text", "p_encounter" "text", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_expected_meeting_attendees"("p_meeting_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
begin
  perform app.assert_meetings_enabled();
  v_commission_id := app.assert_meeting_staff_admin(p_meeting_id);

  perform set_config('app.in_meeting_rpc', 'on', true);
  insert into public.meeting_attendees (meeting_id, user_id, role, attendance)
  select p_meeting_id, cm.user_id, 'membro', 'convocado'
  from public.commission_members cm
  where cm.commission_id = v_commission_id
  on conflict (meeting_id, user_id) where user_id is not null do nothing;
  perform set_config('app.in_meeting_rpc', 'off', true);
end;
$$;


ALTER FUNCTION "public"."seed_expected_meeting_attendees"("p_meeting_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_referral"("p_referral_id" "uuid") RETURNS "public"."case_referral"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_referral public.case_referral;
  v_item_count integer;
  v_row public.case_referral;
begin
  perform app.assert_referrals_enabled();
  select * into v_referral from public.case_referral where id = p_referral_id;
  if v_referral.id is null then
    raise exception 'encaminhamento não encontrado' using errcode = 'P0002';
  end if;
  if not app.can_manage_referral_source(p_referral_id, auth.uid()) then
    raise exception 'apenas a coordenação da comissão de origem pode enviar o encaminhamento'
      using errcode = 'HC071';
  end if;
  if v_referral.status <> 'rascunho' then
    raise exception 'apenas rascunhos podem ser enviados' using errcode = 'HC070';
  end if;

  select count(*) into v_item_count from public.referral_shared_item where referral_id = p_referral_id;
  if v_item_count = 0 and btrim(coalesce(v_referral.description_md, '')) = '' then
    raise exception 'adicione ao menos uma narrativa, documento ou descrição antes de enviar'
      using errcode = 'check_violation';
  end if;

  perform set_config('app.in_referral_rpc', 'on', true);
  update public.case_referral
  set status = 'enviada', sent_at = now(), sent_by = auth.uid(), updated_at = now()
  where id = p_referral_id
  returning * into v_row;
  perform set_config('app.in_referral_rpc', 'off', true);

  return v_row;
end;
$$;


ALTER FUNCTION "public"."send_referral"("p_referral_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_capa_action_task_done"("p_task_id" "uuid", "p_is_done" boolean) RETURNS "public"."capa_action_task"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_capa_id uuid;
  v_row public.capa_action_task;
begin
  perform app.assert_patient_safety_enabled();
  select a.capa_id into v_capa_id
  from public.capa_action_task t join public.capa_action a on a.id = t.action_id
  where t.id = p_task_id;
  if v_capa_id is null then
    raise exception 'etapa não encontrada' using errcode = 'no_data_found';
  end if;
  perform app.assert_capa_writable(v_capa_id);

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.capa_action_task set is_done = coalesce(p_is_done, false), updated_at = now()
  where id = p_task_id
  returning * into v_row;
  perform set_config('app.in_safety_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."set_capa_action_task_done"("p_task_id" "uuid", "p_is_done" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_case_offered_outcomes"("p_case_id" "uuid", "p_outcome_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission uuid;
  v_status text;
  v_assigned uuid;
  v_bad uuid;
begin
  perform app.assert_cases_enabled();
  perform app.assert_extras_enabled();

  select commission_id, status, outcome_id
    into v_commission, v_status, v_assigned
  from public.cases where id = p_case_id;
  if v_commission is null then
    raise exception 'caso % não encontrado', p_case_id using errcode = 'no_data_found';
  end if;

  if not (app.is_staff_admin_of(v_commission) or app.is_admin()) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;

  if v_status in ('concluido', 'cancelado') then
    raise exception 'este caso está em um estado final e não pode mais ser alterado'
      using errcode = 'HC025';
  end if;

  -- Same-commission + non-archived validation (the HC030 idiom).
  if cardinality(p_outcome_ids) > 0 then
    select oid into v_bad
    from unnest(p_outcome_ids) as oid
    where not exists (
      select 1 from public.case_outcomes o
      where o.id = oid
        and o.commission_id = v_commission
        and o.archived = false
    )
    limit 1;
    if found then
      raise exception 'este desfecho não pertence à comissão deste caso'
        using errcode = 'HC030';
    end if;
  end if;

  -- EDGE: the outcome currently ASSIGNED to the case cannot be dropped from the
  -- offered list — change the case's outcome first.
  if v_assigned is not null and not (v_assigned = any(p_outcome_ids)) then
    raise exception 'o desfecho atualmente atribuído a este caso não pode ser removido da lista de desfechos disponíveis; altere o desfecho do caso antes'
      using errcode = 'HC029';
  end if;

  -- Delete-then-insert (no in_case_rpc guard — this touches the join table, not
  -- cases). '{}' clears the set.
  delete from public.case_offered_outcomes where case_id = p_case_id;

  insert into public.case_offered_outcomes (case_id, outcome_id)
  select p_case_id, oid from unnest(p_outcome_ids) as oid
  on conflict do nothing;

  -- One PHI-free mutation audit row (no-ops while audit_trail is off).
  perform app.audit_write(
    'case.offered_outcomes_set', 'case', p_case_id, v_commission,
    'Desfechos disponíveis do caso atualizados',
    jsonb_build_object('count', cardinality(p_outcome_ids))
  );
end;
$$;


ALTER FUNCTION "public"."set_case_offered_outcomes"("p_case_id" "uuid", "p_outcome_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_case_outcome"("p_case_id" "uuid", "p_outcome_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."cases"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_status text;
  v_result public.cases;
begin
  perform app.assert_extras_enabled();

  select commission_id, status into v_commission_id, v_status
  from public.cases where id = p_case_id;
  if v_commission_id is null then
    raise exception 'caso % não encontrado', p_case_id using errcode = 'no_data_found';
  end if;
  if not (app.is_staff_admin_of(v_commission_id) or app.is_org_admin_of_commission(v_commission_id)) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;
  if v_status in ('concluido', 'cancelado') then
    raise exception 'este caso está em um estado final e não pode mais ser alterado'
      using errcode = 'HC025';
  end if;

  -- A non-null outcome must be one this case's process OFFERED (frozen set).
  if p_outcome_id is not null and not exists (
    select 1 from public.case_offered_outcomes
    where case_id = p_case_id and outcome_id = p_outcome_id
  ) then
    raise exception 'este desfecho não está disponível para este caso'
      using errcode = 'HC029';
  end if;

  update public.cases
  set outcome_id = p_outcome_id
  where id = p_case_id
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."set_case_outcome"("p_case_id" "uuid", "p_outcome_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_case_patient"("p_case_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_mrn" "text" DEFAULT NULL::"text", "p_date_of_birth" "date" DEFAULT NULL::"date", "p_age_years" integer DEFAULT NULL::integer, "p_sex" "text" DEFAULT 'unknown'::"text", "p_encounter_ref" "text" DEFAULT NULL::"text", "p_unit" "text" DEFAULT NULL::"text", "p_attending" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_case public.cases;
begin
  perform app.assert_case_patient_enabled();

  select * into v_case from public.cases where id = p_case_id;
  if v_case.id is null then
    raise exception 'caso não encontrado' using errcode = 'P0002';
  end if;
  -- COORDINATOR-ONLY write gate (not can_read_case — that is the broad READ scope).
  if not (app.is_staff_admin_of(v_case.commission_id)) then
    raise exception 'apenas a coordenação da comissão pode registrar dados do paciente'
      using errcode = '42501';
  end if;
  if not v_case.patient_enabled then
    raise exception 'este caso não coleta identificação do paciente'
      using errcode = 'check_violation';
  end if;
  if v_case.phi_disposed_at is not null then
    raise exception 'os dados do paciente deste caso foram descartados e não podem mais ser alterados'
      using errcode = 'check_violation';
  end if;
  if p_sex is not null and p_sex not in ('female', 'male', 'other', 'unknown') then
    raise exception 'sexo inválido' using errcode = 'check_violation';
  end if;

  insert into public.case_patient (
    case_id, name, mrn, date_of_birth, age_years, sex, encounter_ref, unit, attending
  ) values (
    p_case_id, p_name, p_mrn, p_date_of_birth, p_age_years, coalesce(p_sex, 'unknown'),
    p_encounter_ref, p_unit, p_attending
  )
  on conflict (case_id) do update
  set name = excluded.name, mrn = excluded.mrn, date_of_birth = excluded.date_of_birth,
      age_years = excluded.age_years, sex = excluded.sex,
      encounter_ref = excluded.encounter_ref, unit = excluded.unit,
      attending = excluded.attending, updated_at = now();

  -- Maintain the denormalized has_patient flag. Runs under the case-RPC guard
  -- bypass so it works even on a terminal case (cases has no updated_at).
  if not v_case.has_patient then
    perform set_config('app.in_case_rpc', 'on', true);
    update public.cases set has_patient = true where id = p_case_id;
    perform set_config('app.in_case_rpc', 'off', true);
  end if;
end;
$$;


ALTER FUNCTION "public"."set_case_patient"("p_case_id" "uuid", "p_name" "text", "p_mrn" "text", "p_date_of_birth" "date", "p_age_years" integer, "p_sex" "text", "p_encounter_ref" "text", "p_unit" "text", "p_attending" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_case_phase_result_override"("p_case_phase_id" "uuid", "p_result_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_case_id uuid;
  v_commission_id uuid;
  v_phase_status text;
  v_case_status text;
  v_assigned_to uuid;
  v_position integer;
  v_is_staff_admin boolean;
  v_allowed jsonb;
  v_ruleset jsonb;
  v_emits boolean;
  v_is_manual boolean;
begin
  perform app.assert_phase_results_enabled();

  select cp.case_id, cp.status, cp.assigned_to, cp.position, c.commission_id, c.status,
         cp.allowed_result_ids, cp.result_ruleset, cp.emits_result
    into v_case_id, v_phase_status, v_assigned_to, v_position, v_commission_id, v_case_status,
         v_allowed, v_ruleset, v_emits
  from public.case_phases cp
  join public.cases c on c.id = cp.case_id
  where cp.id = p_case_phase_id;

  if v_case_id is null then
    raise exception 'fase % não encontrada', p_case_phase_id using errcode = 'no_data_found';
  end if;

  v_is_staff_admin := app.is_staff_admin_of(v_commission_id) or app.is_org_admin_of_commission(v_commission_id);
  v_is_manual := coalesce(v_emits, false) and v_ruleset is null;

  if v_phase_status not in ('ativa', 'concluida') then
    raise exception 'o resultado só pode ser ajustado em uma fase ativa ou concluída'
      using errcode = 'HC057';
  end if;

  if v_phase_status = 'ativa' then
    if not (v_assigned_to = auth.uid() or v_is_staff_admin) then
      raise exception 'sem permissão' using errcode = '42501';
    end if;
  else
    if not v_is_staff_admin then
      raise exception 'sem permissão' using errcode = '42501';
    end if;
    if v_case_status in ('concluido', 'cancelado') then
      raise exception 'este caso está em um estado final e não pode mais ser alterado'
        using errcode = 'HC060';
    end if;
  end if;

  -- MANUAL phase: the result is the filler's pick over the ALLOWED subset, so it
  -- is MANDATORY (cannot be cleared) and must be one of the allowed options. An
  -- AUTOMATIC phase's override is a staff adjustment with full flexibility (any
  -- active result, clearable → revert to the computed result).
  if v_is_manual then
    if p_result_id is null then
      raise exception 'o resultado desta fase é obrigatório e não pode ser removido'
        using errcode = 'HC062';
    end if;
    if v_allowed is not null and not exists (
      select 1 from jsonb_array_elements_text(v_allowed) as e(id)
      where e.id::uuid = p_result_id
    ) then
      raise exception 'o resultado escolhido não está entre as opções permitidas para esta fase'
        using errcode = 'HC058';
    end if;
  end if;

  -- A non-null result must resolve to a NON-ARCHIVED option in the commission.
  if p_result_id is not null and not exists (
    select 1 from public.phase_results
    where id = p_result_id and commission_id = v_commission_id and archived = false
  ) then
    raise exception 'opção de resultado inválida para esta comissão'
      using errcode = 'HC058';
  end if;

  perform set_config('app.in_case_rpc', 'on', true);
  update public.case_phases
  set result_override_id = p_result_id,
      result_override_by = case when p_result_id is null then null else auth.uid() end,
      result_override_at = case when p_result_id is null then null else now() end,
      result_override_reason = case when p_result_id is null then null else nullif(btrim(p_reason), '') end,
      updated_at = now()
  where id = p_case_phase_id;
  perform set_config('app.in_case_rpc', 'off', true);

  perform app.audit_write(
    'case_phase.result_override_set', 'case_phase', p_case_phase_id, v_commission_id,
    'Resultado da fase ' || v_position || ' ajustado manualmente',
    jsonb_build_object('result_override_id', p_result_id));

  if v_phase_status = 'concluida' then
    perform app.compute_case_phase_result(p_case_phase_id);
    -- ADR 0043: the concluded phase's EFFECTIVE result just changed/cleared —
    -- re-flip downstream result-based recommendations against it.
    perform public.recompute_recommendations(v_case_id);
  end if;
end;
$$;


ALTER FUNCTION "public"."set_case_phase_result_override"("p_case_phase_id" "uuid", "p_result_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_event_patient"("p_event_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_mrn" "text" DEFAULT NULL::"text", "p_date_of_birth" "date" DEFAULT NULL::"date", "p_age_years" integer DEFAULT NULL::integer, "p_sex" "text" DEFAULT 'unknown'::"text", "p_encounter_ref" "text" DEFAULT NULL::"text", "p_unit" "text" DEFAULT NULL::"text", "p_attending" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
begin
  perform app.assert_patient_safety_enabled();

  if not app.can_read_event(p_event_id, auth.uid()) then
    raise exception 'evento não encontrado' using errcode = 'P0002';
  end if;
  if not app.event_current_custodian(p_event_id, auth.uid()) then
    raise exception 'apenas quem detém a custódia do evento pode registrar dados do paciente'
      using errcode = 'HC044';
  end if;
  if p_sex is not null and p_sex not in ('female', 'male', 'other', 'unknown') then
    raise exception 'sexo inválido' using errcode = 'check_violation';
  end if;

  insert into public.event_patient (
    event_id, name, mrn, date_of_birth, age_years, sex, encounter_ref, unit, attending
  ) values (
    p_event_id, p_name, p_mrn, p_date_of_birth, p_age_years, coalesce(p_sex, 'unknown'),
    p_encounter_ref, p_unit, p_attending
  )
  on conflict (event_id) do update
  set name = excluded.name, mrn = excluded.mrn, date_of_birth = excluded.date_of_birth,
      age_years = excluded.age_years, sex = excluded.sex,
      encounter_ref = excluded.encounter_ref, unit = excluded.unit,
      attending = excluded.attending, updated_at = now();

  -- WS A: maintain the denormalized has_patient flag so list/governance reads can
  -- derive hasPatient without embedding event_patient (which is no longer directly
  -- SELECT-able). Disposal (WS C) sets it back to false.
  update public.patient_safety_event set has_patient = true where id = p_event_id;
end;
$$;


ALTER FUNCTION "public"."set_event_patient"("p_event_id" "uuid", "p_name" "text", "p_mrn" "text", "p_date_of_birth" "date", "p_age_years" integer, "p_sex" "text", "p_encounter_ref" "text", "p_unit" "text", "p_attending" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_meeting_quorum_met"("p_meeting_id" "uuid", "p_quorum_met" boolean) RETURNS "public"."meetings"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_result public.meetings;
begin
  perform app.assert_meetings_enabled();
  perform app.assert_meeting_staff_admin(p_meeting_id);

  select status into v_status from public.meetings where id = p_meeting_id;
  if v_status <> 'em_assinatura' then
    raise exception 'o quórum só pode ser ajustado enquanto a ata aguarda assinatura'
      using errcode = 'HC033';
  end if;

  perform set_config('app.in_meeting_rpc', 'on', true);
  update public.meetings set quorum_met = p_quorum_met, updated_at = now()
  where id = p_meeting_id returning * into v_result;
  perform set_config('app.in_meeting_rpc', 'off', true);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."set_meeting_quorum_met"("p_meeting_id" "uuid", "p_quorum_met" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_pqs_rca_due_window"("p_org_id" "uuid", "p_days" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_old integer;
  v_id uuid;
begin
  perform app.assert_patient_safety_enabled();
  -- The org's coordinator OR an enrolled member may set its window.
  if not (app.is_nsp_coordinator_of(p_org_id) or app.is_pqs_member_of(p_org_id)) then
    raise exception 'apenas o NSP pode configurar a janela de RCA' using errcode = '42501';
  end if;
  if p_days is null or p_days < 1 or p_days > 365 then
    raise exception 'a janela de RCA deve estar entre 1 e 365 dias' using errcode = 'HC046';
  end if;

  select id, rca_default_due_days into v_id, v_old
  from public.pqs_department where organization_id = p_org_id;
  if v_id is null then
    raise exception 'NSP não configurado' using errcode = 'P0002';
  end if;

  update public.pqs_department
  set rca_default_due_days = p_days, updated_at = now()
  where id = v_id;

  -- Audit at the ORG tier (was platform-tier in the global RPC). PHI-free integer.
  perform app.audit_write('pqs_config.rca_due_window_changed', 'pqs_department', v_id, null,
    'Janela de RCA do NSP definida para ' || p_days || ' dias',
    jsonb_build_object('rca_default_due_days',
      jsonb_build_object('old', v_old, 'new', p_days)),
    p_org_id);

  return p_days;
end;
$$;


ALTER FUNCTION "public"."set_pqs_rca_due_window"("p_org_id" "uuid", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_process_outcomes"("p_template_id" "uuid", "p_outcome_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_status text;
begin
  perform app.assert_extras_enabled();

  select commission_id, status into v_commission_id, v_status
  from public.process_templates where id = p_template_id;
  if v_commission_id is null then
    raise exception 'processo % não encontrado', p_template_id using errcode = 'no_data_found';
  end if;
  if not (app.is_staff_admin_of(v_commission_id) or app.is_org_admin_of_commission(v_commission_id)) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;
  if v_status <> 'draft' then
    raise exception 'apenas processos em rascunho podem ser editados'
      using errcode = 'check_violation';
  end if;

  delete from public.process_template_outcomes where template_id = p_template_id;

  insert into public.process_template_outcomes (template_id, outcome_id, position)
  select p_template_id, oid, ord::integer
  from unnest(p_outcome_ids) with ordinality as t(oid, ord);
end;
$$;


ALTER FUNCTION "public"."set_process_outcomes"("p_template_id" "uuid", "p_outcome_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_rca_factor_key"("p_factor_id" "uuid", "p_is_key" boolean) RETURNS "public"."rca_factors"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_rca_id uuid;
  v_row public.rca_factors;
begin
  perform app.assert_patient_safety_enabled();
  select rca_id into v_rca_id from public.rca_factors where id = p_factor_id;
  if v_rca_id is null then
    raise exception 'fator não encontrado' using errcode = 'no_data_found';
  end if;
  perform app.assert_rca_writable(v_rca_id);

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.rca_factors set is_key = coalesce(p_is_key, false), updated_at = now()
  where id = p_factor_id
  returning * into v_row;
  -- Un-keying a factor drops its 5-Whys chain (it is no longer carried into the drill).
  if not coalesce(p_is_key, false) then
    delete from public.rca_why_chains where factor_id = p_factor_id;
  end if;
  perform set_config('app.in_safety_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."set_rca_factor_key"("p_factor_id" "uuid", "p_is_key" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."rca_why_chains" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "rca_id" "uuid" NOT NULL,
    "factor_id" "uuid" NOT NULL,
    "steps" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "root_text" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "rca_why_chains_steps_is_array" CHECK (("jsonb_typeof"("steps") = 'array'::"text")),
    CONSTRAINT "rca_why_chains_steps_max5" CHECK (("jsonb_array_length"("steps") <= 5))
);


ALTER TABLE "public"."rca_why_chains" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_rca_why_root"("p_factor_id" "uuid", "p_root_text" "text") RETURNS "public"."rca_why_chains"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_rca_id uuid;
  v_row public.rca_why_chains;
begin
  perform app.assert_patient_safety_enabled();
  select rca_id into v_rca_id from public.rca_factors where id = p_factor_id;
  if v_rca_id is null then
    raise exception 'fator não encontrado' using errcode = 'no_data_found';
  end if;
  perform app.assert_rca_writable(v_rca_id);

  perform set_config('app.in_safety_rpc', 'on', true);
  insert into public.rca_why_chains (rca_id, factor_id, steps, root_text)
  values (v_rca_id, p_factor_id, '[]'::jsonb, p_root_text)
  on conflict (factor_id) do update set root_text = excluded.root_text, updated_at = now()
  returning * into v_row;
  perform set_config('app.in_safety_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."set_rca_why_root"("p_factor_id" "uuid", "p_root_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_rca_why_step"("p_factor_id" "uuid", "p_index" integer, "p_text" "text") RETURNS "public"."rca_why_chains"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_rca_id uuid;
  v_row public.rca_why_chains;
  v_steps jsonb;
  i integer;
begin
  perform app.assert_patient_safety_enabled();
  select rca_id into v_rca_id from public.rca_factors where id = p_factor_id;
  if v_rca_id is null then
    raise exception 'fator não encontrado' using errcode = 'no_data_found';
  end if;
  perform app.assert_rca_writable(v_rca_id);
  if p_index < 0 or p_index > 4 then
    raise exception 'os 5 porquês admitem no máximo 5 etapas' using errcode = 'check_violation';
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);

  -- Lazily create the chain.
  insert into public.rca_why_chains (rca_id, factor_id, steps)
  values (v_rca_id, p_factor_id, '[]'::jsonb)
  on conflict (factor_id) do nothing;

  select steps into v_steps from public.rca_why_chains where factor_id = p_factor_id;
  -- Pad the array up to p_index with empty strings.
  i := jsonb_array_length(v_steps);
  while i <= p_index loop
    v_steps := v_steps || to_jsonb(''::text);
    i := i + 1;
  end loop;
  v_steps := jsonb_set(v_steps, array[p_index::text], to_jsonb(coalesce(p_text, '')));

  update public.rca_why_chains
  set steps = v_steps, updated_at = now()
  where factor_id = p_factor_id
  returning * into v_row;
  perform set_config('app.in_safety_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."set_rca_why_step"("p_factor_id" "uuid", "p_index" integer, "p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_referral_patient"("p_referral_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_mrn" "text" DEFAULT NULL::"text", "p_date_of_birth" "date" DEFAULT NULL::"date", "p_age_years" integer DEFAULT NULL::integer, "p_sex" "text" DEFAULT 'unknown'::"text", "p_encounter_ref" "text" DEFAULT NULL::"text", "p_unit" "text" DEFAULT NULL::"text", "p_attending" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
begin
  perform app.assert_referrals_enabled();

  select status into v_status from public.case_referral where id = p_referral_id;
  if v_status is null then
    raise exception 'encaminhamento não encontrado' using errcode = 'P0002';
  end if;
  if not app.can_read_referral_phi(p_referral_id, auth.uid()) then
    raise exception 'você não pode registrar dados do paciente neste encaminhamento'
      using errcode = 'HC078';
  end if;
  if v_status in ('concluida', 'recusada', 'retirada') then
    raise exception 'encaminhamento concluído; os dados do paciente não podem mais ser alterados'
      using errcode = 'HC078';
  end if;
  if p_sex is not null and p_sex not in ('female', 'male', 'other', 'unknown') then
    raise exception 'sexo inválido' using errcode = 'check_violation';
  end if;

  insert into public.referral_patient (
    referral_id, name, mrn, date_of_birth, age_years, sex, encounter_ref, unit, attending
  ) values (
    p_referral_id, p_name, p_mrn, p_date_of_birth, p_age_years, coalesce(p_sex, 'unknown'),
    p_encounter_ref, p_unit, p_attending
  )
  on conflict (referral_id) do update
  set name = excluded.name, mrn = excluded.mrn, date_of_birth = excluded.date_of_birth,
      age_years = excluded.age_years, sex = excluded.sex,
      encounter_ref = excluded.encounter_ref, unit = excluded.unit,
      attending = excluded.attending, updated_at = now();

  update public.case_referral set has_patient = true, updated_at = now() where id = p_referral_id;
end;
$$;


ALTER FUNCTION "public"."set_referral_patient"("p_referral_id" "uuid", "p_name" "text", "p_mrn" "text", "p_date_of_birth" "date", "p_age_years" integer, "p_sex" "text", "p_encounter_ref" "text", "p_unit" "text", "p_attending" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_template_collects_patient"("p_template_id" "uuid", "p_collects" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_status text;
begin
  perform app.assert_case_patient_enabled();

  select commission_id, status into v_commission_id, v_status
  from public.process_templates where id = p_template_id;
  if v_commission_id is null then
    raise exception 'processo % não encontrado', p_template_id using errcode = 'no_data_found';
  end if;
  if not (app.is_staff_admin_of(v_commission_id)) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;
  if v_status <> 'draft' then
    raise exception 'apenas processos em rascunho podem ser editados'
      using errcode = 'check_violation';
  end if;

  update public.process_templates
  set collects_patient = coalesce(p_collects, false), updated_at = now()
  where id = p_template_id;
end;
$$;


ALTER FUNCTION "public"."set_template_collects_patient"("p_template_id" "uuid", "p_collects" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_template_phase_blocks"("p_phase_id" "uuid", "p_blocks" integer[]) RETURNS "public"."process_template_phases"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_template_id uuid;
  v_position integer;
  v_status text;
  v_blocks integer[];
  v_result public.process_template_phases;
begin
  perform app.assert_cases_enabled();

  select ph.template_id, ph.position, t.status
    into v_template_id, v_position, v_status
  from public.process_template_phases ph
  join public.process_templates t on t.id = ph.template_id
  where ph.id = p_phase_id;

  if v_template_id is null then
    raise exception 'fase % não encontrada', p_phase_id using errcode = 'no_data_found';
  end if;
  if v_status <> 'draft' then
    raise exception 'apenas processos em rascunho podem ser editados'
      using errcode = 'check_violation';
  end if;

  -- Normalise: drop nulls + dups, sort ascending (stable storage).
  v_blocks := coalesce(
    (select array_agg(distinct b order by b)
     from unnest(p_blocks) as b
     where b is not null),
    '{}');

  perform app.validate_template_phase_blocks(v_template_id, v_position, v_blocks);

  update public.process_template_phases
  set blocks = v_blocks
  where id = p_phase_id
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."set_template_phase_blocks"("p_phase_id" "uuid", "p_blocks" integer[]) OWNER TO "postgres";


