    "status" "text" DEFAULT 'signed'::"text" NOT NULL,
    "signed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "content_hash" "text",
    "provider_ref" "text",
    "provider_payload" "jsonb",
    "ip_address" "inet",
    "user_agent" "text",
