CREATE OR REPLACE FUNCTION "public"."sign_meeting"("p_attendee_id" "uuid", "p_method" "text" DEFAULT 'internal_eauth'::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."meeting_signatures"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_meeting_id uuid;
  v_status text;
  v_minutes text;
  v_hash text;
  v_uid uuid := auth.uid();
  v_required integer;
  v_signed integer;
  v_result public.meeting_signatures;
begin
  perform app.assert_meetings_enabled();

  select a.meeting_id, m.status, m.minutes_md
    into v_meeting_id, v_status, v_minutes
  from public.meeting_attendees a
  join public.meetings m on m.id = a.meeting_id
  where a.id = p_attendee_id;

  if v_meeting_id is null then
    raise exception 'participante não encontrado' using errcode = 'no_data_found';
  end if;
  if v_status <> 'em_assinatura' then
    raise exception 'esta reunião não está aguardando assinatura' using errcode = 'HC033';
  end if;

  v_hash := encode(extensions.digest(coalesce(v_minutes, ''), 'sha256'), 'hex');

  -- ELIGIBILITY: this function is SECURITY DEFINER (owned by a superuser), so the
  -- INSERT below BYPASSES the meeting_signatures_insert RLS policy entirely —
  -- RLS is not enforced for the table owner. We therefore re-assert the same
  -- predicate (app.can_sign_meeting) EXPLICITLY here: only a PRESENT PLATFORM
  -- attendee whose user_id = the caller, on an em_assinatura meeting in the
  -- caller's commission, may sign their OWN row. The sign-own-row RLS policy
  -- remains the authority for any DIRECT (invoker) insert path; this explicit
  -- check is the authority for THIS definer path. (HC036.)
  if not app.can_sign_meeting(p_attendee_id, v_uid) then
    raise exception 'apenas participantes presentes podem assinar a ata' using errcode = 'HC036';
  end if;

  -- Insert the signature. A double-sign collides with the active partial-unique
  -- (meeting_signatures_active_key) -> unique_violation -> HC035. signer_id MUST
  -- be the acting user (asserted by can_sign_meeting above).
  begin
    insert into public.meeting_signatures
      (meeting_id, attendee_id, signer_id, method, status, content_hash, note)
    values
      (v_meeting_id, p_attendee_id, v_uid, coalesce(p_method, 'internal_eauth'),
       'signed', v_hash, nullif(btrim(p_note), ''))
    returning * into v_result;
  exception
    when unique_violation then
      raise exception 'você já assinou esta ata' using errcode = 'HC035';
  end;

  -- Count required (present platform attendees) vs. active signatures.
  select count(*) into v_required
  from public.meeting_attendees
  where meeting_id = v_meeting_id and user_id is not null and attendance = 'presente';

  select count(*) into v_signed
  from public.meeting_signatures
  where meeting_id = v_meeting_id and status = 'signed';

  -- AUTO-FLIP em_assinatura -> assinada when the last required signature lands.
  if v_required > 0 and v_signed >= v_required then
    perform set_config('app.in_meeting_rpc', 'on', true);
    update public.meetings set status = 'assinada', updated_at = now()
    where id = v_meeting_id and status = 'em_assinatura';
    perform set_config('app.in_meeting_rpc', 'off', true);
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."sign_meeting"("p_attendee_id" "uuid", "p_method" "text", "p_note" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."response_section_signoffs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "response_id" "uuid" NOT NULL,
    "section_id" "uuid" NOT NULL,
    "signed_by" "uuid" NOT NULL,
    "signed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "note" "text"
);


ALTER TABLE "public"."response_section_signoffs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sign_section"("p_response_id" "uuid", "p_section_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."response_section_signoffs"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_version_id uuid;
  v_requires_signoff boolean;
  v_visible_when jsonb;
  v_found boolean := false;
  v_answers jsonb;
  v_result public.response_section_signoffs;
begin
  -- Definer-rights metadata read (see header). No row -> response not found.
  for v_status, v_version_id, v_requires_signoff, v_visible_when in
    select t.status, t.version_id, t.requires_signoff, t.visible_when
    from app.signoff_target(p_response_id, p_section_id) t
  loop
    v_found := true;
  end loop;

  if not v_found then
    raise exception 'resposta % não encontrada', p_response_id
      using errcode = 'no_data_found';
  end if;

  if v_status <> 'in_progress' then
    raise exception 'esta resposta já foi enviada e não pode mais ser assinada'
      using errcode = 'check_violation';
  end if;

  -- requires_signoff null means the section does not belong to this response's
  -- version (the LEFT JOIN found no matching section).
  if v_requires_signoff is null then
    raise exception 'seção % não pertence a esta resposta', p_section_id
      using errcode = 'check_violation';
  end if;

  if not v_requires_signoff then
    raise exception 'esta seção não exige assinatura'
      using errcode = 'check_violation';
  end if;

  -- Visibility precondition (Architecture Rule 4): a section hidden under the
  -- response's saved answers collects no sign-off. RLS cannot cheaply evaluate
  -- this (it would have to read answers from within a signoffs policy), so the
  -- RPC owns it.
  v_answers := app.answer_map(p_response_id);
  if not app.eval_condition(v_visible_when, v_answers) then
    raise exception 'esta seção não está disponível para assinatura'
      using errcode = 'HC014';
  end if;

  -- The insert is the authority for WHO may sign (signoffs_insert WITH CHECK:
  -- respondent -> creator, staff_admin -> is_staff_admin_of, signed_by =
  -- auth.uid(), in_progress). The unique(response_id, section_id) index turns a
  -- double-sign race into a discriminated "already signed".
  begin
    insert into public.response_section_signoffs (response_id, section_id, signed_by, note)
    values (p_response_id, p_section_id, auth.uid(), nullif(btrim(p_note), ''))
    returning * into v_result;
  exception
    when unique_violation then
      raise exception 'esta seção já foi assinada'
        using errcode = 'HC015';
  end;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."sign_section"("p_response_id" "uuid", "p_section_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."skip_phase"("p_case_phase_id" "uuid") RETURNS "public"."case_phases"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_case_id uuid;
  v_status text;
  v_case_status text;
  v_result public.case_phases;
begin
  perform app.assert_cases_enabled();

  select cp.case_id, cp.status, c.status
    into v_case_id, v_status, v_case_status
  from public.case_phases cp
  join public.cases c on c.id = cp.case_id
  where cp.id = p_case_phase_id;

  if v_case_id is null then
    raise exception 'fase % não encontrada', p_case_phase_id using errcode = 'no_data_found';
  end if;
  if v_case_status in ('concluido', 'cancelado') then
    raise exception 'este caso não está aberto' using errcode = 'HC020';
  end if;
  if v_status <> 'pendente' then
    raise exception 'apenas fases pendentes podem ser marcadas como não necessárias'
      using errcode = 'HC019';
  end if;

  perform set_config('app.in_case_rpc', 'on', true);
  update public.case_phases
  set status = 'nao_necessaria', skipped_at = now(), updated_at = now()
  where id = p_case_phase_id
  returning * into v_result;
  perform set_config('app.in_case_rpc', 'off', true);

  perform public.recompute_recommendations(v_case_id);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."skip_phase"("p_case_phase_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."snap_referral_commission_names"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  SELECT name INTO NEW.source_commission_name
    FROM public.commissions WHERE id = NEW.source_commission_id;
  SELECT name INTO NEW.target_commission_name
    FROM public.commissions WHERE id = NEW.target_commission_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."snap_referral_commission_names"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_interview"("p_interview_id" "uuid") RETURNS "public"."case_interviews"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_result public.case_interviews;
begin
  perform app.assert_interviews_enabled();
  perform app.assert_interview_writable(p_interview_id);

  select status into v_status from public.case_interviews where id = p_interview_id;
  if v_status <> 'agendada' then
    raise exception 'apenas entrevistas agendadas podem ser iniciadas' using errcode = 'HC038';
  end if;

  perform set_config('app.in_interview_rpc', 'on', true);
  update public.case_interviews
  set status = 'em_andamento', conducted_at = coalesce(conducted_at, now())
  where id = p_interview_id
  returning * into v_result;
  perform set_config('app.in_interview_rpc', 'off', true);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."start_interview"("p_interview_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_or_resume_phase"("p_case_phase_id" "uuid") RETURNS "public"."responses"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_assigned_to uuid;
  v_version_id uuid;
  v_commission_id uuid;
  v_uid uuid := auth.uid();
  v_result public.responses;
begin
  perform app.assert_cases_enabled();

  select cp.status, cp.assigned_to, cp.form_version_id, c.commission_id
    into v_status, v_assigned_to, v_version_id, v_commission_id
  from public.case_phases cp
  join public.cases c on c.id = cp.case_id
  where cp.id = p_case_phase_id;

  if v_version_id is null then
    raise exception 'fase % não encontrada', p_case_phase_id using errcode = 'no_data_found';
  end if;
  if v_status <> 'ativa' then
    raise exception 'esta fase não está ativa' using errcode = 'HC019';
  end if;
  if v_assigned_to is distinct from v_uid then
    raise exception 'apenas o responsável pode preencher esta fase' using errcode = 'HC022';
  end if;

  -- Resume the phase's existing response (any status; a submitted one is handed
  -- back read-only by the wizard).
  select * into v_result
  from public.responses where case_phase_id = p_case_phase_id;
  if v_result.id is not null then
    return v_result;
  end if;

  -- Create. NOTE: we pin v_version_id WITHOUT the published-only backstop — the
  -- snapshot may now be archived.
  begin
    insert into public.responses (form_version_id, commission_id, created_by, status, case_phase_id)
    values (v_version_id, v_commission_id, v_uid, 'in_progress', p_case_phase_id)
    returning * into v_result;
  exception
    when unique_violation then
      select * into v_result
      from public.responses where case_phase_id = p_case_phase_id;
  end;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."start_or_resume_phase"("p_case_phase_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_or_resume_response"("p_form_version_id" "uuid") RETURNS "public"."responses"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
  v_status text;
  v_uid uuid := auth.uid();
  v_result public.responses;
begin
  -- Resolve the version's form/commission and its lifecycle status.
  select f.commission_id, v.status
    into v_commission_id, v_status
  from public.form_versions v
  join public.forms f on f.id = v.form_id
  where v.id = p_form_version_id;

  if v_commission_id is null then
    raise exception 'versão % não encontrada', p_form_version_id
      using errcode = 'no_data_found';
  end if;

  -- Server backstop: only published versions are fillable (the query layer
  -- lists published only, but a hand-crafted call must not start a draft on an
  -- unpublished/archived version).
  if v_status <> 'published' then
    raise exception 'este formulário não está publicado'
      using errcode = 'check_violation';
  end if;

  -- Resume: hand back the caller's existing in_progress draft if one exists.
  select * into v_result
  from public.responses
  where form_version_id = p_form_version_id
    and created_by = v_uid
    and status = 'in_progress';

  if v_result.id is not null then
    return v_result;
  end if;

  -- Create. The unique index guards against a concurrent create winning the
  -- race; on conflict, re-read and return the surviving draft.
  begin
    insert into public.responses (form_version_id, commission_id, created_by, status)
    values (p_form_version_id, v_commission_id, v_uid, 'in_progress')
    returning * into v_result;
  exception
    when unique_violation then
      select * into v_result
      from public.responses
      where form_version_id = p_form_version_id
        and created_by = v_uid
        and status = 'in_progress';
  end;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."start_or_resume_response"("p_form_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_referral_review"("p_referral_id" "uuid") RETURNS "public"."case_referral"
    LANGUAGE "plpgsql" SECURITY DEFINER
