  perform set_config('app.in_safety_rpc', 'on', true);
  update public.rca
  set status = 'in_review', submitted_by = auth.uid(), submitted_at = now(), updated_at = now()
  where id = p_rca_id
  returning * into v_rca;
  perform set_config('app.in_safety_rpc', 'off', true);

  return v_rca;
end;
$$;


ALTER FUNCTION "public"."submit_rca_for_review"("p_rca_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_response"("p_response_id" "uuid") RETURNS "public"."responses"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_response public.responses;
  v_eff jsonb;          -- effective answer map (question_key -> value), forward pass
  r_section record;
  r_item record;
  v_visible boolean;
  v_missing boolean;
  v_signoff_exists boolean;
  v_result public.responses;
begin
  select * into v_response
  from public.responses
  where id = p_response_id;

  if v_response.id is null then
    raise exception 'resposta % não encontrada', p_response_id
      using errcode = 'no_data_found';
  end if;

  if v_response.status = 'submitted' then
    raise exception 'esta resposta já foi enviada'
      using errcode = 'HC010';
  end if;

  perform 1 from public.responses
  where id = p_response_id and status = 'in_progress'
  for update;

  -- Effective map starts from the saved answers (rebuilt by the normalized
  -- app.answer_map — single->code, checkbox->array of codes, scalars->raw); we DROP
  -- hidden items'/sections' keys as we walk in document order.
  v_eff := app.answer_map(p_response_id);

  perform set_config('app.in_submit_rpc', 'on', true);

  for r_section in
    select s.id, s.position, s.visible_when, s.requires_signoff
    from public.form_sections s
    where s.form_version_id = v_response.form_version_id
    order by s.position
  loop
    v_visible := app.eval_visibility(r_section.visible_when, v_eff);

    if not v_visible then
      -- Stray cleanup for the whole section: delete the answers rows (selections
      -- cascade via answer_id FK) + any group instances, then drop its keys.
      delete from public.answers a
      using public.form_items i
      where a.response_id = p_response_id
        and a.item_id = i.id
        and i.section_id = r_section.id;

      delete from public.response_group_instances gi
      using public.form_items i
      where gi.response_id = p_response_id
        and gi.group_item_id = i.id
        and i.section_id = r_section.id;

      v_eff := v_eff - (
        select coalesce(array_agg(i.question_key), '{}')
        from public.form_items i
        where i.section_id = r_section.id
          and i.question_key is not null
      );
      continue;
    end if;

    for r_item in
      select i.id, i.position, i.item_type, i.question_key, i.label,
             i.required, i.config, i.visible_when
      from public.form_items i
      where i.section_id = r_section.id
        and i.question_key is not null   -- input items only
      order by i.position
    loop
      if not app.eval_visibility(r_item.visible_when, v_eff) then
        -- Hidden item: clear its answer (selections cascade) + group instances +
        -- drop its key.
        delete from public.answers a
        where a.response_id = p_response_id and a.item_id = r_item.id;
        delete from public.response_group_instances gi
        where gi.response_id = p_response_id and gi.group_item_id = r_item.id;
        v_eff := v_eff - r_item.question_key;
        continue;
      end if;

      -- Visible & required: must have a non-null SCALAR answer OR >= 1 selection.
      if r_item.required then
        select not (
          exists (
            select 1 from public.answers a
            where a.response_id = p_response_id
              and a.item_id = r_item.id
              and a.value is not null
              and a.value <> 'null'::jsonb
          )
          or exists (
            select 1
            from public.answer_selected_options s
            join public.answers a on a.id = s.answer_id
            where a.response_id = p_response_id
              and a.item_id = r_item.id
          )
        ) into v_missing;

        if v_missing then
          raise exception 'há perguntas obrigatórias sem resposta'
            using errcode = 'HC011';
        end if;
      end if;

      -- Visible number/date: enforce config min/max (present answer only).
      perform app.assert_item_bounds(
        p_response_id, r_item.id, r_item.item_type, r_item.config, r_item.label
      );
    end loop;

    -- Sign-off check (feature-flagged).
    if r_section.requires_signoff and app.feature_enabled('signoff_enforcement') then
      select exists (
        select 1 from public.response_section_signoffs so
        where so.response_id = p_response_id
          and so.section_id = r_section.id
      ) into v_signoff_exists;

      if not v_signoff_exists then
        raise exception 'há seções pendentes de assinatura'
          using errcode = 'HC012';
      end if;
    end if;
  end loop;

  update public.responses
  set status = 'submitted', submitted_at = now(), updated_at = now()
  where id = p_response_id
  returning * into v_result;

  perform set_config('app.in_submit_rpc', 'off', true);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."submit_response"("p_response_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_case_phase_on_submit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_case_id uuid;
  v_case_status text;
begin
  if new.case_phase_id is null
     or new.status <> 'submitted'
     or old.status = 'submitted' then
    return new;
  end if;

  select cp.case_id, c.status
    into v_case_id, v_case_status
  from public.case_phases cp
  join public.cases c on c.id = cp.case_id
  where cp.id = new.case_phase_id;

  if v_case_status in ('concluido', 'cancelado') then
    return new;
  end if;

  perform set_config('app.in_case_rpc', 'on', true);
  update public.case_phases
  set status = 'concluida', completed_at = now(), updated_at = now()
  where id = new.case_phase_id and status = 'ativa';
  perform set_config('app.in_case_rpc', 'off', true);

  -- Compute (or honor the override for) the phase result, in the same conclude
  -- transition. No-op when the case_phase_results flag is off.
  perform app.compute_case_phase_result(new.case_phase_id);

  perform public.recompute_recommendations(v_case_id);

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_case_phase_on_submit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_profile_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if new.email is distinct from old.email then
    update public.profiles
    set email = new.email
    where id = new.id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_profile_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_event_custody"("p_event_id" "uuid", "p_to_owner_kind" "text", "p_to_commission_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."patient_safety_event"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_event public.patient_safety_event;
  v_status text;
begin
  perform app.assert_patient_safety_enabled();

  if not app.can_read_event(p_event_id, auth.uid()) then
    raise exception 'evento não encontrado' using errcode = 'P0002';
  end if;
  if not app.event_current_custodian(p_event_id, auth.uid()) then
    raise exception 'apenas quem detém a custódia do evento pode transferi-la'
      using errcode = 'HC044';
  end if;

  select status into v_status from public.patient_safety_event where id = p_event_id;
  if v_status in ('closed', 'cancelled') then
    raise exception 'um evento encerrado ou cancelado não pode ter a custódia transferida'
      using errcode = 'HC043';
  end if;

  if p_to_owner_kind not in ('pqs', 'commission') then
    raise exception 'destino de custódia inválido' using errcode = 'check_violation';
  end if;
  if p_to_owner_kind = 'commission' and p_to_commission_id is null then
    raise exception 'selecione a comissão de destino' using errcode = 'check_violation';
  end if;
  if p_to_owner_kind = 'pqs' then
    p_to_commission_id := null;
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);

  -- Close the open interval (the guard admits exactly this held_until move).
  update public.event_custody
  set held_until = now()
  where event_id = p_event_id and held_until is null;

  -- Append the new interval.
  insert into public.event_custody (event_id, owner_kind, owner_commission_id, assigned_by, note)
  values (p_event_id, p_to_owner_kind, p_to_commission_id, auth.uid(), p_note);

  -- Update the denormalized owner head (drives access-follows-custody RLS).
  update public.patient_safety_event
  set current_owner_kind = p_to_owner_kind,
      current_owner_commission_id = p_to_commission_id,
      updated_at = now()
  where id = p_event_id
  returning * into v_event;

  perform set_config('app.in_safety_rpc', 'off', true);
  return v_event;
end;
$$;


ALTER FUNCTION "public"."transfer_event_custody"("p_event_id" "uuid", "p_to_owner_kind" "text", "p_to_commission_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."triage_disposition"("p_event_id" "uuid") RETURNS TABLE("event_id" "uuid", "is_pse" boolean, "reached" boolean, "severe" boolean, "is_sentinel" boolean, "verdict" "text", "review_pathway" "text", "rca_due_date" "date")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_t public.event_triage;
  v_event public.patient_safety_event;
  v_reached boolean;
  v_severe boolean;
  v_verdict text;
  v_pathway text;
  v_due date;
  v_due_days integer;
begin
  if not app.can_read_event(p_event_id, auth.uid()) then
    return;  -- out of scope: no rows
  end if;

  select * into v_event from public.patient_safety_event where id = p_event_id;
  if not found then
    return;
  end if;

  select * into v_t from public.event_triage where event_triage.event_id = p_event_id;

  v_reached := coalesce(v_t.reach in ('no_harm', 'adverse', 'sentinel'), false);
  v_severe := coalesce(v_t.harm_severity in ('severe', 'permanent', 'death'), false);

  if v_t.is_pse is false then
    v_verdict := 'closed';
    v_pathway := null;
  elsif coalesce(v_t.sentinel_determination, false) then
    v_verdict := 'rca';
    v_pathway := 'rca';
  elsif v_t.reach is not null then
    v_verdict := 'review';
    v_pathway := coalesce(v_t.review_pathway, 'peer_review');
  else
    v_verdict := 'pending';
    v_pathway := null;
  end if;

  if v_verdict = 'rca' then
    select rca_default_due_days into v_due_days
    from public.pqs_department where organization_id = app.org_of_event(p_event_id);
    v_due_days := coalesce(v_due_days, 45);
    v_due := coalesce(v_event.discovered_at, v_event.reported_at::date) + v_due_days;
  end if;

  return query select
    p_event_id, v_t.is_pse, v_reached, v_severe,
    coalesce(v_t.sentinel_determination, false), v_verdict, v_pathway, v_due;
end;
$$;


ALTER FUNCTION "public"."triage_disposition"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unassign_case_tag"("p_case_id" "uuid", "p_tag_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_commission_id uuid;
begin
  perform app.assert_extras_enabled();

  v_commission_id := app.commission_of_case(p_case_id);
  if v_commission_id is null then
    raise exception 'caso % não encontrado', p_case_id using errcode = 'no_data_found';
  end if;
  if not app.can_write_case_content(p_case_id, auth.uid()) then
    raise exception 'sem permissão' using errcode = '42501';
  end if;

  delete from public.case_tag_assignments
  where case_id = p_case_id and tag_id = p_tag_id;
end;
$$;


