    "body_md" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "assigned_to" "uuid",
    "status" "text" DEFAULT 'aberta'::"text" NOT NULL,
    "concluded_at" timestamp with time zone,
