CREATE OR REPLACE FUNCTION "public"."update_rca_root_cause"("p_root_cause_id" "uuid", "p_text" "text", "p_category" "text" DEFAULT NULL::"text", "p_classification" "text" DEFAULT 'system'::"text", "p_type" "text" DEFAULT 'root'::"text") RETURNS "public"."rca_root_causes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_rca_id uuid;
  v_row public.rca_root_causes;
begin
  perform app.assert_patient_safety_enabled();
  select rca_id into v_rca_id from public.rca_root_causes where id = p_root_cause_id;
  if v_rca_id is null then
    raise exception 'causa raiz não encontrada' using errcode = 'no_data_found';
  end if;
  perform app.assert_rca_writable(v_rca_id);
  if btrim(coalesce(p_text, '')) = '' then
    raise exception 'descreva a causa raiz' using errcode = 'check_violation';
  end if;
  if p_category is not null
     and p_category not in ('people', 'communication', 'process', 'equipment', 'environment', 'policy') then
    raise exception 'categoria inválida' using errcode = 'check_violation';
  end if;
  if coalesce(p_classification, 'system') not in ('system', 'human', 'environment', 'external') then
    raise exception 'classificação inválida' using errcode = 'check_violation';
  end if;
  if coalesce(p_type, 'root') not in ('root', 'contributing') then
    raise exception 'tipo inválido' using errcode = 'check_violation';
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.rca_root_causes
  set text = p_text, category = p_category,
      classification = coalesce(p_classification, 'system'), type = coalesce(p_type, 'root'),
      updated_at = now()
  where id = p_root_cause_id
  returning * into v_row;
  perform set_config('app.in_safety_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_rca_root_cause"("p_root_cause_id" "uuid", "p_text" "text", "p_category" "text", "p_classification" "text", "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_rca_timeline_entry"("p_entry_id" "uuid", "p_occurred_at" timestamp with time zone, "p_description" "text") RETURNS "public"."rca_timeline_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_rca_id uuid;
  v_row public.rca_timeline_entries;
begin
  perform app.assert_patient_safety_enabled();
  select rca_id into v_rca_id from public.rca_timeline_entries where id = p_entry_id;
  if v_rca_id is null then
    raise exception 'item não encontrado' using errcode = 'no_data_found';
  end if;
  perform app.assert_rca_writable(v_rca_id);
  if btrim(coalesce(p_description, '')) = '' then
    raise exception 'descreva o que ocorreu neste ponto da linha do tempo' using errcode = 'check_violation';
  end if;

  perform set_config('app.in_safety_rpc', 'on', true);
  update public.rca_timeline_entries
  set occurred_at = p_occurred_at, description = p_description
  where id = p_entry_id
  returning * into v_row;
  perform set_config('app.in_safety_rpc', 'off', true);
  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_rca_timeline_entry"("p_entry_id" "uuid", "p_occurred_at" timestamp with time zone, "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_referral_draft"("p_referral_id" "uuid", "p_referral_type_id" "uuid", "p_subject" "text", "p_description_md" "text" DEFAULT NULL::"text", "p_response_expected" boolean DEFAULT true) RETURNS "public"."case_referral"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_type public.referral_types;
  v_row public.case_referral;
begin
  perform app.assert_referrals_enabled();
  perform app.assert_referral_draft_writable(p_referral_id);

  if btrim(coalesce(p_subject, '')) = '' then
    raise exception 'informe um assunto para o encaminhamento' using errcode = 'check_violation';
  end if;
  select * into v_type from public.referral_types where id = p_referral_type_id;
  if v_type.id is null then
    raise exception 'tipo de encaminhamento inválido' using errcode = 'check_violation';
  end if;

  perform set_config('app.in_referral_rpc', 'on', true);
  update public.case_referral
  set referral_type_id = v_type.id,
      type_label = v_type.label,
      subject = btrim(p_subject),
      description_md = p_description_md,
      response_expected = coalesce(p_response_expected, true),
      updated_at = now()
  where id = p_referral_id
  returning * into v_row;
  perform set_config('app.in_referral_rpc', 'off', true);

  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_referral_draft"("p_referral_id" "uuid", "p_referral_type_id" "uuid", "p_subject" "text", "p_description_md" "text", "p_response_expected" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_sentinel_criterion"("p_id" "uuid", "p_label" "text", "p_description" "text" DEFAULT NULL::"text") RETURNS "public"."pqs_sentinel_criteria"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_row public.pqs_sentinel_criteria;
begin
  perform app.assert_patient_safety_enabled();
  if not app.is_pqs_member_of_any(auth.uid()) then
    raise exception 'apenas o NSP pode gerenciar critérios de evento sentinela' using errcode = '42501';
  end if;
  if btrim(coalesce(p_label, '')) = '' then
    raise exception 'informe um rótulo' using errcode = 'check_violation';
  end if;
  update public.pqs_sentinel_criteria
  set label = btrim(p_label), description = p_description, updated_at = now()
  where id = p_id
  returning * into v_row;
  if not found then
    raise exception 'critério não encontrado' using errcode = 'P0002';
  end if;
  return v_row;
end;
$$;


ALTER FUNCTION "public"."update_sentinel_criterion"("p_id" "uuid", "p_label" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_template_narrative"("p_narrative_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_instructions" "text" DEFAULT NULL::"text", "p_is_expected" boolean DEFAULT NULL::boolean, "p_clear_title" boolean DEFAULT false, "p_clear_instructions" boolean DEFAULT false) RETURNS "public"."process_template_narratives"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_template_id uuid;
  v_status text;
  v_result public.process_template_narratives;
begin
  perform app.assert_narratives_enabled();

  select n.template_id, t.status
    into v_template_id, v_status
  from public.process_template_narratives n
  join public.process_templates t on t.id = n.template_id
  where n.id = p_narrative_id;

  if v_template_id is null then
    raise exception 'narrativa % não encontrada', p_narrative_id using errcode = 'no_data_found';
  end if;
  if v_status <> 'draft' then
    raise exception 'apenas processos em rascunho podem ser editados'
      using errcode = 'check_violation';
  end if;

  update public.process_template_narratives
  set title = case
                when p_clear_title then null
                when p_title is null then title
                else nullif(btrim(p_title), '')
              end,
      instructions = case
                       when p_clear_instructions then null
                       when p_instructions is null then instructions
                       else nullif(btrim(p_instructions), '')
                     end,
      is_expected = coalesce(p_is_expected, is_expected)
  where id = p_narrative_id
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."update_template_narrative"("p_narrative_id" "uuid", "p_title" "text", "p_instructions" "text", "p_is_expected" boolean, "p_clear_title" boolean, "p_clear_instructions" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_template_phase"("p_phase_id" "uuid", "p_form_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_recommend_when" "jsonb" DEFAULT NULL::"jsonb", "p_clear_recommend_when" boolean DEFAULT false, "p_default_due_days" integer DEFAULT NULL::integer, "p_clear_default_due_days" boolean DEFAULT false, "p_blocks" integer[] DEFAULT NULL::integer[], "p_clear_blocks" boolean DEFAULT false, "p_result_ruleset" "jsonb" DEFAULT NULL::"jsonb", "p_clear_result_ruleset" boolean DEFAULT false, "p_emits_result" boolean DEFAULT NULL::boolean, "p_allowed_result_ids" "jsonb" DEFAULT NULL::"jsonb", "p_clear_allowed_result_ids" boolean DEFAULT false) RETURNS "public"."process_template_phases"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_template_id uuid;
  v_position integer;
  v_status text;
  v_commission_id uuid;
  v_new_recommend jsonb;
  v_new_due_days integer;
  v_new_blocks integer[];
  v_new_ruleset jsonb;
  v_new_emits boolean;
  v_new_allowed jsonb;
  v_result public.process_template_phases;
begin
  perform app.assert_cases_enabled();

  select ph.template_id, ph.position, t.status, t.commission_id
    into v_template_id, v_position, v_status, v_commission_id
  from public.process_template_phases ph
  join public.process_templates t on t.id = ph.template_id
  where ph.id = p_phase_id;

  if v_template_id is null then
    raise exception 'fase % não encontrada', p_phase_id using errcode = 'no_data_found';
  end if;
  if v_status <> 'draft' then
    raise exception 'apenas processos em rascunho podem ser editados'
      using errcode = 'check_violation';
  end if;

  if p_form_id is not null and not exists (
    select 1 from public.forms where id = p_form_id and commission_id = v_commission_id
  ) then
    raise exception 'o formulário não pertence a esta comissão'
      using errcode = 'check_violation';
  end if;

  if p_clear_recommend_when then
    v_new_recommend := null;
  elsif p_recommend_when is not null then
    v_new_recommend := p_recommend_when;
  else
    select recommend_when into v_new_recommend
    from public.process_template_phases where id = p_phase_id;
  end if;

  if p_clear_default_due_days then
    v_new_due_days := null;
  elsif p_default_due_days is not null then
    v_new_due_days := p_default_due_days;
  else
    select default_due_days into v_new_due_days
    from public.process_template_phases where id = p_phase_id;
  end if;

  if p_clear_blocks then
    v_new_blocks := '{}';
  elsif p_blocks is not null then
    v_new_blocks := coalesce(
      (select array_agg(distinct b order by b)
       from unnest(p_blocks) as b
       where b is not null),
      '{}');
  else
    select blocks into v_new_blocks
    from public.process_template_phases where id = p_phase_id;
  end if;

  -- result_ruleset (automatic): clear/replace/keep.
  if p_clear_result_ruleset then
    v_new_ruleset := null;
  elsif p_result_ruleset is not null then
    v_new_ruleset := p_result_ruleset;
  else
    select result_ruleset into v_new_ruleset
    from public.process_template_phases where id = p_phase_id;
  end if;

  -- allowed_result_ids: clear/replace/keep.
  if p_clear_allowed_result_ids then
    v_new_allowed := null;
  elsif p_allowed_result_ids is not null then
    v_new_allowed := p_allowed_result_ids;
  else
    select allowed_result_ids into v_new_allowed
    from public.process_template_phases where id = p_phase_id;
  end if;

  -- emits_result: explicit boolean when provided, else keep.
  if p_emits_result is not null then
    v_new_emits := p_emits_result;
  else
    select emits_result into v_new_emits
    from public.process_template_phases where id = p_phase_id;
  end if;

  update public.process_template_phases
  set form_id = coalesce(p_form_id, form_id),
      title = case when p_title is null then title else nullif(btrim(p_title), '') end,
      recommend_when = v_new_recommend,
      default_due_days = v_new_due_days,
      blocks = v_new_blocks,
      result_ruleset = v_new_ruleset,
      emits_result = v_new_emits,
      allowed_result_ids = v_new_allowed
  where id = p_phase_id
  returning * into v_result;

  perform app.validate_template_recommend_when(v_template_id, v_position, v_new_recommend);
  perform app.validate_template_phase_blocks(v_template_id, v_position, v_new_blocks);
  perform app.validate_template_result_ruleset(v_template_id, v_position, v_new_ruleset);
  perform app.validate_template_allowed_results(v_template_id, v_position, v_new_allowed);

  return v_result;
end;
$$;


ALTER FUNCTION "public"."update_template_phase"("p_phase_id" "uuid", "p_form_id" "uuid", "p_title" "text", "p_recommend_when" "jsonb", "p_clear_recommend_when" boolean, "p_default_due_days" integer, "p_clear_default_due_days" boolean, "p_blocks" integer[], "p_clear_blocks" boolean, "p_result_ruleset" "jsonb", "p_clear_result_ruleset" boolean, "p_emits_result" boolean, "p_allowed_result_ids" "jsonb", "p_clear_allowed_result_ids" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_visible_when"("p_form_version_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  r record;            -- section with a condition
  ri record;           -- item with a condition
  rc record;           -- one sub-condition (jsonb)
  v_first_position integer;
  v_ref_min_position integer;
  v_op text;
  v_target_type text;  -- the referenced input's item_type
  v_dep_section integer;
  v_dep_item integer;
  v_ref_section integer;
  v_ref_item integer;
  v_ref_key text;
begin
  select min(position) into v_first_position
  from public.form_sections
  where form_version_id = p_form_version_id;

  -- ---- SECTION conditions (single OR group). ----
  for r in
    select id, position, title, visible_when
    from public.form_sections
    where form_version_id = p_form_version_id
      and visible_when is not null
    order by position
  loop
    if r.position = v_first_position then
      raise exception
        'a primeira seção não pode ter condição de visibilidade (seção "%")',
        coalesce(r.title, '(padrão)')
        using errcode = 'check_violation';
    end if;

    for rc in select cond from app.visibility_conditions(r.visible_when) cond loop
      v_op := rc.cond ->> 'op';
      v_ref_key := rc.cond ->> 'question_key';

      select min(s.position), max(i.item_type)
        into v_ref_min_position, v_target_type
      from public.form_items i
      join public.form_sections s on s.id = i.section_id
      where i.form_version_id = p_form_version_id
        and i.question_key = v_ref_key;

      if v_ref_min_position is null then
        raise exception
          'a condição da seção "%" referencia a pergunta "%", que não existe nesta versão',
          coalesce(r.title, '(padrão)'), v_ref_key
          using errcode = 'check_violation';
      end if;

      if v_ref_min_position >= r.position then
        raise exception
          'a condição da seção "%" deve referenciar uma pergunta de uma seção anterior',
          coalesce(r.title, '(padrão)')
          using errcode = 'check_violation';
      end if;

      perform app.assert_condition_op_target(
        v_op, v_target_type, rc.cond -> 'value',
        format('a condição da seção "%s"', coalesce(r.title, '(padrão)'))
      );

      -- form-model-normalization: choice-target value codes must exist.
      perform app.assert_condition_value_codes(
        p_form_version_id, v_ref_key, v_target_type, rc.cond -> 'value',
        format('a condição da seção "%s"', coalesce(r.title, '(padrão)'))
      );
    end loop;
  end loop;

  -- ---- ITEM conditions (single OR group). ----
  for ri in
    select i.id, i.label, i.question_key, i.visible_when,
           s.position as section_position, i.position as item_position
    from public.form_items i
    join public.form_sections s on s.id = i.section_id
    where i.form_version_id = p_form_version_id
      and i.visible_when is not null
    order by s.position, i.position
  loop
    v_dep_section := ri.section_position;
    v_dep_item := ri.item_position;

    for rc in select cond from app.visibility_conditions(ri.visible_when) cond loop
      v_op := rc.cond ->> 'op';
      v_ref_key := rc.cond ->> 'question_key';

      select s.position, i.position, i.item_type
        into v_ref_section, v_ref_item, v_target_type
      from public.form_items i
      join public.form_sections s on s.id = i.section_id
      where i.form_version_id = p_form_version_id
        and i.question_key = v_ref_key
      order by s.position, i.position
      limit 1;

      if v_ref_section is null then
        raise exception
          'a condição da pergunta "%" referencia a pergunta "%", que não existe nesta versão',
          coalesce(ri.label, '(sem rótulo)'), v_ref_key
          using errcode = 'check_violation';
      end if;

      if not (v_ref_section < v_dep_section
              or (v_ref_section = v_dep_section and v_ref_item < v_dep_item)) then
        raise exception
          'a condição da pergunta "%" deve referenciar uma pergunta anterior no formulário',
          coalesce(ri.label, '(sem rótulo)')
          using errcode = 'check_violation';
      end if;

      perform app.assert_condition_op_target(
        v_op, v_target_type, rc.cond -> 'value',
        format('a condição da pergunta "%s"', coalesce(ri.label, '(sem rótulo)'))
      );

      -- form-model-normalization: choice-target value codes must exist.
      perform app.assert_condition_value_codes(
        p_form_version_id, v_ref_key, v_target_type, rc.cond -> 'value',
        format('a condição da pergunta "%s"', coalesce(ri.label, '(sem rótulo)'))
      );
    end loop;
  end loop;

  return true;
end;
$$;


ALTER FUNCTION "public"."validate_visible_when"("p_form_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_audit_chain"("p_commission" "uuid" DEFAULT NULL::"uuid", "p_organization" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("ok" boolean, "broken_seq" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_rec record;
  v_prev_hash text;
  v_expected text;
  v_chain_org uuid;
  v_chain_comm uuid;
begin
  perform app.assert_audit_enabled();

  -- Authorization, per tier.
  if p_commission is not null then
    if not (app.is_staff_admin_of(p_commission) or app.is_org_admin_of_commission(p_commission)) then
      raise exception 'não autorizado' using errcode = '42501';
    end if;
  elsif p_organization is not null then
    if not app.is_org_admin_of(p_organization) then
      raise exception 'não autorizado' using errcode = '42501';
    end if;
  else
    -- platform chain: platform_admin only.
    if not app.is_admin() then
      raise exception 'não autorizado' using errcode = '42501';
    end if;
  end if;

  -- Build the chain identities to verify, BY PRECEDENCE (matching audit_write):
  --   v_chain_comm set        -> commission chain (enumerate by commission_id alone)
  --   v_chain_org set, comm 0 -> org chain        (organization_id, commission NULL)
  --   both 0                  -> platform chain   (both NULL)
  -- A sentinel ('0' uuid) marks "not this tier" since a plain NULL is ambiguous
  -- with the platform tier; we use a separate boolean column instead.
  for v_chain_org, v_chain_comm in
    select o, c from (
      -- a specific commission chain (org irrelevant — keyed on commission_id)
      select null::uuid as o, p_commission as c
      where p_commission is not null
      union all
      -- a specific org chain (commission NULL)
      select p_organization as o, null::uuid as c
      where p_commission is null and p_organization is not null
      union all
      -- platform chain (org NULL, commission NULL)
      select null::uuid as o, null::uuid as c
      where p_commission is null and p_organization is null
    ) chains
  loop
    v_prev_hash := null;
    for v_rec in
      select * from public.audit_log
      where (
              -- commission tier: keyed on commission_id ALONE
              (v_chain_comm is not null and commission_id = v_chain_comm)
              -- org tier: organization_id set, commission NULL
              or (v_chain_comm is null and v_chain_org is not null
                  and organization_id = v_chain_org and commission_id is null)
              -- platform tier: both NULL
              or (v_chain_comm is null and v_chain_org is null
                  and organization_id is null and commission_id is null)
            )
      order by seq asc
    loop
      v_expected := encode(
        extensions.digest(
          coalesce(v_prev_hash, '') || app.audit_canonical(
            v_rec.seq, v_rec.occurred_at, v_rec.actor_id, v_rec.actor_is_admin,
            v_rec.commission_id, v_rec.action, v_rec.entity_type, v_rec.entity_id,
            v_rec.summary, v_rec.metadata, v_rec.organization_id
          ),
          'sha256'
        ),
        'hex'
      );
      if v_rec.prev_hash is distinct from v_prev_hash or v_rec.row_hash <> v_expected then
        ok := false;
        broken_seq := v_rec.seq;
        return next;
        return;
      end if;
      v_prev_hash := v_rec.row_hash;
    end loop;
  end loop;

  ok := true;
  broken_seq := null;
  return next;
end;
$$;


ALTER FUNCTION "public"."verify_audit_chain"("p_commission" "uuid", "p_organization" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."withdraw_referral"("p_referral_id" "uuid") RETURNS "public"."case_referral"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'app', 'public', 'pg_catalog'
    AS $$
declare
  v_status text;
  v_row public.case_referral;
begin
  perform app.assert_referrals_enabled();
  select status into v_status from public.case_referral where id = p_referral_id;
  if v_status is null then
    raise exception 'encaminhamento não encontrado' using errcode = 'P0002';
  end if;
  if not app.can_manage_referral_source(p_referral_id, auth.uid()) then
    raise exception 'apenas a coordenação da comissão de origem pode retirar o encaminhamento'
      using errcode = 'HC071';
  end if;
  if v_status not in ('rascunho', 'enviada', 'recebida', 'aceita', 'em_analise') then
    raise exception 'este encaminhamento não pode ser retirado neste estado' using errcode = 'HC070';
  end if;

  perform set_config('app.in_referral_rpc', 'on', true);
  update public.case_referral
  set status = 'retirada', withdrawn_at = now(), withdrawn_by = auth.uid(), updated_at = now()
  where id = p_referral_id
  returning * into v_row;
  perform set_config('app.in_referral_rpc', 'off', true);

  return v_row;
end;
$$;


ALTER FUNCTION "public"."withdraw_referral"("p_referral_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "app"."app_secrets" (
    "key" "text" NOT NULL,
    "value" "text" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "app"."app_secrets" OWNER TO "postgres";


COMMENT ON TABLE "app"."app_secrets" IS 'Server-side application secrets (ADR 0039) — currently the HMAC pepper for patient-identity linkage (key = ''mrn_pepper''). In the `app` schema (NOT public) so it is never PostgREST-exposed; all DML REVOKED from authenticated/anon, SELECT granted only to service_role. The DEFINER app.derive_patient_key reads it as owner. Superuser/owner-visible is the accepted ADR-0035 residual (the keyed hash is a linkage control, not an at-rest-encryption control).';



CREATE TABLE IF NOT EXISTS "app"."feature_flags" (
    "key" "text" NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "description" "text"
);


ALTER TABLE "app"."feature_flags" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."answer_selected_options" (
    "option_id" "uuid" NOT NULL,
    "answer_id" "uuid" NOT NULL
);


ALTER TABLE "public"."answer_selected_options" OWNER TO "postgres";


COMMENT ON TABLE "public"."answer_selected_options" IS 'answer-model-v2 (ADR 0045): choice-answer selections hang off the parent answers row (answer_id -> answers). Response / item / instance are inherited via answer_id; PK (answer_id, option_id) — the nullable-key trap is avoided by construction. RLS + submitted-immutability re-derive the response through answer_id.';



CREATE TABLE IF NOT EXISTS "public"."answers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "response_id" "uuid" NOT NULL,
    "item_id" "uuid" NOT NULL,
    "question_key" "text" NOT NULL,
    "value" "jsonb",
    "observation" "text",
    "group_instance_id" "uuid",
    "value_number" numeric,
    "value_date" "date",
    "value_time" time without time zone,
    "answered_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "confidentiality_level" "text" DEFAULT 'standard'::"text" NOT NULL
);


ALTER TABLE "public"."answers" OWNER TO "postgres";


COMMENT ON COLUMN "public"."answers"."group_instance_id" IS 'answer-model-v2 (ADR 0045): repeating-group instance this answer belongs to (NULL = top-level; the ONLY value written until repeating groups ship).';



COMMENT ON COLUMN "public"."answers"."value_number" IS 'answer-model-v2 (ADR 0045): typed denormalization of value for number items, derived by app.sync_answer_typed_values. value jsonb stays the CANONICAL evaluator input; this is analytics/indexing only.';



COMMENT ON COLUMN "public"."answers"."value_date" IS 'answer-model-v2 (ADR 0045): typed denormalization of value for date items (trigger-derived; analytics only).';



COMMENT ON COLUMN "public"."answers"."value_time" IS 'answer-model-v2 (ADR 0045): typed denormalization of value for time items (trigger-derived; analytics only).';



COMMENT ON COLUMN "public"."answers"."answered_at" IS 'answer-model-v2 (ADR 0045): contemporaneous per-answer timestamp (ALCOA+); set on insert, refreshed by save_section_answers when the answer changes.';



COMMENT ON COLUMN "public"."answers"."confidentiality_level" IS 'answer-model-v2 (ADR 0045/0046): RESERVED + UNENFORCED field-level confidentiality hook; default ''standard''. No RLS predicate keys on it yet.';



CREATE TABLE IF NOT EXISTS "public"."audit_log" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "commission_id" "uuid",
    "actor_id" "uuid",
    "actor_is_admin" boolean DEFAULT false NOT NULL,
    "action" "text" NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "summary" "text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "seq" bigint NOT NULL,
    "prev_hash" "text",
    "row_hash" "text" NOT NULL,
    "organization_id" "uuid",
    CONSTRAINT "audit_log_action_shape" CHECK ((POSITION(('.'::"text") IN ("action")) > 1)),
    CONSTRAINT "audit_log_entity_type_not_blank" CHECK (("btrim"("entity_type") <> ''::"text")),
    CONSTRAINT "audit_log_seq_positive" CHECK (("seq" >= 1)),
    CONSTRAINT "audit_log_summary_not_blank" CHECK (("btrim"("summary") <> ''::"text"))
);


ALTER TABLE "public"."audit_log" OWNER TO "postgres";


COMMENT ON COLUMN "public"."audit_log"."commission_id" IS 'NULL = the global chain (admin/system/cross-commission). ON DELETE NO ACTION: commissions are archived, not dropped; audit rows are never deleted (ADR 0029).';



COMMENT ON COLUMN "public"."audit_log"."metadata" IS 'Curated old->new diff over a NON-SENSITIVE column allow-list ONLY. NEVER answer payloads or *_md/free-text/Markdown bodies (Rule 1 + Rule 11).';



COMMENT ON COLUMN "public"."audit_log"."organization_id" IS 'Tenant org for this audit row. NULL+commission NULL = platform chain; SET+commission NULL = org chain; SET+commission SET = commission chain (org derived from the commission). Part of the hashed canonical tuple.';



CREATE TABLE IF NOT EXISTS "public"."case_access" (
    "case_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "level" "text" NOT NULL,
    "granted_by" "uuid",
    "granted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "case_access_level_check" CHECK (("level" = ANY (ARRAY['read'::"text", 'write'::"text"])))
);


ALTER TABLE "public"."case_access" OWNER TO "postgres";


COMMENT ON TABLE "public"."case_access" IS 'Per-case ACL (ADR 0033 D6). One (case,user) grant; level write implies read. Attribution-derived read is NOT stored here — it is computed in app.can_read_case. Writes via grant_case_access / revoke_case_access (DEFINER) only; no INSERT/UPDATE/DELETE policy.';



CREATE TABLE IF NOT EXISTS "public"."case_documents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "case_id" "uuid" NOT NULL,
    "doc_type" "text" DEFAULT 'other'::"text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "storage_path" "text" NOT NULL,
    "mime_type" "text",
    "size_bytes" bigint,
    "occurred_at" "date",
    "uploaded_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "deleted_by" "uuid",
    CONSTRAINT "case_documents_doc_type_check" CHECK (("doc_type" = ANY (ARRAY['ata'::"text", 'digitalizacao'::"text", 'registro'::"text", 'other'::"text"]))),
    CONSTRAINT "case_documents_size_nonneg" CHECK ((("size_bytes" IS NULL) OR ("size_bytes" >= 0))),
    CONSTRAINT "case_documents_title_not_blank" CHECK (("btrim"("title") <> ''::"text"))
);


ALTER TABLE "public"."case_documents" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."case_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "case_id" "uuid" NOT NULL,
    "kind" "text" DEFAULT 'note'::"text" NOT NULL,
    "title" "text",
    "body" "text" NOT NULL,
    "occurred_at" "date",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "occurred_time" time without time zone,
    CONSTRAINT "case_events_body_not_blank" CHECK (("btrim"("body") <> ''::"text")),
    CONSTRAINT "case_events_kind_check" CHECK (("kind" = ANY (ARRAY['note'::"text", 'meeting'::"text", 'decision'::"text", 'interview'::"text", 'safety_event'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."case_events" OWNER TO "postgres";


COMMENT ON COLUMN "public"."case_events"."body" IS 'PHI-BEARING free text (WS B; Rule 11/12). Case-event working-note body; detail-open audited via case.opened; never copied into the audit log.';



COMMENT ON COLUMN "public"."case_events"."occurred_time" IS 'Optional wall-clock time companion to occurred_at (date). NULL = no time. Governance metadata, not PHI; surfaced as HH:mm in the UI.';



CREATE TABLE IF NOT EXISTS "public"."case_offered_outcomes" (
    "case_id" "uuid" NOT NULL,
    "outcome_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."case_offered_outcomes" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."case_patient" (
    "case_id" "uuid" NOT NULL,
    "name" "text",
    "mrn" "text",
    "date_of_birth" "date",
    "age_years" integer,
    "sex" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "encounter_ref" "text",
    "unit" "text",
    "attending" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "patient_key" "text",
    "encounter_key" "text",
    CONSTRAINT "case_patient_age_nonneg" CHECK ((("age_years" IS NULL) OR ("age_years" >= 0))),
    CONSTRAINT "case_patient_sex_check" CHECK (("sex" = ANY (ARRAY['female'::"text", 'male'::"text", 'other'::"text", 'unknown'::"text"])))
);


ALTER TABLE "public"."case_patient" OWNER TO "postgres";


COMMENT ON TABLE "public"."case_patient" IS 'ISOLATED PHI (Rule 12; ADR 0038) — the ONLY place case patient identifiers live. 0..1 per case (PK = case_id). Read via the dedicated AUDITED door only (get_case_patient -> case_patient.read); direct SELECT is REVOKED from authenticated. NEVER selected on list/board/dashboard paths (minimum-necessary). Modeled exactly on public.event_patient / public.referral_patient. The READ scope is the BROAD app.can_read_case (assignees need the MRN), unlike the staff_admin+PQS predicates of the other two modules — see ADR 0038.';



COMMENT ON COLUMN "public"."case_patient"."patient_key" IS 'ADR 0039 — non-reversible keyed hash of the MRN (see event_patient.patient_key). NOT PHI.';



COMMENT ON COLUMN "public"."case_patient"."encounter_key" IS 'ADR 0039 — non-reversible keyed hash of the encounter number (see event_patient.encounter_key). NOT PHI.';



CREATE TABLE IF NOT EXISTS "public"."case_phase_offered_results" (
    "case_id" "uuid" NOT NULL,
    "result_id" "uuid" NOT NULL
);


ALTER TABLE "public"."case_phase_offered_results" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."case_tag_assignments" (
