    "assigned_by" "uuid",
    "assigned_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."case_tag_assignments" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."commission_members" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "commission_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "role" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "commission_members_role_check" CHECK (("role" = ANY (ARRAY['staff'::"text", 'staff_admin'::"text"])))
);


ALTER TABLE "public"."commission_members" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."commissions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "slug" "extensions"."citext" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "hospital_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    CONSTRAINT "commissions_slug_format" CHECK (("slug" OPERATOR("extensions".~) '^[a-z0-9]+(-[a-z0-9]+)*$'::"extensions"."citext"))
);


ALTER TABLE "public"."commissions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."commissions"."hospital_id" IS 'The hospital this commission belongs to (NOT NULL since Phase C).';



COMMENT ON COLUMN "public"."commissions"."organization_id" IS 'DENORMALIZED from hospital_id via the commission_derive_organization_id trigger (non-app-writable, cannot drift). NOT NULL since Phase C. Single-hop org for per-org slug uniqueness + the org-admin predicates.';



CREATE TABLE IF NOT EXISTS "public"."event_custody" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "event_id" "uuid" NOT NULL,
    "owner_kind" "text" NOT NULL,
    "owner_commission_id" "uuid",
    "held_from" timestamp with time zone DEFAULT "now"() NOT NULL,
    "held_until" timestamp with time zone,
    "assigned_by" "uuid",
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "event_custody_interval_order" CHECK ((("held_until" IS NULL) OR ("held_until" >= "held_from"))),
    CONSTRAINT "event_custody_owner_kind_check" CHECK (("owner_kind" = ANY (ARRAY['pqs'::"text", 'commission'::"text"]))),
    CONSTRAINT "event_custody_owner_shape" CHECK (((("owner_kind" = 'pqs'::"text") AND ("owner_commission_id" IS NULL)) OR (("owner_kind" = 'commission'::"text") AND ("owner_commission_id" IS NOT NULL))))
);


ALTER TABLE "public"."event_custody" OWNER TO "postgres";


COMMENT ON TABLE "public"."event_custody" IS 'APPEND-ONLY custody ledger (ADR 0031). Current holder = the row with held_until IS NULL. Guarded: only a held_until NULL->non-null close (under app.in_safety_rpc) is permitted; no other UPDATE, no DELETE — a closed interval is permanent.';



CREATE TABLE IF NOT EXISTS "public"."event_patient" (
    "event_id" "uuid" NOT NULL,
    "name" "text",
    "mrn" "text",
    "date_of_birth" "date",
    "age_years" integer,
    "sex" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "encounter_ref" "text",
    "unit" "text",
    "attending" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "patient_key" "text",
    "encounter_key" "text",
    CONSTRAINT "event_patient_age_nonneg" CHECK ((("age_years" IS NULL) OR ("age_years" >= 0))),
    CONSTRAINT "event_patient_sex_check" CHECK (("sex" = ANY (ARRAY['female'::"text", 'male'::"text", 'other'::"text", 'unknown'::"text"])))
);


ALTER TABLE "public"."event_patient" OWNER TO "postgres";


COMMENT ON TABLE "public"."event_patient" IS 'ISOLATED PHI (Rule 12) — the ONLY place patient identifiers live. 0..1 per event (PK = event_id). Read via the dedicated AUDITED path only (event_patient.read, Rule 11); NEVER selected on queue/list/aggregate paths. Encryption-ready.';



COMMENT ON COLUMN "public"."event_patient"."patient_key" IS 'ADR 0039 — non-reversible keyed hash of the MRN (HMAC-SHA256 under the app.app_secrets pepper). NOT PHI. Derived ALWAYS by app.trg_derive_patient_keys (not flag-gated; the flag gates exposure via the RPCs/UI). Links the patient across committees via public.patient_xref. NULL only when there is no MRN.';



COMMENT ON COLUMN "public"."event_patient"."encounter_key" IS 'ADR 0039 — non-reversible keyed hash of the encounter number. NOT PHI. Lets QPS pivot encounter -> patient. NULL only when there is no encounter.';



CREATE TABLE IF NOT EXISTS "public"."event_triage_sentinel_flags" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "event_id" "uuid" NOT NULL,
    "criteria_id" "uuid",
    "criteria_key" "text" NOT NULL,
    "criteria_label" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."event_triage_sentinel_flags" OWNER TO "postgres";


COMMENT ON TABLE "public"."event_triage_sentinel_flags" IS 'The permanent record of which designated sentinel criteria were flagged on a worksheet (Phase 14b). criteria_key/label are SNAPSHOTTED at flag time so the record stays viewable-forever across vocab edits.';



CREATE TABLE IF NOT EXISTS "public"."form_item_options" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "item_id" "uuid" NOT NULL,
    "form_version_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "code" "text" NOT NULL,
    "label" "text" NOT NULL,
    "color_token" "text",
    "score" numeric,
    "analytics_code" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "form_item_options_code_not_blank" CHECK (("btrim"("code") <> ''::"text")),
    CONSTRAINT "form_item_options_color_token_check" CHECK ((("color_token" IS NULL) OR ("color_token" = ANY (ARRAY['muted'::"text", 'slate'::"text", 'blue'::"text", 'amber'::"text", 'green'::"text", 'red'::"text", 'violet'::"text"])))),
    CONSTRAINT "form_item_options_label_not_blank" CHECK (("btrim"("label") <> ''::"text"))
);


ALTER TABLE "public"."form_item_options" OWNER TO "postgres";


COMMENT ON TABLE "public"."form_item_options" IS 'Normalized per-question choice options (form-model-normalization). Version-scoped, cloned + frozen with the version. `code` is the stable hidden analytics/condition identity (conditions/recommend_when/result_ruleset + dashboards key on it); `label` is the renameable display text. Only choice item_types (multiple_choice/dropdown/checkbox) own rows.';



COMMENT ON COLUMN "public"."form_item_options"."code" IS 'Auto slug(label)+suffix, immutable (trg_form_item_options_code_immutable), unique per item. The clone-stable analytics/condition identity — NEVER rewritten, copied verbatim on clone.';



COMMENT ON COLUMN "public"."form_item_options"."analytics_code" IS 'Optional author-facing free-text cross-form tagging hook (greenfield indicator engine). No managed vocabulary yet.';



CREATE TABLE IF NOT EXISTS "public"."form_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "section_id" "uuid" NOT NULL,
    "form_version_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "item_type" "text" NOT NULL,
    "question_key" "text",
    "label" "text",
    "question_explanation" "text",
    "required" boolean DEFAULT false NOT NULL,
    "content" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "config" "jsonb",
    "visible_when" "jsonb",
    "parent_item_id" "uuid",
    "default_value" "jsonb",
    CONSTRAINT "form_items_conditional_not_required" CHECK ((("visible_when" IS NULL) OR ("required" = false))),
    CONSTRAINT "form_items_config_shape" CHECK ((("config" IS NULL) OR ("jsonb_typeof"("config") = 'object'::"text"))),
    CONSTRAINT "form_items_default_value_display_null" CHECK ((("default_value" IS NULL) OR ("item_type" <> ALL (ARRAY['section_text'::"text", 'image'::"text"])))),
    CONSTRAINT "form_items_input_vs_display" CHECK (
CASE
    WHEN ("item_type" = ANY (ARRAY['multiple_choice'::"text", 'dropdown'::"text", 'checkbox'::"text", 'free_text'::"text", 'short_text'::"text", 'number'::"text", 'date'::"text", 'time'::"text"])) THEN (("question_key" IS NOT NULL) AND ("label" IS NOT NULL) AND ("content" IS NULL))
    WHEN ("item_type" = ANY (ARRAY['section_text'::"text", 'image'::"text"])) THEN (("content" IS NOT NULL) AND ("question_key" IS NULL) AND ("label" IS NULL) AND ("question_explanation" IS NULL) AND ("required" = false))
    ELSE NULL::boolean
END),
    CONSTRAINT "form_items_item_type_check" CHECK (("item_type" = ANY (ARRAY['multiple_choice'::"text", 'dropdown'::"text", 'checkbox'::"text", 'free_text'::"text", 'short_text'::"text", 'number'::"text", 'date'::"text", 'time'::"text", 'section_text'::"text", 'image'::"text"]))),
    CONSTRAINT "form_items_visible_when_shape" CHECK ((("visible_when" IS NULL) OR "app"."is_valid_visibility"("visible_when")))
);


ALTER TABLE "public"."form_items" OWNER TO "postgres";


COMMENT ON COLUMN "public"."form_items"."parent_item_id" IS 'answer-model-v2 (ADR 0046): future repeating_group container owning this item. ALWAYS NULL now (all forms flat); exists so the definition model is coherent with the instance-ready answer model (answers.group_instance_id). clone_form_version remaps it. Same-section/version consistency CHECK deferred while all values are NULL.';



COMMENT ON COLUMN "public"."form_items"."default_value" IS 'answer-model-v2 (ADR 0046 / P2.4): per-input default value used to pre-fill an unanswered VISIBLE item in the wizard. Scalar for free_text/short_text/number/date/time; option code (single) or code array (checkbox) for choice; NULL for display items (CHECK). clone_form_version copies it verbatim; publish_form_version validates it (HC080).';



CREATE TABLE IF NOT EXISTS "public"."form_sections" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "form_version_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "title" "text",
    "description" "text",
    "is_default" boolean DEFAULT false NOT NULL,
    "visible_when" "jsonb",
    "requires_signoff" boolean DEFAULT false NOT NULL,
    "signoff_role" "text",
    CONSTRAINT "form_sections_default_shape" CHECK (((NOT "is_default") OR (("visible_when" IS NULL) AND ("requires_signoff" = false)))),
    CONSTRAINT "form_sections_signoff_role" CHECK ((("requires_signoff" AND ("signoff_role" IS NOT NULL)) OR ((NOT "requires_signoff") AND ("signoff_role" IS NULL)))),
    CONSTRAINT "form_sections_signoff_role_check" CHECK (("signoff_role" = ANY (ARRAY['respondent'::"text", 'staff_admin'::"text"]))),
    CONSTRAINT "form_sections_visible_when_shape" CHECK ((("visible_when" IS NULL) OR "app"."is_valid_visibility"("visible_when")))
);


ALTER TABLE "public"."form_sections" OWNER TO "postgres";


COMMENT ON CONSTRAINT "form_sections_default_shape" ON "public"."form_sections" IS 'The default (anchor) section may carry a title but never a visibility condition or a sign-off requirement: it is always first, so it cannot reference an earlier answer, and sign-off on the anchor is out of scope.';



CREATE TABLE IF NOT EXISTS "public"."forms" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "commission_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."forms" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."hospitals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "slug" "extensions"."citext" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "hospitals_name_not_blank" CHECK (("btrim"("name") <> ''::"text")),
    CONSTRAINT "hospitals_slug_format" CHECK (("slug" OPERATOR("extensions".~) '^[a-z0-9]+(-[a-z0-9]+)*$'::"extensions"."citext"))
);


ALTER TABLE "public"."hospitals" OWNER TO "postgres";


COMMENT ON TABLE "public"."hospitals" IS 'A facility within an organization. Slug is unique per organization; hospital is a data/admin/reporting grouping, NOT part of the URL (commissions carry the routed slug).';



CREATE TABLE IF NOT EXISTS "public"."organization_members" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "role" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "organization_members_role_check" CHECK (("role" = ANY (ARRAY['org_admin'::"text", 'nsp_coordinator'::"text"])))
);


ALTER TABLE "public"."organization_members" OWNER TO "postgres";


COMMENT ON TABLE "public"."organization_members" IS 'Org-level role membership. org_admin = org-scoped super-user (sees/writes everything in its org, nothing in any other). The role CHECK is the widening seam for a future hospital_admin.';



COMMENT ON CONSTRAINT "organization_members_role_check" ON "public"."organization_members" IS 'NSP-per-org (ADR 0042): widened to {org_admin, nsp_coordinator}. org_admin = org super-user; nsp_coordinator = curates that org''s PQS roster (pqs_members) — three-way duty separation (org_admin appoints ≠ coordinator curates ≠ enrolled member reads PHI).';



CREATE TABLE IF NOT EXISTS "public"."organizations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "slug" "extensions"."citext" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "organizations_name_not_blank" CHECK (("btrim"("name") <> ''::"text")),
    CONSTRAINT "organizations_slug_format" CHECK (("slug" OPERATOR("extensions".~) '^[a-z0-9]+(-[a-z0-9]+)*$'::"extensions"."citext"))
);


ALTER TABLE "public"."organizations" OWNER TO "postgres";


COMMENT ON TABLE "public"."organizations" IS 'Top-level tenant (the customer/buyer). Slug is globally unique — it is the /o/[org] route key. Provisioned by platform_admin (is_admin); org_admins administer their own org below it.';



CREATE TABLE IF NOT EXISTS "public"."patient_xref" (
    "module" "text" NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "commission_id" "uuid",
    "patient_key" "text",
    "encounter_key" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "disposed_at" timestamp with time zone,
    "disposed_reason" "text",
    CONSTRAINT "patient_xref_disposed_reason_check" CHECK ((("disposed_reason" IS NULL) OR ("disposed_reason" = ANY (ARRAY['retention_expired'::"text", 'subject_request'::"text", 'entered_in_error'::"text", 'duplicate'::"text", 'other'::"text"])))),
    CONSTRAINT "patient_xref_module_check" CHECK (("module" = ANY (ARRAY['event'::"text", 'referral'::"text", 'case'::"text"])))
);


ALTER TABLE "public"."patient_xref" OWNER TO "postgres";


COMMENT ON TABLE "public"."patient_xref" IS 'ADR 0039 — KEY-ONLY cross-committee patient index. Holds non-reversible keyed hashes (patient_key/encounter_key) + governance metadata ONLY — NO names, NO raw MRN, so it is NOT a PHI store (Rule 12 — this layer adds no fourth PHI table). QPS-only: RLS SELECT = app.is_pqs_member; all DML REVOKED from authenticated (maintained by triggers off the 3 PHI tables, served by DEFINER doors). retain-marked-disposed on PHI erasure.';



COMMENT ON COLUMN "public"."patient_xref"."module" IS 'Which isolated PHI module this row mirrors: event | referral | case.';



COMMENT ON COLUMN "public"."patient_xref"."entity_id" IS 'The module-native entity id (event_id / referral_id / case_id).';



COMMENT ON COLUMN "public"."patient_xref"."disposed_reason" IS 'WHY the source PHI was disposed — constrained category (mirrors the *_patient disposal reason), never free text. NULL until disposal. The xref row is RETAINED (keys are non-identifying).';



CREATE TABLE IF NOT EXISTS "public"."pqs_department" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" DEFAULT 'Núcleo de Segurança do Paciente'::"text" NOT NULL,
    "rca_default_due_days" integer DEFAULT 45 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    CONSTRAINT "pqs_department_due_days_positive" CHECK (("rca_default_due_days" >= 1)),
    CONSTRAINT "pqs_department_name_not_blank" CHECK (("btrim"("name") <> ''::"text"))
);


ALTER TABLE "public"."pqs_department" OWNER TO "postgres";


COMMENT ON TABLE "public"."pqs_department" IS 'NSP/PQS-department configuration, ONE ROW PER ORGANIZATION (NSP-per-org, ADR 0042; was a global singleton). Holds that org''s name + RCA default due-window read by triage (14b) / RCA (14c). No PHI.';



CREATE TABLE IF NOT EXISTS "public"."process_template_outcomes" (
    "template_id" "uuid" NOT NULL,
    "outcome_id" "uuid" NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."process_template_outcomes" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" "uuid" NOT NULL,
    "full_name" "text" DEFAULT ''::"text" NOT NULL,
    "is_admin" boolean DEFAULT false NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "email" "extensions"."citext"
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


COMMENT ON TABLE "public"."profiles" IS 'One row per auth user. Never deleted; deactivate via is_active.';



COMMENT ON COLUMN "public"."profiles"."email" IS 'Denormalized copy of auth.users.email; kept fresh by the signup trigger and the auth-email-change sync trigger. Source of truth remains auth.users.';



CREATE SEQUENCE IF NOT EXISTS "public"."referral_code_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE "public"."referral_code_seq" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."referral_patient" (
    "referral_id" "uuid" NOT NULL,
    "name" "text",
    "mrn" "text",
    "date_of_birth" "date",
    "age_years" integer,
    "sex" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "encounter_ref" "text",
    "unit" "text",
    "attending" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "patient_key" "text",
    "encounter_key" "text",
    CONSTRAINT "referral_patient_age_nonneg" CHECK ((("age_years" IS NULL) OR ("age_years" >= 0))),
    CONSTRAINT "referral_patient_sex_check" CHECK (("sex" = ANY (ARRAY['female'::"text", 'male'::"text", 'other'::"text", 'unknown'::"text"])))
);


ALTER TABLE "public"."referral_patient" OWNER TO "postgres";


COMMENT ON TABLE "public"."referral_patient" IS 'ISOLATED PHI (Rule 12; ADR 0037) — the ONLY place referral patient identifiers live. 0..1 per referral (PK = referral_id). Read via the dedicated AUDITED door only (get_referral_patient → referral_patient.read); direct SELECT is REVOKED from authenticated. NEVER selected on list/dashboard paths (minimum-necessary). Modeled exactly on public.event_patient.';



COMMENT ON COLUMN "public"."referral_patient"."patient_key" IS 'ADR 0039 — non-reversible keyed hash of the MRN (see event_patient.patient_key). The key TRAVELS on the referral via this row (no new transport). NOT PHI.';



COMMENT ON COLUMN "public"."referral_patient"."encounter_key" IS 'ADR 0039 — non-reversible keyed hash of the encounter number (see event_patient.encounter_key). NOT PHI.';



CREATE TABLE IF NOT EXISTS "public"."referral_reply" (
    "referral_id" "uuid" NOT NULL,
    "reply_outcome_id" "uuid",
    "outcome_label" "text",
    "result_md" "text",
    "acknowledged_only" boolean DEFAULT false NOT NULL,
    "replied_by" "uuid",
    "replied_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."referral_reply" OWNER TO "postgres";


COMMENT ON TABLE "public"."referral_reply" IS 'The structured reply B delivers (Decision 10). 0..1 per referral; kept SEPARATE from case_referral so list reads never touch the PHI body. Frozen once replied_at is set (guard_referral_reply_lock). A no-reply-expected referral may conclude with acknowledged_only = true and a null result_md.';



COMMENT ON COLUMN "public"."referral_reply"."result_md" IS 'PHI-bearing result narrative (sanitized Markdown). Loaded ONLY via the audited get_referral_detail door; never on list reads; never copied into the audit log (Rule 11/12).';



CREATE TABLE IF NOT EXISTS "public"."referral_types" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "key" "text" NOT NULL,
    "label" "text" NOT NULL,
    "description" "text",
    "color_token" "text",
    "default_response_expected" boolean DEFAULT true NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "referral_types_key_not_blank" CHECK (("btrim"("key") <> ''::"text")),
    CONSTRAINT "referral_types_label_not_blank" CHECK (("btrim"("label") <> ''::"text"))
);


ALTER TABLE "public"."referral_types" OWNER TO "postgres";


COMMENT ON TABLE "public"."referral_types" IS 'Configurable referral-type vocabulary (Phase 22, Decision 8). PHI-free; any-authenticated READ, is_admin()-gated CRUD. default_response_expected pre-fills the send wizard. FK target of case_referral.referral_type_id.';



CREATE TABLE IF NOT EXISTS "public"."reply_outcomes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "key" "text" NOT NULL,
    "label" "text" NOT NULL,
    "description" "text",
    "color_token" "text",
    "position" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "reply_outcomes_key_not_blank" CHECK (("btrim"("key") <> ''::"text")),
    CONSTRAINT "reply_outcomes_label_not_blank" CHECK (("btrim"("label") <> ''::"text"))
);


ALTER TABLE "public"."reply_outcomes" OWNER TO "postgres";


COMMENT ON TABLE "public"."reply_outcomes" IS 'Configurable structured-reply disposition vocabulary (Phase 22, Decision 10). PHI-free; any-authenticated READ, is_admin()-gated CRUD. Seeds procede / nao_procede / requer_acao / inconclusivo. FK target of referral_reply.reply_outcome_id.';



CREATE TABLE IF NOT EXISTS "public"."response_group_instances" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "response_id" "uuid" NOT NULL,
    "group_item_id" "uuid" NOT NULL,
    "parent_instance_id" "uuid",
    "position" integer NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."response_group_instances" OWNER TO "postgres";


COMMENT ON TABLE "public"."response_group_instances" IS 'answer-model-v2 (ADR 0045/0046): repeating-group instance scaffold. INERT until repeating groups ship — no row is written while every answer stays top-level (answers.group_instance_id NULL). RLS mirrors answers (member read; creator write while in_progress); immutability-guarded via guard_submitted_children.';



