CREATE POLICY "profiles_select_self_or_admin" ON "public"."profiles" FOR SELECT TO "authenticated" USING ((("id" = "auth"."uid"()) OR (EXISTS ( SELECT 1
   FROM ("public"."commission_members" "cm"
     JOIN "public"."commissions" "c" ON (("c"."id" = "cm"."commission_id")))
  WHERE (("cm"."user_id" = "profiles"."id") AND "app"."is_org_admin_of"("c"."organization_id")))) OR (EXISTS ( SELECT 1
   FROM ("public"."commission_members" "me"
     JOIN "public"."commission_members" "them" ON (("them"."commission_id" = "me"."commission_id")))
  WHERE (("me"."user_id" = "auth"."uid"()) AND ("them"."user_id" = "profiles"."id"))))));



CREATE POLICY "profiles_update_self" ON "public"."profiles" FOR UPDATE TO "authenticated" USING (("id" = "auth"."uid"())) WITH CHECK (("id" = "auth"."uid"()));



