-- ============================================================================
-- CARRIED: app-schema config DATA + global config vocabularies. The schema dump
-- drops data rows, so the config the app/seed/tests depend on is carried here from
-- the live fully-migrated DB (idempotent). Demo/fixture rows in public.* domain
-- tables are NOT carried — seed.sql is the canonical demo data.
-- ============================================================================

-- feature_flags (14, final enabled-state):
insert into app.feature_flags (key, enabled, description) values ('audit_trail', true, 'When true, the append-only tamper-evident audit trail is live: every instrumented mutation emits one hash-chained audit_log row, sensitive foreign reads/exports emit .read/.export rows, and verify_audit_chain checks integrity. Enabled at Phase 13 completion (Architecture Rule 11).') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('case_access', true, 'When true, the Case Access Control feature (per-case read/write grants via case_access, attribution-driven full-case read computed in app.can_read_case, the narrative assignee + aberta/concluida lifecycle, and the "Meus Casos" list) is live. While OFF, app.can_read_case falls back to is_member_of so the restrictive boundary does not bite. Enabled at Case Access Control completion.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('case_narratives', true, 'When true, the Case Narratives feature (per-commission narrative TYPES, per-template narrative SLOTS interleaved with phases, and per-case de-identified Markdown prose authored inline and frozen on case close) is live. Enabled at Case Narratives completion.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('case_patient', true, 'When true, the Cases module captures an OPTIONAL minimum-necessary set of patient identifiers (the THIRD PHI module; ADR 0038): a per-template collects_patient toggle gates the create-dialog PHI block, identifiers live on the isolated public.case_patient behind the audited single-door get_case_patient (case_patient.read), the read scope is the BROAD can_read_case (assignees need the MRN) while writes stay coordinators-only, and dispose_case_phi provides LGPD erasure. Ships OFF; enabled at feature completion.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('case_phase_results', true, 'When true, the per-phase categorical RESULT feature is live: template phases may carry a result_ruleset, case creation snapshots it + the offered result set, the conclude trigger computes/honors the result, and the end-of-wizard override RPC runs. compute_case_phase_result early-returns when off, so the conclude hook stays a no-op. Record-&-surface only (no routing/gating).') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('case_referrals', true, 'When true, Inter-Committee Case Referrals (Phase 22) are live: a committee sends a frozen point-in-time SNAPSHOT of a case to another committee as a Notification or Analysis Request, the target replies (structured outcome + result, optional linked case), QPS gets the cross-commission macro view, and a source case stays unconcludable while an expected reply is in flight (close_case HC076). Referrals MAY carry isolated PHI on referral_patient behind the audited single-door (Rule 12; ADR 0037). Ships OFF; enabled at Phase 22 completion.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('cases_extras', true, 'When true, the Cases-Extras write RPCs (configurable case status set + set_case_status, documents/events, tags, action items) are live. The modified core phase RPCs keep gating only cases_multi_phase. Enabled at the end of the Cases-Extras batch.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('cases_multi_phase', true, 'When true, the multi-phase cases RPCs (template lifecycle, case creation, phase activation/skip/ad-hoc/reassign/fill, close/cancel, board reads) are live. Enabled at Phase 7 completion.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('interviews', true, 'When true, the Interviews feature (case-scoped interviews of healthcare professionals: scheduling, lifecycle, interviewees + interviewers, evidence attachments, conclusion writing a case_events registry row) is live. Enabled at Phase 11 completion.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('meetings', true, 'When true, the Meetings feature (scheduling, minutes/ata registry, attendance/quorum, cases discussed, action plans, attachments, internal electronic signatures, pending-signatures) is live. Enabled at Phase 10 completion.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('patient_index', true, 'When true, a NON-IDENTIFYING patient-identity layer links the same patient across committees (Phase 23; ADR 0039): a deterministic, non-reversible keyed hash (patient_key/encounter_key = HMAC-SHA256 under the app.app_secrets pepper) is derived by a trigger on the three isolated PHI tables, mirrored into the KEY-ONLY QPS-only public.patient_xref, transmitted on referrals (with a count-only receiver hint), and reassembled into a PHI-free cross-committee trajectory + access audit by QPS-only DEFINER doors — every reassembly audited on the global chain, key-only, never the raw MRN. Adds no fourth PHI store. Ships OFF; enabled at feature completion.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('patient_safety', true, 'When true, the Patient-Safety / NSP module (event intake & hand-off with isolated PHI + a custody ledger [14a], triage [14b], RCA [14c], CAPA [14d]) is live: the notify/acknowledge/transfer/PHI RPCs run, the access-follows-custody RLS + PHI isolation apply, and PHI reads emit .read audit rows (Rule 12). Enabled at Phase 14a completion; the single umbrella flag for all of Phase 14 (ADR 0030).') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('processless_cases', true, 'When true, a coordinator can create a Case with NO process ("Sem processo"): cases.template_id NULL, zero phases at creation (ad-hoc phases grown later via add_ad_hoc_phase), an OPTIONAL hand-picked offered-outcome set, and OPTIONAL patient identifiers. Gates the create-dialog "Sem processo" option + create_case + set_case_offered_outcomes.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;
insert into app.feature_flags (key, enabled, description) values ('signoff_enforcement', true, 'When true, submit_response requires a sign-off row for every visible requires_signoff section. Enabled in Phase 6.') on conflict (key) do update set enabled = excluded.enabled, description = excluded.description;

-- app_secrets (dev mrn_pepper; reset to a real value in prod per ADR 0039):
