-- CARRIED: auth.users triggers (dump excludes the auth schema)
-- Triggers on auth.users (excluded from the public/app schema dump; carried
-- verbatim from the original identity migrations). Profile bootstrap on signup
-- and the denormalized-email sync.
CREATE TRIGGER "on_auth_user_created"
  AFTER INSERT ON "auth"."users"
  FOR EACH ROW EXECUTE FUNCTION "public"."handle_new_user"();

CREATE TRIGGER "on_auth_user_email_changed"
  AFTER UPDATE OF "email" ON "auth"."users"
  FOR EACH ROW EXECUTE FUNCTION "public"."sync_profile_email"();

-- ============================================================================
-- CARRIED: privilege-posture reconciliation (the FINAL, load-bearing carry).
-- pg_dump does NOT re-emit REVOKE-from-default ACLs, so a dump-derived baseline
-- silently re-grants anon and re-opens the isolated-PHI tables + the case_referral
-- column-grant model to authenticated. This block re-asserts the hardened grant
-- posture so the squashed schema is PRIVILEGE-IDENTICAL to the pre-squash history
-- (proven by an empty pre/post pg_dump diff). Mirrors 20260620012000_grants_revoke.sql.
-- RLS + the audited PHI single-doors remain the authority; this is defense in depth.
-- ============================================================================

-- Root cause: stop future public objects auto-granting to anon / PUBLIC.
alter default privileges in schema public revoke all on tables    from anon;
alter default privileges in schema public revoke all on sequences from anon;
alter default privileges in schema public revoke all on functions from anon;
alter default privileges in schema public revoke execute on functions from public;

-- Revoke anon from every existing public table/sequence/function + PUBLIC EXECUTE.
revoke all privileges on all tables    in schema public from anon;
revoke all privileges on all sequences in schema public from anon;
revoke all privileges on all functions in schema public from anon;
revoke execute on all functions in schema public from public;

-- Isolated-PHI tables + patient_xref: ZERO direct authenticated DML (reads via
-- the audited single-door RPCs only; Rule 12 / ADR 0035/0037/0038).
revoke all privileges on table public.event_patient    from authenticated;
revoke all privileges on table public.case_patient     from authenticated;
revoke all privileges on table public.referral_patient from authenticated;
revoke all privileges on table public.patient_xref     from authenticated;

-- case_referral: the default-privilege GRANT ALL to authenticated adds a
-- table-level SELECT the column-grant model forbids (SELECT is per-column only;
-- memory case-referral-column-grants). Revoke the whole authenticated grant, then
-- re-apply the EXACT granular grants (table-level non-SELECT + the 27 column SELECTs).
revoke all privileges on table public.case_referral from authenticated;
GRANT INSERT,REFERENCES,DELETE,TRIGGER,TRUNCATE,MAINTAIN,UPDATE ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("id") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("code") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("source_case_id") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("source_commission_id") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("target_commission_id") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("referral_type_id") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("type_label") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("subject") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("status") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("response_expected") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("target_case_id") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("has_patient") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("created_by") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("sent_at") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("sent_by") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("received_at") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("received_by") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("decided_at") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("decided_by") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("concluded_at") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("concluded_by") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("withdrawn_at") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("withdrawn_by") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("created_at") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("updated_at") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("source_commission_name") ON TABLE "public"."case_referral" TO "authenticated";
GRANT SELECT("target_commission_name") ON TABLE "public"."case_referral" TO "authenticated";

-- Access-token hook: locked to supabase_auth_admin (GoTrue) only.
revoke all on function public.custom_access_token_hook(jsonb) from public, anon, authenticated;
grant execute on function public.custom_access_token_hook(jsonb) to supabase_auth_admin;
